        for (int num : nums) {
            countMap.put(num, countMap.getOrDefault(num, 0) + 1);
        }

        // Sort unique numbers in descending order
        int[] uniqueNums = Arrays.stream(countMap.keySet().toArray(new Integer[0])).mapToInt(Integer::intValue).sorted().distinct().toArray();
