        for (int i = 0; i < n; i++) {
            StringBuilder sb = new StringBuilder(s.substring(i, n) + s.substring(0, i));
            String str1 = "", str2 = "";

            // Generate alternating strings starting with '0' and '1'
            for (int j = 0; j < n; j++) {
