                    str1 += "0";
                    str2 += "1";
                } else {
                    str1 += "1";
                    str2 += "0";
                }
            }

            // Calculate the minimum number of flips required
            int count1 = 0, count2 = 0;
            for (int j = 0; j < n; j++) {
                if (sb.charAt(j) != str1.charAt(j)) {
                    count1++;
                }
                if (sb.charAt(j) != str2.charAt(j)) {
