public class Solution {
    public int carFleet(int target, int[] position, int[] speed) {
        int n = position.length;
        Integer[] ids = new Integer[n];
        for (int i = 0; i < n; i++) {
            ids[i] = i;
        }

        Arrays.sort(ids, Comparator.comparingInt(i -> position[i]));

        double maxTime = -1;
        int fleets = 0;

