public class Solution {
    private static final int MOD = (int) 1e9 + 7;
    private Integer[][] memo;

    public int distinctSequences(int n) {
        memo = new Integer[7][n + 1];
        return dfs(0, -1, n);
    }

    private int dfs(int prev, int prevPrev, int rollsLeft) {
        if (rollsLeft == 0) return 1;
        if (memo[prev][rollsLeft] != null) return memo[prev][rollsLeft];

        int res = 0;
        for (int i = 1; i <= 6; i++) {
            if ((i % prev != 0 || prev == -1) && (i != prevPrev)) {
                res += dfs(i, prev, rollsLeft - 1);
                res %= MOD;
            }
        }

        memo[prev][rollsLeft] = res;
        return res;
    }
}

