public class Solution {
    public int amountOfTime(TreeNode root, int start) {
        if (root == null) return 0;

        int maxDepth = 0;
        dfs(root, start, 0, new boolean[1001], maxDepth);

        return maxDepth;
    }

    private void dfs(TreeNode node, int target, int depth, boolean[] visited, int[] maxDepth) {
        if (node == null || visited[node.val]) return;

        visited[node.val] = true;

        if (node.val == target) {
            maxDepth[0] = Math.max(maxDepth[0], depth);
        } else {
            dfs(node.left, target, depth + 1, visited, maxDepth);
            dfs(node.right, target, depth + 1, visited, maxDepth);
        }

        if (node.val != target) {
            maxDepth[0] = Math.max(maxDepth[0], depth);
        }
    }
}

