            int nextRow = row + directions[dirIndex];
            int nextCol = col + directions[dirIndex + 1];

            if (nextRow < 0 || nextRow >= m || nextCol < 0 || nextCol >= n || matrix[nextRow][nextCol] != -1) {
                dirIndex = (dirIndex + 1) % 4;
            }

            row += directions[dirIndex];
            col += directions[dirIndex + 1];

        }
        return matrix;
    }
