public class Solution {
    public int minimumOperations(int[] nums) {
        int operations = 0;
        while (true) {
            boolean allZeroes = true;
            for (int num : nums) {
                if (num != 0) {
                    allZeroes = false;
                    break;
                }
            }
            if (allZeroes) {
                return operations;
            }

            int minNonZero = Integer.MAX_VALUE;
            for (int num : nums) {
                if (num > 0 && num < minNonZero) {
                    minNonZero = num;
                }
            }

            for (int i = 0; i < nums.length; i++) {
                if (nums[i] > 0) {
                    nums[i] -= minNonZero;
                }
            }
            operations++;
        }
    }
}

