public class Solution {
    public int numberofValidNames(String[] ideas) {
        Map<Character, Set<String>> map = new HashMap<>();
        for (String idea : ideas) {
            char firstChar = idea.charAt(0);
            if (!map.containsKey(firstChar)) {
                map.put(firstChar, new HashSet<>());
            }
            map.get(firstChar).add(idea.substring(1));
        }

        int count = 0;
        Set<String> seen = new HashSet<>();
        for (int i = 0; i < ideas.length; i++) {
            for (int j = i + 1; j < ideas.length; j++) {
                String ideaA = ideas[i];
                String ideaB = ideas[j];

                char firstCharA = ideaA.charAt(0);
                char firstCharB = ideaB.charAt(0);

                if (!map.containsKey(firstCharA) || !map.containsKey(firstCharB)) {
                    continue;
                }

                String newIdeaA = firstCharB + ideaA.substring(1);
                String newIdeaB = firstCharA + ideaB.substring(1);

                if (!map.get(firstCharA).contains(newIdeaB.substring(1)) && !map.get(firstCharB).contains(newIdeaA.substring(1))) {
                    String name = newIdeaA + " " + newIdeaB;
                    if (!seen.contains(name)) {
                        count++;
                        seen.add(name);
                    }
                }
            }
        }

        return count;
    }
}

