public class Solution {
    public String largestPalindromic(String num) {
        int[] count = new int[10];
        for (char c : num.toCharArray()) {
            count[c - '0']++;
        }

        StringBuilder firstHalf = new StringBuilder();
        char middle = ' ';
        for (int i = 9; i >= 0; i--) {
            if (count[i] % 2 == 1 && middle == ' ') {
                middle = (char) ('0' + i);
            }
            int times = count[i] / 2;
            while (times-- > 0) {
                firstHalf.append((char) ('0' + i));
            }
        }

        if (firstHalf.length() == 0 && middle == ' ') {
            return "0";
        }

        StringBuilder secondHalf = new StringBuilder(firstHalf).reverse();
        String result = firstHalf.toString() + (middle != ' ' ? middle : "") + secondHalf.toString();

        // Remove leading zeros
        while (result.length() > 1 && result.charAt(0) == '0') {
            result = result.substring(1);
        }

        return result;
    }
}

