public class Solution {
    public int longestCycle(int[] edges) {
        int n = edges.length;
        boolean[] visited = new boolean[n];
        int maxCycleLength = -1;

        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                int[] distance = new int[n + 1];
                int currentDistance = 1;
                int currentNode = i;

                while (currentNode != -1 && !visited[currentNode]) {
                    visited[currentNode] = true;
                    int nextNode = edges[currentNode];

                    if (nextNode != -1) {
                        if (distance[nextNode] > 0) {
                            maxCycleLength = Math.max(maxCycleLength, currentDistance - distance[nextNode] + 1);
                        } else {
                            distance[nextNode] = currentDistance;
                        }
                    }

                    currentNode = nextNode;
                    currentDistance++;
                }
            }
        }

        return maxCycleLength;
    }
}

