public class Solution {
    public double calculateTax(int[][] brackets, int income) {
        double tax = 0.0;
        int prevUpper = 0;

        for (int[] bracket : brackets) {
            int upper = bracket[0];
            int percent = bracket[1];

            if (income > upper) {
                tax += (upper - prevUpper) * (percent / 100.0);
            } else {
                tax += (income - prevUpper) * (percent / 100.0);
                break;
            }

            prevUpper = upper;
        }

        return tax;
    }
}

