public class Solution {
    public int[][] largestLocal(int[][] grid) {
        int n = grid.length;
        int[][] maxLocal = new int[n - 2][n - 2];

        for (int i = 0; i < n - 2; i++) {
            for (int j = 0; j < n - 2; j++) {
                int maxVal = Integer.MIN_VALUE;

                // Check the 3x3 matrix centered around row i + 1 and column j + 1
                for (int x = i; x <= i + 2; x++) {
                    for (int y = j; y <= j + 2; y++) {
                        maxVal = Math.max(maxVal, grid[x][y]);
                    }
                }

                // Update the maxLocal matrix with the maximum value found
                maxLocal[i][j] = maxVal;
            }
        }

        return maxLocal;
    }
}

