public class Solution {
    public String smallestNumber(String pattern) {
        StringBuilder sb = new StringBuilder();
        int index = 1;

        for (char c : pattern.toCharArray()) {
            if (c == 'I') {
                while (index > 0 && sb.length() > 0 && sb.charAt(sb.length() - 1) < index + '0') {
                    sb.append((char)(index++ + '0'));
                }
                sb.append((char)(index++ + '0'));
            } else if (c == 'D') {
                while (index > 0 && sb.length() > 0 && sb.charAt(sb.length() - 1) < index + '0') {
                    sb.append((char)(index++ + '0'));
                }
                for (int i = index; i >= 1; i--) {
                    if (sb.length() == 0 || sb.charAt(sb.length() - 1) > i + '0') {
                        sb.append((char)(i + '0'));
                        index = i;
                    } else {
                        break;
                    }
                }
            }
        }

        while (index <= 9) {
            if (sb.length() == 0 || sb.charAt(sb.length() - 1) < index + '0') {
                sb.append((char)(index++ + '0'));
            } else {
                break;
            }
        }

        return sb.toString();
    }
}

