public class Solution {
    public int latestTimeCatchTheBus(int[] buses, int[] passengers, int capacity) {
        Arrays.sort(buses);
        Arrays.sort(passengers);

        int lastBus = buses[buses.length - 1];
        boolean isFull = true;
        for (int i = 0; i < passengers.length; i++) {
            if (passengers[i] > lastBus) break;
            if (i == passengers.length - 1 || passengers[i + 1] > lastBus) {
                isFull = false;
                break;
            }
        }

        int latestTime = isFull ? findLatestTimeWhenLastBusIsFull(buses, passengers, capacity) : findLatestTimeWhenLastBusIsNotFull(lastBus);
        return latestTime;
    }

    private int findLatestTimeWhenLastBusIsFull(int[] buses, int[] passengers, int capacity) {
        int lastPassengerIndex = 0;
        for (int i = 0; i < passengers.length; i++) {
            if (passengers[i] > buses[buses.length - 1]) break;
            lastPassengerIndex++;
        }

        int latestTime = passengers[lastPassengerIndex - 1];
        while (latestTime >= 0) {
            boolean canBoard = true;
            for (int passenger : passengers) {
                if (passenger == latestTime) {
                    canBoard = false;
                    break;
                }
            }
            if (canBoard && latestTime <= buses[buses.length - 1]) return latestTime;
            latestTime--;
        }

        return -1; // should not reach here
    }

    private int findLatestTimeWhenLastBusIsNotFull(int lastBus) {
        for (int time = lastBus; time >= 0; time--) {
            boolean canBoard = true;
            for (int passenger : passengers) {
                if (passenger == time) {
                    canBoard = false;
                    break;
                }
            }
            if (canBoard) return time;
        }

        return -1; // should not reach here
    }

    int[] passengers;

