import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int countSubarrays(int[] nums, int k) {
        int n = nums.length;
        int count = 0;

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j <= n; j++) {
                int[] subarray = new int[j - i];
                System.arraycopy(nums, i, subarray, 0, j - i);

                // Sort the subarray
                java.util.Arrays.sort(subarray);

                // Calculate the median of the subarray
                double median;
                if (subarray.length % 2 == 1) {
                    median = subarray[subarray.length / 2];
                } else {
                    median = subarray[(subarray.length - 1) / 2];
                }

                // Check if the median is equal to k
                if ((int) median == k) {
                    count++;
                }
            }
        }

        return count;
    }
}

