import java.util.Arrays;

public class Solution {
    public int deleteGreatestValue(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int ans = 0;

        for (int i = 0; i < n; i++) {
            int[] maxValues = new int[m];

            // Find the maximum value in each row
            for (int j = 0; j < m; j++) {
                int maxValue = Integer.MIN_VALUE;

                // Iterate through the remaining elements in the current column
                for (int k = i; k < n - i; k++) {
                    if (grid[j][k] > maxValue) {
                        maxValue = grid[j][k];
                    }
                }

                maxValues[j] = maxValue;
            }

            // Update the answer with the maximum of deleted elements
            int maxDeletedValue = Arrays.stream(maxValues).max().getAsInt();
            ans += maxDeletedValue;
        }

        return ans;
    }
}

