public class Solution {
    public int deleteString(String s) {
        int n = s.length();
        int[] dp = new int[n + 1];
        for (int i = n - 1; i >= 0; --i) {
            dp[i] = 1;
            for (int j = 1; j <= i; ++j) {
                if (2 * j <= n && s.substring(i - j, i).equals(s.substring(i, i + j))) {
                    dp[i] = Math.max(dp[i], dp[i + j] + 1);
                }
            }
        }
        return dp[0];
    }
