public class Solution {
    public int countDaysTogether(String arriveAlice, String leaveAlice, String arriveBob, String leaveBob) {
        int[] daysInMonth = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};

        int arriveAliceDay = Integer.parseInt(arriveAlice.substring(3)) + 
                             getDaysBeforeMonth(Integer.parseInt(arriveAlice.substring(0, 2)), daysInMonth);

        int leaveAliceDay = Integer.parseInt(leaveAlice.substring(3)) + 
                            getDaysBeforeMonth(Integer.parseInt(leaveAlice.substring(0, 2)), daysInMonth);

        int arriveBobDay = Integer.parseInt(arriveBob.substring(3)) + 
                           getDaysBeforeMonth(Integer.parseInt(arriveBob.substring(0, 2)), daysInMonth);

        int leaveBobDay = Integer.parseInt(leaveBob.substring(3)) + 
                          getDaysBeforeMonth(Integer.parseInt(leaveBob.substring(0, 2)), daysInMonth);

        int maxArriveDay = Math.max(arriveAliceDay, arriveBobDay);
        int minLeaveDay = Math.min(leaveAliceDay, leaveBobDay);

        return Math.max(minLeaveDay - maxArriveDay + 1, 0);
    }

    private int getDaysBeforeMonth(int month, int[] daysInMonth) {
        int sum = 0;
        for (int i = 0; i < month - 1; i++) {
            sum += daysInMonth[i];
        }
        return sum;
    }
}

