        }

        long chemistrySum = 0L;
        int left = 1, right = n - 2;

        while (left < right) {
            if (skill[left] + skill[right] == targetSum) {
                chemistrySum += (long) skill[left] * skill[right];
                left++;
                right--;
            } else if (skill[left] + skill[right] > targetSum) {
                right--;
            } else {
                left++;
            }
        }

        return chemistrySum;
    }

