public class Solution {
    public int boxDelivering(int[][] boxes, int portsCount, int maxBoxes, int maxWeight) {
        int n = boxes.length;
        int[] prefixSum = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] + boxes[i][1];
        }

        int[][] dp = new int[n + 1][n + 1];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                dp[i][j] = Integer.MAX_VALUE;
            }
        }

        dp[0][0] = 0;

        for (int i = 1; i <= n; i++) {
            int ports = 0, weight = 0;
            for (int j = i; j > 0; j--) {
                if (i - j + 1 > maxBoxes || prefixSum[i] - prefixSum[j - 1] > maxWeight) break;

                weight += boxes[j - 1][1];
                if (j < i && boxes[j - 1][0] != boxes[j][0]) ports++;

                dp[i][j] = Math.min(dp[i][j], dp[j - 1][0] + ports + 2);
            }
        }

        return dp[n][n];
    }
}

