                    if (i < m - 1 && grid[i + 1][j] != 0) happiness += 20;
                    if (j > 0 && grid[i][j - 1] != 0) happiness += 20;
                    if (j < n - 1 && grid[i][j + 1] != 0) happiness += 20;
                }
            }
        }

