                return map.get(a) - map.get(b);
            }
        });

        // Create the result array
        int[] result = new int[nums.length];
        int index = 0;
        for (int num : list) {
            int freq = map.get(num);
            while (freq-- > 0) {
                result[index++] = num;
            }
        }

        return result;
    }
}

