import java.util.*;

public class Solution {
    public int[] countSubgraphsForEachDiameter(int n, int[][] edges) {
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }

        // Build the graph
        for (int[] edge : edges) {
            graph[edge[0] - 1].add(edge[1] - 1);
            graph[edge[1] - 1].add(edge[0] - 1);
        }

        int[] result = new int[n - 1];

        // Iterate over all possible subsets of nodes
        for (int mask = 1; mask < (1 << n); mask++) {
            List<Integer> subset = new ArrayList<>();

            // Get the nodes in the current subset
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    subset.add(i);
                }
            }

            int maxDistance = 0;
            boolean isConnected = true;

            // Check if all nodes in the subset are connected
            for (int node : subset) {
                boolean[] visited = new boolean[n];
                Queue<Integer> queue = new LinkedList<>();
                queue.offer(node);
                visited[node] = true;

                while (!queue.isEmpty()) {
                    int current = queue.poll();
                    for (int neighbor : graph[current]) {
                        if ((mask & (1 << neighbor)) != 0 && !visited[neighbor]) {
                            queue.offer(neighbor);
                            visited[neighbor] = true;
                        }
                    }
                }

                // If not all nodes in the subset are connected, break
                for (int i = 0; i < n; i++) {
                    if ((mask & (1 << i)) != 0 && !visited[i]) {
                        isConnected = false;
                        break;
                    }
                }
                if (!isConnected) {
                    break;
                }
            }

            // If the subset is not connected, skip it
            if (!isConnected) {
                continue;
            }

            // Calculate the maximum distance in the subset
            for (int i : subset) {
                boolean[] visited = new boolean[n];
                Queue<int[]> queue = new LinkedList<>();
                queue.offer(new int[]{i, 0});
                visited[i] = true;

                while (!queue.isEmpty()) {
                    int[] current = queue.poll();
                    maxDistance = Math.max(maxDistance, current[1]);
                    for (int neighbor : graph[current[0]]) {
                        if ((mask & (1 << neighbor)) != 0 && !visited[neighbor]) {
                            queue.offer(new int[]{neighbor, current[1] + 1});
                            visited[neighbor] = true;
                        }
                    }
                }
            }

            // Update the result
            if (maxDistance > 0) {
                result[maxDistance - 1]++;
            }
        }

        return result;
    }
}

