import java.util.*;

public class Solution {
    public String findLexSmallestString(String s, int a, int b) {
        HashSet<String> visited = new HashSet<>();
        Queue<String> queue = new LinkedList<>();
        queue.offer(s);
        visited.add(s);

        String result = s;
        while (!queue.isEmpty()) {
            String current = queue.poll();
            if (current.compareTo(result) < 0) {
                result = current;
            }

            // Add a to all odd indices of s
            char[] arr = current.toCharArray();
            for (int i = 1; i < arr.length; i += 2) {
                int num = (arr[i] - '0') + a;
                arr[i] = (char) ((num % 10) + '0');
            }
            String next = new String(arr);
            if (!visited.contains(next)) {
                queue.offer(next);
                visited.add(next);
            }

            // Rotate s to the right by b positions
            int rotateTimes = b % arr.length;
            StringBuilder sb = new StringBuilder();
            for (int i = arr.length - rotateTimes; i < arr.length; i++) {
                sb.append(arr[i]);
            }
            for (int i = 0; i < arr.length - rotateTimes; i++) {
                sb.append(arr[i]);
            }
            next = sb.toString();
            if (!visited.contains(next)) {
                queue.offer(next);
                visited.add(next);
            }
        }

        return result;
    }
}

