public class Solution {
    public int[] decrypt(int[] code, int k) {
        int n = code.length;
        int[] result = new int[n];

        for (int i = 0; i < n; i++) {
            if (k == 0) {
                result[i] = code[i];
            } else if (k > 0) {
                int sum = 0;
                for (int j = 1; j <= k; j++) {
                    sum += code[(i + j) % n];
                }
                result[i] = sum;
            } else {
                int sum = 0;
                for (int j = 1; j <= -k; j++) {
                    sum += code[(n + i - j) % n];
                }
                result[i] = sum;
            }
        }

        return result;
    }
}

