public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int numberOfSets(int n, int k) {
        long[][] dp = new long[n + 1][k + 1];

        for (int i = 0; i <= n; i++) {
            dp[i][0] = 1;
        }

        for (int i = 2; i <= n; i++) {
            for (int j = 1; j <= k && j <= i / 2; j++) {
                for (int l = 1; l <= i - 1; l++) {
                    dp[i][j] = (dp[i][j] + dp[l][j - 1]) % MOD;
