            result[j] = dsu.find(queries[j][0]) == dsu.find(queries[j][1]);
        }

        return result;
    }

    public int find(int num) {
        if (parent[num] != num) {
            parent[num] = find(parent[num]);
        }
        return parent[num];
    }

    private class Dsu {
        private int[] parent;

        public Dsu(int n) {
            parent = new int[n + 1];
            for (int i = 0; i <= n; i++) {
                parent[i] = i;
            }
        }

        public void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX != rootY) {
                parent[rootX] = rootY;
            }
        }

        public int find(int num) {
            if (parent[num] != num) {
                parent[num] = find(parent[num]);
            }
            return parent[num];
        }
    }
}

