public class Solution {
    public int countBinarySubstrings(String s) {
        int count = 0;
        for (int i = 0; i < s.length(); i++) {
            for (int j = i + 1; j <= s.length(); j++) {
                String substring = s.substring(i, j);
                if (isConsecutive(substring)) {
                    count++;
                }
            }
        }
        return count;
    }

    private boolean isConsecutive(String s) {
        int zeros = 0;
        int ones = 0;
        char prevChar = ' ';
        for (char c : s.toCharArray()) {
            if (prevChar != ' ' && prevChar != c) {
                if ((c == '1' && zeros > 0) || (c == '0' && ones > 0)) {
                    continue;
                } else {
                    return false;
                }
            }
            if (c == '0') {
                zeros++;
            } else {
                ones++;
            }
            prevChar = c;
        }
        return zeros == ones && zeros != 0;
    }
}

