public class Solution {
    public boolean judgePoint24(int[] cards) {
        return dfs(cards, 0);
    }

    private boolean dfs(int[] cards, int index) {
        if (index == 3) {
            double result = cards[3];
            return Math.abs(result - 24.0) < 1e-6;
        }

        for (int i = index; i < 4; i++) {
            for (int j = index; j < i; j++) {
                int[] newCards = new int[index + 2];
                System.arraycopy(cards, 0, newCards, 0, index);

                double a = cards[j], b = cards[i];
                newCards[index] = (int) (a + b);
                newCards[index + 1] = (int) (b - a);
                if (dfs(newCards, index + 1)) return true;

                newCards[index] = (int) (a * b);
                newCards[index + 1] = (int) (b / a);
                if (dfs(newCards, index + 1)) return true;

                newCards[index] = (int) (a - b);
                newCards[index + 1] = (int) (a / b);
                if (dfs(newCards, index + 1)) return true;
            }
        }

        return false;
    }
}

