public class Solution {
    public int flipLights(int n, int presses) {
        if (n == 0 || presses == 0) return 1;
        if (n == 1) return presses > 0 ? 2 : 1;
        if (n == 2) return presses > 1 ? 4 : Math.min(presses + 1, 3);
        if (presses >= 3) return 8;
        int[] masks = {15, 9, 10, 6};
        boolean[] seen = new boolean[16];
        dfs(masks, seen, presses, 0);
        int count = 0;
        for (boolean b : seen) if (b) count++;
        return count;
    }

    private void dfs(int[] masks, boolean[] seen, int presses, int state) {
        if (presses == 0) {
            seen[state] = true;
            return;
        }
        for (int mask : masks) {
            dfs(masks, seen, presses - 1, state ^ mask);
        }
    }
}

