// #Medium #Depth_First_Search #Breadth_First_Search #Tree #Binary_Tree
// #2022_03_21_Time_1_ms_(98.04%)_Space_42.4_MB_(79.96%)
import com_github_leetcode.TreeNode;
import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;

public class Solution {
    public List<List<String>> printTree(TreeNode root) {
        int height = getHeight(root);
        int n = (int)Math.pow(2, height + 1) - 1;
        List<List<String>> res = new ArrayList<>();

        for(int i = 0; i <= height; i++) {
            List<String> row = new ArrayList<>();
            for(int j = 0; j < n; j++) {
                row.add("");
            }
            res.add(row);
        }

        dfs(root, 0, (n - 1) / 2, height, res);

        return res;
    }

    private int getHeight(TreeNode root) {
        if(root == null) {
            return -1;
        }
        return Math.max(getHeight(root.left), getHeight(root.right)) + 1;
    }

    private void dfs(TreeNode node, int r, int c, int height, List<List<String>> res) {
        if(node == null) {
            return;
        }

        res.get(r).set(c, String.valueOf(node.val));

        if(node.left != null || node.right != null) {
            dfs(node.left, r + 1, c - (int)Math.pow(2, height - r - 1), height, res);
            dfs(node.right, r + 1, c + (int)Math.pow(2, height - r - 1), height, res);
        }
    }
}

