public class Solution {
    public int[] constructArray(int n, int k) {
        int[] result = new int[n];
        for (int i = 0; i < n - k; i++) {
            result[i] = i + 1;
        }
        boolean isIncreasing = true;
        int left = n - k + 1;
        int right = n;
        for (int i = n - k; i < n; i++) {
            if (isIncreasing) {
                result[i] = left++;
            } else {
                result[i] = right--;
            }
            isIncreasing = !isIncreasing;
        }
        return result;
    }
