    private TreeNode findLCA(TreeNode node, int depth) {
        if (node == null) {
            return null;
        }

        maxDepth = Math.max(maxDepth, depth);

        TreeNode left = findLCA(node.left, depth + 1);
        TreeNode right = findLCA(node.right, depth + 1);

        if (left != null && right != null) {
            return node;
        } else if (depth == maxDepth - 1) {
            return node;
        } else if (left != null) {
            return left;
        } else {
            return right;
        }
    }
