public class Solution {
    public int longestDecomposition(String text) {
        int left = 0, right = text.length() - 1;
        int count = 0;

        while (left < right) {
            int l = left, r = right;
            while (l < r && !text.substring(left, l + 1).equals(text.substring(r, right + 1))) {
                l++;
                r--;
            }

            if (l >= r) break;

            count += 2;
            left = l + 1;
            right = r - 1;
        }

        return left == right ? count + 1 : count;
    }
}

