        // Count the frequency of each character in 'chars'
        for (char c : chars.toCharArray()) {
            charCount.put(c, charCount.getOrDefault(c, 0) + 1);
        }

        int totalLength = 0;

        // Iterate over each word in 'words'
        for (String word : words) {
            Map<Character, Integer> wordCount = new HashMap<>();

            // Count the frequency of each character in the current word
            for (char c : word.toCharArray()) {
                wordCount.put(c, wordCount.getOrDefault(c, 0) + 1);
            }

            boolean isGoodWord = true;

            // Check if the current word can be formed from 'chars'
            for (Map.Entry<Character, Integer> entry : wordCount.entrySet()) {
                char c = entry.getKey();
                int count = entry.getValue();

                if (!charCount.containsKey(c) || count > charCount.get(c)) {
                    isGoodWord = false;
                    break;
                }
            }

            // If the current word can be formed from 'chars', add its length to the total
            if (isGoodWord) {
                totalLength += word.length();
            }
        }

        return totalLength;
    }
}

