public class Solution {
    public long numberOfWeeks(int[] milestones) {
        Arrays.sort(milestones);
        int n = milestones.length;

        if (n == 1 || milestones[n - 2] <= 1) {
            return milestones[n - 1];
        }

        int diff = milestones[n - 1] - milestones[n - 2];
        long weeks = milestones[n - 2] * 2L + Math.min(diff, n - 1);

        if (diff > n - 1) {
            weeks += diff - (n - 1);
        }

        return weeks;
    }
}

