public class Solution {
    public int[] longestObstacleCourseAtEachPosition(int[] obstacles) {
        int n = obstacles.length;
        int[] ans = new int[n];
        int[] tails = new int[n + 1];

        Arrays.fill(tails, Integer.MAX_VALUE);
        tails[0] = -1;

        for (int i = 0; i < n; i++) {
            int left = 0, right = n;
            while (left < right) {
                int mid = left + (right - left) / 2;
                if (tails[mid] <= obstacles[i]) {
                    left = mid + 1;
                } else {
                    right = mid;
                }
            }

            ans[i] = left;
            tails[left] = Math.min(tails[left], obstacles[i]);
        }

        return ans;
    }
}

