// #2022_05_16_Time_73_ms_(49.69%)_Space_73.1_MB_(38.04%)
import java.util.Arrays;
import java.util.PriorityQueue;

public class Solution {
    public int smallestChair(int[][] times, int targetFriend) {
        Arrays.sort(times, (a, b) -> a[0] - b[0]);

        PriorityQueue<Integer> availableChairs = new PriorityQueue<>();
        for (int i = 0; i < times.length * 2; i++) {
            availableChairs.offer(i);
        }

        int[] chairAssignment = new int[times.length];
        Arrays.fill(chairAssignment, -1);

        PriorityQueue<int[]> occupiedChairs = new PriorityQueue<>((a, b) -> a[0] - b[0]);

        for (int i = 0; i < times.length; i++) {
            while (!occupiedChairs.isEmpty() && occupiedChairs.peek()[0] <= times[i][0]) {
                int[] chairInfo = occupiedChairs.poll();
                availableChairs.offer(chairAssignment[chairInfo[1]]);
            }

            if (i == targetFriend) {
                return availableChairs.poll();
            } else {
                chairAssignment[i] = availableChairs.poll();
                occupiedChairs.offer(new int[]{times[i][1], i});
            }
        }

        return -1;
    }
}

