        for (int i = 0; i < 8; i++) {
            if (i == rMove) continue;
            if (board[i][cMove] != '.' && board[i][cMove] != color) {
                boolean isGoodLine = true;
                int count = 1;
                for (int j = Math.min(i, rMove) + 1; j < Math.max(i, rMove); j++) {
                    if (board[j][cMove] == '.') {
                        isGoodLine = false;
                        break;
                    } else if (board[j][cMove] != color) {
                        count++;
                    }
                }
                if (isGoodLine && count >= 2) return true;
            }
        }

        // Check vertical lines
        for (int i = 0; i < 8; i++) {
            if (i == cMove) continue;
            if (board[rMove][i] != '.' && board[rMove][i] != color) {
                boolean isGoodLine = true;
                int count = 1;
                for (int j = Math.min(i, cMove) + 1; j < Math.max(i, cMove); j++) {
                    if (board[rMove][j] == '.') {
                        isGoodLine = false;
                        break;
                    } else if (board[rMove][j] != color) {
                        count++;
                    }
                }
                if (isGoodLine && count >= 2) return true;
            }
        }

        // Check diagonal lines
        for (int i = -7; i <= 7; i++) {
            int x = rMove + i, y = cMove + i;
            if (x < 0 || x > 7 || y < 0 || y > 7) continue;
            if (board[x][y] != '.' && board[x][y] != color) {
                boolean isGoodLine = true;
                int count = 1;
                for (int j = 1; j < Math.abs(i); j++) {
                    int midX = rMove + i / Math.abs(i) * j, midY = cMove + i / Math.abs(i) * j;
                    if (board[midX][midY] == '.') {
                        isGoodLine = false;
                        break;
                    } else if (board[midX][midY] != color) {
                        count++;
                    }
                }
                if (isGoodLine && count >= 2) return true;
            }
        }

        for (int i = -7; i <= 7; i++) {
            int x = rMove + i, y = cMove - i;
            if (x < 0 || x > 7 || y < 0 || y > 7) continue;
            if (board[x][y] != '.' && board[x][y] != color) {
                boolean isGoodLine = true;
                int count = 1;
                for (int j = 1; j < Math.abs(i); j++) {
                    int midX = rMove + i / Math.abs(i) * j, midY = cMove - i / Math.abs(i) * j;
                    if (board[midX][midY] == '.') {
