            for (int j = 0; j < land[0].length; j++) {
                if (land[i][j] == 1) {
                    int[] group = findGroup(land, i, j);
                    result.add(group);
                }
            }
        }
        return result.toArray(new int[result.size()][]);
    }

    private int[] findGroup(int[][] land, int row, int col) {
        int minRow = row;
        int maxRow = row;
        int minCol = col;
        int maxCol = col;

        dfs(land, row, col, minRow, maxRow, minCol, maxCol);

        return new int[] {minRow, minCol, maxRow, maxCol};
    }

    private void dfs(int[][] land, int row, int col, int[] minRow, int[] maxRow, int[] minCol, int[] maxCol) {
        if (row < 0 || row >= land.length || col < 0 || col >= land[0].length || land[row][col] == 0) {
            return;
        }

        minRow[0] = Math.min(minRow[0], row);
        maxRow[0] = Math.max(maxRow[0], row);
        minCol[0] = Math.min(minCol[0], col);
        maxCol[0] = Math.max(maxCol[0], col);

        land[row][col] = 0;

        dfs(land, row - 1, col, minRow, maxRow, minCol, maxCol);
        dfs(land, row + 1, col, minRow, maxRow, minCol, maxCol);
        dfs(land, row, col - 1, minRow, maxRow, minCol, maxCol);
        dfs(land, row, col + 1, minRow, maxRow, minCol, maxCol);
    }
}

