public class Solution {
    public int numberOfRounds(String loginTime, String logoutTime) {
        int startHour = Integer.parseInt(loginTime.substring(0, 2));
        int startMinute = Integer.parseInt(loginTime.substring(3, 5));

        int endHour = Integer.parseInt(logoutTime.substring(0, 2));
        int endMinute = Integer.parseInt(logoutTime.substring(3, 5));

        if (endHour < startHour || (endHour == startHour && endMinute < startMinute)) {
            endHour += 24;
        }

        int startTimeInMinutes = startHour * 60 + startMinute;
        int endTimeInMinutes = endHour * 60 + endMinute;

        int nextRoundStart = ((startTimeInMinutes + 14) / 15) * 15;
        int lastRoundEnd = (endTimeInMinutes / 15) * 15;

        if (nextRoundStart > lastRoundEnd) {
            return 0;
        }

        return (lastRoundEnd - nextRoundStart) / 15;
    }
}

