import java.util.*;

public class Solution {
    public List<List<Long>> splitPainting(int[][] segments) {
        Map<Integer, Long> map = new TreeMap<>();

        for (int[] segment : segments) {
            int start = segment[0];
            int end = segment[1];
            long color = segment[2];

            while (start < end) {
                if (!map.containsKey(start)) {
                    map.put(start, 0L);
                }
                if (!map.containsKey(end)) {
                    map.put(end, 0L);
                }

                Long value = map.get(start);
                map.put(start, value + color);
                value = map.get(end);
                map.put(end, value - color);
                start++;
            }
        }

        List<List<Long>> result = new ArrayList<>();
        long sum = 0;
        long left = -1;

        for (Map.Entry<Integer, Long> entry : map.entrySet()) {
            if (sum != 0) {
                result.add(Arrays.asList((long) left, (long) entry.getKey(), sum));
            }

            sum += entry.getValue();
            if (sum == 0 && !result.isEmpty() && result.get(result.size() - 1).get(1).equals((long) entry.getKey())) {
                continue;
            } else if (sum != 0) {
                left = entry.getKey();
            }
        }

        return result;
    }
}

