// #2022_05_15_Time_87_ms_(48.43%)_Space_145.9_MB_(64.15%)
import com_github_leetcode.TreeNode;
import java.util.ArrayDeque;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Queue;

public class Solution {
    public TreeNode canMerge(List<TreeNode> trees) {
        Map<Integer, TreeNode> map = new HashMap<>();
        for (TreeNode tree : trees) {
            map.put(tree.val, tree);
        }

        int[] count = new int[1];
        Queue<TreeNode> queue = new ArrayDeque<>();
        for (TreeNode tree : trees) {
            if (!hasParent(map, tree)) {
                queue.offer(tree);
                count[0]++;
            }
        }

        if (count[0] != 1) return null;

        TreeNode root = queue.poll();
        while (!queue.isEmpty()) {
            merge(root, queue.poll(), map);
        }

        return isValidBST(root) ? root : null;
    }

    private boolean hasParent(Map<Integer, TreeNode> map, TreeNode tree) {
        if (tree.left != null && map.containsKey(tree.left.val)) return true;
        if (tree.right != null && map.containsKey(tree.right.val)) return true;
        return false;
    }

    private void merge(TreeNode root, TreeNode node, Map<Integer, TreeNode> map) {
        if (node.val < root.val) {
            if (root.left == null) {
                root.left = node;
            } else {
                merge(root.left, node, map);
            }
        } else {
            if (root.right == null) {
                root.right = node;
            } else {
                merge(root.right, node, map);
            }
        }
    }

    private boolean isValidBST(TreeNode root) {
        return isValidBSTHelper(root, Long.MIN_VALUE, Long.MAX_VALUE);
    }

    private boolean isValidBSTHelper(TreeNode root, long minVal, long maxVal) {
        if (root == null) return true;

        if (root.val <= minVal || root.val >= maxVal) return false;

        return isValidBSTHelper(root.left, minVal, root.val) && 
               isValidBSTHelper(root.right, root.val, maxVal);
    }
}

