import java.util.HashMap;
import java.util.Map;

public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int colorTheGrid(int m, int n) {
        Map<String, Integer> memo = new HashMap<>();
        return dfs(m, n, new char[m][n], memo);
    }

    private int dfs(int m, int n, char[][] grid, Map<String, Integer> memo) {
        if (isFull(grid)) {
            return 1;
        }
        String key = toString(grid);
        if (memo.containsKey(key)) {
            return memo.get(key);
        }
        int count = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == '\0') {
                    char[] colors = {'r', 'g', 'b'};
                    for (char color : colors) {
                        if (isValid(grid, i, j, color)) {
                            grid[i][j] = color;
                            count += dfs(m, n, grid, memo);
                            count %= MOD;
                            grid[i][j] = '\0';
                        }
                    }
                    return memo.put(key, count);
                }
            }
        }
        return 0;
    }

    private boolean isValid(char[][] grid, int i, int j, char color) {
        if (i > 0 && grid[i - 1][j] == color) {
            return false;
        }
        if (j > 0 && grid[i][j - 1] == color) {
            return false;
        }
        return true;
    }

    private boolean isFull(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '\0') {
                    return false;
                }
            }
        }
        return true;
    }

    private String toString(char[][] grid) {
        StringBuilder sb = new StringBuilder();
        for (char[] row : grid) {
            for (char cell : row) {
                sb.append(cell);
            }
        }
        return sb.toString();
    }
}

