// #2022_05_21_Time_14_ms_(77.59%)_Space_55.5_MB_(27.59%)
import java.util.*;

public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int countPaths(int n, int[][] roads) {
        List<List<int[]>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }

        for (int[] road : roads) {
            int u = road[0];
            int v = road[1];
            int time = road[2];
            graph.get(u).add(new int[]{v, time});
            graph.get(v).add(new int[]{u, time});
        }

        long[][] dp = new long[n][2];
        for (int i = 0; i < n; i++) {
            Arrays.fill(dp[i], -1);
        }

        return (int) dfs(0, n, graph, dp)[1];
    }

    private long[] dfs(int node, int n, List<List<int[]>> graph, long[][] dp) {
        if (node == n - 1) {
            return new long[]{0, 1};
        }

        if (dp[node][0] != -1) {
            return new long[]{dp[node][0], dp[node][1]};
        }

        long minTime = Long.MAX_VALUE;
        long count = 0;

        for (int[] neighbor : graph.get(node)) {
            int nextNode = neighbor[0];
            int time = neighbor[1];

            long[] result = dfs(nextNode, n, graph, dp);
            if (result[0] + time < minTime) {
                minTime = result[0] + time;
                count = result[1];
            } else if (result[0] + time == minTime) {
                count += result[1];
                count %= MOD;
            }
        }

        dp[node][0] = minTime;
        dp[node][1] = count;

        return new long[]{minTime, count};
    }
}

