import java.util.*;

public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int waysToBuildRooms(int[] prevRoom) {
        int n = prevRoom.length;
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }
        for (int i = 1; i < n; i++) {
            graph.get(prevRoom[i]).add(i);
        }

        long[] dp = new long[n];
        Arrays.fill(dp, -1);

        return (int) dfs(0, graph, dp);
    }

    private long dfs(int node, List<List<Integer>> graph, long[] dp) {
        if (dp[node] != -1) {
            return dp[node];
        }
        int children = 0;
        long result = 1;
        for (int child : graph.get(node)) {
            children++;
            result = (result * dfs(child, graph, dp)) % MOD;
        }

        // Calculate the number of ways to arrange the children
        if (children > 0) {
            result = (result * factorial(children)) % MOD;
        }
        dp[node] = result;
        return result;
    }

    private long factorial(int n) {
        long result = 1;
        for (int i = 2; i <= n; i++) {
            result = (result * i) % MOD;
        }
        return result;
    }
}

