public class Solution {
    public int minSpaceWastedKResizing(int[] nums, int k) {
        int n = nums.length;
        Integer[][] dp = new Integer[n][k + 1];

        return dfs(nums, 0, k, dp);
    }

    private int dfs(int[] nums, int start, int k, Integer[][] dp) {
        if (start >= nums.length) {
            return 0;
        }

        if (dp[start][k] != null) {
            return dp[start][k];
        }

        if (k == 0) {
            int max = nums[start];
            int sum = 0;
            for (int i = start; i < nums.length; i++) {
                max = Math.max(max, nums[i]);
                sum += max - nums[i];
            }
            dp[start][k] = sum;
        } else {
            int min = Integer.MAX_VALUE;
            for (int end = start; end < nums.length; end++) {
                int max = 0;
                int sum = 0;
                for (int i = start; i <= end; i++) {
                    max = Math.max(max, nums[i]);
                    sum += max - nums[i];
                }
                min = Math.min(min, sum + dfs(nums, end + 1, k - 1, dp));
            }
            dp[start][k] = min;
        }

        return dp[start][k];
    }
}

