import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

public class Solution {
    public int minSessions(int[] tasks, int sessionTime) {
        Arrays.sort(tasks);
        reverseArray(tasks);

        int low = 1, high = tasks.length;
        while (low < high) {
            int mid = low + (high - low) / 2;
            if (canFit(tasks, sessionTime, mid)) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }

        return low;
    }

    private boolean canFit(int[] tasks, int sessionTime, int sessions) {
        int[] timeUsed = new int[sessions];
        for (int task : tasks) {
            boolean fit = false;
            for (int i = 0; i < sessions; i++) {
                if (timeUsed[i] + task <= sessionTime) {
                    timeUsed[i] += task;
                    fit = true;
                    break;
                }
            }
            if (!fit) return false;
        }
        return true;
    }

    private void reverseArray(int[] array) {
        int left = 0, right = array.length - 1;
        while (left < right) {
            int temp = array[left];
            array[left] = array[right];
            array[right] = temp;
            left++;
            right--;
        }
    }
}

