public class Solution {
    public long maxPoints(int[][] points) {
        int m = points.length;
        int n = points[0].length;

        // Initialize dp array with the first row of points
        long[] dp = new long[n];
        for (int j = 0; j < n; j++) {
            dp[j] = points[0][j];
        }

        // Iterate over each row starting from the second row
        for (int i = 1; i < m; i++) {
            // Initialize a temporary array to store the maximum points that can be achieved at each column in the current row
            long[] temp = new long[n];

            // Calculate the maximum points that can be achieved at each column in the current row
            for (int j = 0; j < n; j++) {
                long maxPoints = Long.MIN_VALUE;
                for (int k = 0; k < n; k++) {
                    maxPoints = Math.max(maxPoints, dp[k] - Math.abs(k - j));
                }
                temp[j] = maxPoints + points[i][j];
            }

            // Update the dp array with the maximum points that can be achieved at each column in the current row
            System.arraycopy(temp, 0, dp, 0, n);
        }

        // Find the maximum points that can be achieved in the last row
        long maxPoints = Long.MIN_VALUE;
        for (int j = 0; j < n; j++) {
            maxPoints = Math.max(maxPoints, dp[j]);
        }

        return maxPoints;
    }
}

