// #Hard #Array #Dynamic_Programming #Math #Bit_Manipulation #Bitmask
// #2022_05_12_Time_15_ms_(94.29%)_Space_125_MB_(11.43%)
public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int numberOfGoodSubsets(int[] nums) {
        Arrays.sort(nums);
        Map<Integer, Integer> countMap = new HashMap<>();
        for (int num : nums) {
            countMap.put(num, countMap.getOrDefault(num, 0) + 1);
        }

        boolean[] isPrime = new boolean[31];
        Arrays.fill(isPrime, true);
        isPrime[0] = false;
        isPrime[1] = false;
        for (int i = 2; i * i <= 30; i++) {
            if (isPrime[i]) {
                for (int j = i * i; j <= 30; j += i) {
                    isPrime[j] = false;
                }
            }
        }

        int[] primes = new int[8];
        int primeIndex = 0;
        for (int i = 2; i <= 30; i++) {
            if (isPrime[i]) {
                primes[primeIndex++] = i;
            }
        }

        long[] dp = new long[1 << 8];
        dp[0] = countMap.getOrDefault(1, 0);

        for (int num : nums) {
            int mask = getMask(num, primes);
            if (mask == -1) continue;

            for (int i = (1 << 8) - 1; i >= 0; i--) {
                if ((i & mask) == mask) {
                    dp[i] = (dp[i] + dp[i ^ mask]) % MOD;
                }
            }
        }

        long res = 0;
        for (int i = 1; i < (1 << 8); i++) {
            res = (res + dp[i]) % MOD;
        }

        return (int) ((countMap.getOrDefault(1, 0) == 0 ? 0 : countMap.getOrDefault(1, 0)) * res % MOD);
    }

    private int getMask(int num, int[] primes) {
        int mask = 0;
        for (int i = 0; i < primes.length; i++) {
            if (num % primes[i] == 0 && num / primes[i] % primes[i] != 0) {
                mask |= (1 << i);
            } else if (num % primes[i] == 0 && num / primes[i] % primes[i] == 0) {
                return -1;
            }
        }
        return mask;
    }
}

