public class Solution {
    public int latestDayToCross(int row, int col, int[][] cells) {
        int low = 1;
        int high = cells.length;

        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (canReachTopToBottom(row, col, cells, mid)) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        return high;
    }

    private boolean canReachTopToBottom(int row, int col, int[][] cells, int day) {
        boolean[][] visited = new boolean[row][col];
        for (int i = 0; i < day; i++) {
            visited[cells[i][0] - 1][cells[i][1] - 1] = true;
        }

        for (int j = 0; j < col; j++) {
            if (!visited[0][j]) {
                if (dfs(0, j, row, col, visited)) {
                    return true;
                }
            }
        }

        return false;
    }

    private boolean dfs(int x, int y, int row, int col, boolean[][] visited) {
        if (x == row - 1) {
            return true;
        }

        visited[x][y] = true;

        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (int[] direction : directions) {
            int newX = x + direction[0];
            int newY = y + direction[1];

            if (newX >= 0 && newX < row && newY >= 0 && newY < col && !visited[newX][newY]) {
                if (dfs(newX, newY, row, col, visited)) {
                    return true;
                }
            }
        }

        return false;
    }
}

