public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int numberOfCombinations(String num) {
        int n = num.length();
        long[] dp = new long[n + 1];
        dp[0] = 1;

        for (int i = 1; i <= n; i++) {
            if (num.charAt(i - 1) != '0') {
                dp[i] += dp[i - 1];
                dp[i] %= MOD;
            }

            for (int j = 2; j <= i && i - j >= 0; j++) {
                String s1 = num.substring(i - j, i);
                if (s1.charAt(0) == '0' || Integer.parseInt(s1) > Integer.parseInt(num.substring(i - j + 1, i))) {
                    break;
                }

                dp[i] += dp[i - j];
                dp[i] %= MOD;
            }
        }

        return (int) dp[n];
    }
}

