public class Solution {
    public List<List<String>> deleteDuplicateFolder(List<List<String>> paths) {
        Map<String, Node> nodes = new HashMap<>();
        for (List<String> path : paths) {
            Node node = nodes.get("/");
            for (String dir : path) {
                if (!node.children.containsKey(dir)) {
                    node.children.put(dir, new Node());
                }
                node = node.children.get(dir);
            }
        }

        Set<Node> toDelete = new HashSet<>();
        dfs(nodes.get("/"), toDelete);

        List<List<String>> result = new ArrayList<>();
        dfs2(nodes.get("/"), "/", result, toDelete);
        return result;
    }

    private void dfs(Node node, Set<Node> toDelete) {
        Map<String, Node> children = node.children;
        if (children.isEmpty()) {
            node.hash = "null";
        } else {
            List<String> hashes = new ArrayList<>();
            for (Node child : children.values()) {
                dfs(child, toDelete);
                hashes.add(child.hash);
            }
            Collections.sort(hashes);
            node.hash = String.join(",", hashes);
        }

        if (!node.hash.equals("null") && count(node) > 1) {
            toDelete.add(node);
        }
    }

    private int count(Node node) {
        Map<String, Node> children = node.children;
        Set<Node> visited = new HashSet<>();
        return dfs3(node, visited);
    }

    private int dfs3(Node node, Set<Node> visited) {
        if (visited.contains(node)) {
            return 0;
        }
        visited.add(node);

        int count = 1;
        for (Node child : node.children.values()) {
            if (!child.hash.equals("null")) {
                count += dfs3(child, visited);
            }
        }

        return count > 1 ? count : 0;
    }

    private void dfs2(Node node, String path, List<List<String>> result, Set<Node> toDelete) {
        if (toDelete.contains(node)) {
            return;
        }

        result.add(Arrays.asList(path.split("/")));
        for (Map.Entry<String, Node> entry : node.children.entrySet()) {
            dfs2(entry.getValue(), path + "/" + entry.getKey(), result, toDelete);
        }
    }

    private static class Node {
        Map<String, Node> children = new HashMap<>();
        String hash;
    }
}

