public class Solution {
    public long maxProduct(String s) {
        int n = s.length();
        boolean[][] isPalindrome = new boolean[n][n];

        // Initialize a 2D array to store whether each substring is a palindrome or not.
        for (int i = 0; i < n; i++) {
            isPalindrome[i][i] = true;
        }

        // Check for substrings of length 2
        for (int i = 0; i < n - 1; i++) {
            if (s.charAt(i) == s.charAt(i + 1)) {
                isPalindrome[i][i + 1] = true;
            }
        }

        // Check for lengths greater than 2.
        for (int length = 3; length <= n; length++) {
            for (int i = 0; i < n - length + 1; i++) {
                int j = i + length - 1;
                if (s.charAt(i) == s.charAt(j) && isPalindrome[i + 1][j - 1]) {
                    isPalindrome[i][j] = true;
                }
            }
        }

        long maxProduct = 0;

        // Iterate over all possible pairs of non-intersecting substrings.
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (isPalindrome[i][j] && (j - i + 1) % 2 == 1) { // Check if the substring is a palindrome and has an odd length.
                    for (int k = j + 1; k < n; k++) {
                        for (int l = k + 1; l < n; l++) {
                            if (isPalindrome[k][l] && (l - k + 1) % 2 == 1) { // Check if the substring is a palindrome and has an odd length.
                                maxProduct = Math.max(maxProduct, (long)(j - i + 1) * (long)(l - k + 1));
                            }
                        }
                    }
                }
            }
        }

        return maxProduct;
    }
}

