import java.util.*;

public class Solution {
    public int minCost(int maxTime, int[][] edges, int[] passingFees) {
        int n = passingFees.length;
        List<int[]>[] graph = new ArrayList[n];

        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }

        for (int[] edge : edges) {
            graph[edge[0]].add(new int[]{edge[1], edge[2]});
            graph[edge[1]].add(new int[]{edge[0], edge[2]});
        }

        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        boolean[] visited = new boolean[n];
        int[] cost = new int[n];
        Arrays.fill(cost, Integer.MAX_VALUE);

        cost[0] = passingFees[0];
        pq.offer(new int[]{cost[0], 0});

        while (!pq.isEmpty()) {
            int[] current = pq.poll();
            if (visited[current[1]]) continue;

            visited[current[1]] = true;

            for (int[] neighbor : graph[current[1]]) {
                int newCost = current[0] + passingFees[neighbor[0]];
                int newTime = current[0] - passingFees[current[1]] + neighbor[1] + passingFees[neighbor[0]];

                if (newTime <= maxTime && newCost < cost[neighbor[0]]) {
                    cost[neighbor[0]] = newCost;
                    pq.offer(new int[]{cost[neighbor[0]], neighbor[0]});
                }
            }
        }

        return cost[n - 1] == Integer.MAX_VALUE ? -1 : cost[n - 1];
    }
}

