// #Hard #Array #Bit_Manipulation #Trie #2022_05_16_Time_174_ms_(100.00%)_Space_134.4_MB_(85.00%)
public class Solution {
    public int[] maxGeneticDifference(int[] parents, int[][] queries) {
        int n = parents.length;
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }

        for (int i = 0; i < n; i++) {
            if (parents[i] != -1) {
                graph[parents[i]].add(i);
            }
        }

        Map<Integer, List<int[]>> queryMap = new HashMap<>();
        int m = queries.length;
        for (int i = 0; i < m; i++) {
            queryMap.computeIfAbsent(queries[i][0], k -> new ArrayList<>()).add(new int[]{i, queries[i][1]});
        }

        Trie trie = new Trie();
        int[] result = new int[m];

        dfs(graph, queryMap, trie, 0, result);

        return result;
    }

    private void dfs(List<Integer>[] graph, Map<Integer, List<int[]>> queryMap, Trie trie, int node, int[] result) {
        if (queryMap.containsKey(node)) {
            for (int[] query : queryMap.get(node)) {
                result[query[0]] = trie.getMaxXor(query[1]);
            }
        }

        trie.insert(node);

        for (int child : graph[node]) {
            dfs(graph, queryMap, trie, child, result);
        }

        trie.delete(node);
    }

    static class TrieNode {
        TrieNode[] children;

        public TrieNode() {
            this.children = new TrieNode[2];
        }
    }

    static class Trie {
        private TrieNode root;

        public Trie() {
            this.root = new TrieNode();
        }

        public void insert(int num) {
            TrieNode node = root;
            for (int i = 31; i >= 0; i--) {
                int bit = (num >> i) & 1;
                if (node.children[bit] == null) {
                    node.children[bit] = new TrieNode();
                }
                node = node.children[bit];
            }
        }

        public void delete(int num) {
            delete(root, num, 31);
        }

        private boolean delete(TrieNode node, int num, int bitIndex) {
            if (node == null) return false;
            if (bitIndex < 0) return true;

            int bit = (num >> bitIndex) & 1;
            if (!delete(node.children[bit], num, bitIndex - 1)) return false;

            node.children[bit] = null;
            return node.children[1 - bit] == null;
        }

        public int getMaxXor(int num) {
            TrieNode node = root;
            int result = 0;
            for (int i = 31; i >= 0; i--) {
                int bit = (num >> i) & 1;
                if (node.children[1 - bit] != null) {
                    result |= (1 << i);
                    node = node.children[1 - bit];
                } else {
                    node = node.children[bit];
                }
            }
            return result;
        }
    }
}

