public class Solution {
    public long maxAlternatingSum(int[] nums) {
        int n = nums.length;
        long[][] dp = new long[n][2];

        // Initialize the base case for the first element.
        dp[0][0] = 0; // Even index sum
        dp[0][1] = -nums[0]; // Odd index sum

        for (int i = 1; i < n; i++) {
            // For even indices, we can either include or exclude the current element.
            dp[i][0] = Math.max(dp[i-1][0], dp[i-1][1] + nums[i]);

            // For odd indices, we can either include or exclude the current element.
            dp[i][1] = Math.max(dp[i-1][1], dp[i-1][0] - nums[i]);
        }

        return Math.max(dp[n-1][0], dp[n-1][1]);
    }
}

