import java.util.HashSet;

public class Solution {
    public int longestCommonSubpath(int n, int[][] paths) {
        int low = 1;
        int high = Math.min(paths[0].length, paths[paths.length - 1].length);

        while (low <= high) {
            int mid = low + (high - low) / 2;

            if (isCommonSubpath(mid, paths)) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        return high;
    }

    private boolean isCommonSubpath(int length, int[][] paths) {
        HashSet<String> set = new HashSet<>();

        for (int i = 0; i <= paths[0].length - length; i++) {
            StringBuilder sb = new StringBuilder();

            for (int j = i; j < i + length; j++) {
                sb.append(paths[0][j]);
                if (j != i + length - 1) {
                    sb.append(",");
                }
            }

            set.add(sb.toString());
        }

        for (int i = 1; i < paths.length; i++) {
            HashSet<String> tempSet = new HashSet<>();

            for (int j = 0; j <= paths[i].length - length; j++) {
                StringBuilder sb = new StringBuilder();

                for (int k = j; k < j + length; k++) {
                    sb.append(paths[i][k]);
                    if (k != j + length - 1) {
                        sb.append(",");
                    }
                }

                tempSet.add(sb.toString());
            }

            set.retainAll(tempSet);

            if (set.isEmpty()) {
                return false;
            }
        }

        return !set.isEmpty();
    }
}

