        maxCount = Math.max(maxCount, countMap.get(node.val));
        dfs(node.left, countMap, maxCount);
        dfs(node.right, countMap, maxCount);
    }

    private void updateResult(Map<Integer, Integer> countMap, int maxCount, List<Integer> result) {
