            return memo.get(key);
        }
        int maxPoints = (k + 1) * (k + 1) + dfs(boxes, left + 1, right, 0);
        for (int i = left + 1; i <= right; i++) {
            if (boxes[left] == boxes[i]) {
                maxPoints = Math.max(maxPoints, dfs(boxes, left + 1, i - 1, 0) + dfs(boxes, i, right, k + 1));
            }
        }
        memo.put(key, maxPoints);
        return maxPoints;
    }
}

