import java.util.ArrayDeque;
import java.util.Deque;

public class Solution {
    public boolean isValid(String code) {
        if (code.isEmpty() || !code.startsWith("<") || !code.endsWith(">")) return false;

        Deque<String> stack = new DequeArray<>();
        int i = 0, n = code.length();

        while (i < n) {
            // Check for CDATA
            if (i + 9 <= n && code.substring(i, i + 9).equals("<![CDATA[")) {
                int j = code.indexOf("]]>", i);
                if (j == -1) return false;
                i = j + 3;
            } 
            // Check for start tag
            else if (code.charAt(i) == '<' && i + 1 < n && Character.isUpperCase(code.charAt(i + 1))) {
                int j = code.indexOf('>', i);
                if (j == -1) return false;
                String tagName = code.substring(i + 1, j);
                if (!isValidTagName(tagName)) return false;
                stack.push(tagName);
                i = j + 1;
            } 
            // Check for end tag
            else if (code.charAt(i) == '<' && i + 2 < n && code.charAt(i + 1) == '/' && Character.isUpperCase(code.charAt(i + 2))) {
                int j = code.indexOf('>', i);
                if (j == -1 || stack.isEmpty() || !stack.pop().equals(code.substring(i + 2, j))) return false;
                i = j + 1;
            } 
            // Check for invalid characters
            else if (code.charAt(i) == '<') {
                return false;
            } 
            // Skip other characters
            else {
                i++;
            }
        }

        return stack.isEmpty();
    }

    private boolean isValidTagName(String tagName) {
        int len = tagName.length();
        return len >= 1 && len <= 9 && tagName.matches("[A-Z]+");
    }
}

