public class Solution {
    public boolean checkInclusion(String s1, String s2) {
        if (s1.length() > s2.length()) return false;

        Map<Character, Integer> s1Count = new HashMap<>();
        for (char c : s1.toCharArray()) {
            s1Count.put(c, s1Count.getOrDefault(c, 0) + 1);
        }

        Map<Character, Integer> windowCount = new HashMap<>();
        int left = 0;
        for (int right = 0; right < s2.length(); right++) {
            char c = s2.charAt(right);
            windowCount.put(c, windowCount.getOrDefault(c, 0) + 1);

            if (right - left + 1 == s1.length()) {
                if (isPermutation(s1Count, windowCount)) return true;
                char leftChar = s2.charAt(left);
                windowCount.put(leftChar, windowCount.get(leftChar) - 1);
                if (windowCount.get(leftChar) == 0) windowCount.remove(leftChar);
                left++;
            }
        }

        return false;
    }

    private boolean isPermutation(Map<Character, Integer> s1Count, Map<Character, Integer> windowCount) {
        for (char c : s1Count.keySet()) {
            if (!windowCount.containsKey(c) || !s1Count.get(c).equals(windowCount.get(c))) return false;
        }
        return true;
    }
}

