public class Solution {
    public int nextGreaterElement(int n) {
        char[] digits = String.valueOf(n).toCharArray();
        int len = digits.length;

        // Find k
        int k = len - 2;
        while (k >= 0 && digits[k] >= digits[k + 1]) {
            k--;
        }

        if (k < 0) return -1;

        // Find l
        int l = len - 1;
        while (l > k && digits[l] <= digits[k]) {
            l--;
        }

        // Swap digits[k] and digits[l]
        char temp = digits[k];
        digits[k] = digits[l];
        digits[l] = temp;

        // Reverse the substring from index k + 1 to len - 1
        int left = k + 1;
        int right = len - 1;
        while (left < right) {
            temp = digits[left];
            digits[left] = digits[right];
            digits[right] = temp;
            left++;
            right--;
        }

        // Convert the char array back to an integer
        long ret = Long.parseLong(new String(digits));

        // Handle the case if ret > Integer.MAX_VALUE
        return (ret > Integer.MAX_VALUE) ? -1 : (int) ret;
    }
}

