public class Solution {
    public int findMinMoves(int[] machines) {
        int n = machines.length;
        int totalDresses = 0;

        // Calculate the total number of dresses and check if it's possible to distribute them evenly
        for (int machine : machines) {
            totalDresses += machine;
        }

        if (totalDresses % n != 0) {
            return -1; // It's not possible to make all washing machines have the same number of dresses
        }

        int target = totalDresses / n;
        int maxMoves = 0;
        int currentImbalance = 0;

        for (int machine : machines) {
            currentImbalance += machine - target;
            maxMoves = Math.max(maxMoves, Math.abs(currentImbalance));
            maxMoves = Math.max(maxMoves, machine - target);
        }

        return maxMoves;
    }
}

