public class Solution {
    public char[][] updateBoard(char[][] board, int[] click) {
        int m = board.length;
        int n = board[0].length;
        int x = click[0];
        int y = click[1];

        if (board[x][y] == 'M') {
            board[x][y] = 'X';
            return board;
        }

        dfs(board, x, y);
        return board;
    }

    private void dfs(char[][] board, int x, int y) {
        int m = board.length;
        int n = board[0].length;

        if (x < 0 || x >= m || y < 0 || y >= n || board[x][y] != 'E') {
            return;
        }

        int count = countMines(board, x, y);
        if (count > 0) {
            board[x][y] = (char) ('0' + count);
            return;
        }

        board[x][y] = 'B';
        dfs(board, x - 1, y);
        dfs(board, x + 1, y);
        dfs(board, x, y - 1);
        dfs(board, x, y + 1);
        dfs(board, x - 1, y - 1);
        dfs(board, x - 1, y + 1);
        dfs(board, x + 1, y - 1);
        dfs(board, x + 1, y + 1);
    }

    private int countMines(char[][] board, int x, int y) {
        int m = board.length;
        int n = board[0].length;
        int count = 0;

        for (int i = -1; i <= 1; i++) {
            for (int j = -1; j <= 1; j++) {
                int nx = x + i;
                int ny = y + j;
                if (nx < 0 || nx >= m || ny < 0 || ny >= n) {
                    continue;
                }
                if (board[nx][ny] == 'M') {
                    count++;
                }
            }
        }

        return count;
    }
}

