public class Solution {
    public int[][] matrixReshape(int[][] mat, int r, int c) {
        int m = mat.length;
        int n = mat[0].length;

        // Check if the reshape operation is possible and legal
        if (m * n != r * c) {
            return mat;
        }

        // Initialize a new reshaped matrix with zeros
        int[][] reshapedMat = new int[r][c];

        // Fill the reshaped matrix in row-traversing order
        int index = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                reshapedMat[index / c][index % c] = mat[i][j];
                index++;
            }
        }

        return reshapedMat;
    }
}

