// #2022_07_25_Time_8_ms_(95.63%)_Space_42.9_MB_(87.34%)
import java.util.*;

public class Solution {
    public int findRotateSteps(String ring, String key) {
        int n = ring.length(), m = key.length();
        List<Integer>[] pos = new ArrayList[26];
        for (int i = 0; i < 26; ++i) pos[i] = new ArrayList<>();
        for (int i = 0; i < n; ++i) 
            pos[ring.charAt(i) - 'a'].add(i);

        int[][] dp = new int[m + 1][n];
        for (int[] d : dp) Arrays.fill(d, Integer.MAX_VALUE / 2);
        dp[0][0] = 0;

        for (int i = 1; i <= m; ++i) {
            for (int j : pos[key.charAt(i - 1) - 'a']) {
                for (int k = 0; k < n; ++k) {
                    int diff = Math.abs(j - k);
                    dp[i][j] = Math.min(dp[i][j], dp[i - 1][k] + Math.min(diff, n - diff) + 1);
                }
            }
        }

        return Arrays.stream(dp[m]).min().getAsInt();
    }
}

