public class Solution {
    public int countArrangement(int n) {
        boolean[] visited = new boolean[n + 1];
        int[] result = new int[1];
        backtrack(result, visited, 1, n);
        return result[0];
    }

    private void backtrack(int[] result, boolean[] visited, int index, int n) {
        if (index == n + 1) {
            result[0]++;
            return;
        }
        for (int i = 1; i <= n; i++) {
            if (!visited[i] && (i % index == 0 || index % i == 0)) {
                visited[i] = true;
                backtrack(result, visited, index + 1, n);
                visited[i] = false;
            }
        }
    }
}

