public class Solution {
    public String nearestPalindromic(String n) {
        long num = Long.parseLong(n);
        long res = -1;
        long diff = Long.MAX_VALUE;

        // Check for 9...99, 999...999 etc.
        long firstCandidate = (long) Math.pow(10, n.length() - 1) - 1;
        if (isPalindrome(firstCandidate) && num - firstCandidate < diff) {
            res = firstCandidate;
            diff = num - firstCandidate;
        } else if (isPalindrome(firstCandidate) && num - firstCandidate == diff) {
            res = Math.min(res, firstCandidate);
        }

        // Check for 1...11, 111...111 etc.
        long secondCandidate = (long) Math.pow(10, n.length()) + 1;
        if (isPalindrome(secondCandidate) && secondCandidate - num < diff) {
            res = secondCandidate;
            diff = secondCandidate - num;
        } else if (isPalindrome(secondCandidate) && secondCandidate - num == diff) {
            res = Math.min(res, secondCandidate);
        }

        // Check for numbers with same digits
        long thirdCandidate = getSameDigits(num, n.length());
        if (thirdCandidate != num && isPalindrome(thirdCandidate)) {
            if (Math.abs(num - thirdCandidate) < diff) {
                res = thirdCandidate;
                diff = Math.abs(num - thirdCandidate);
            } else if (Math.abs(num - thirdCandidate) == diff) {
                res = Math.min(res, thirdCandidate);
            }
        }

        // Check for numbers with same digits but one less or more
        long fourthCandidate = getSameDigits(num + 1, n.length());
        if (fourthCandidate != num && isPalindrome(fourthCandidate)) {
            if (Math.abs((num + 1) - fourthCandidate) < diff) {
                res = fourthCandidate;
                diff = Math.abs((num + 1) - fourthCandidate);
            } else if (Math.abs((num + 1) - fourthCandidate) == diff) {
                res = Math.min(res, fourthCandidate);
            }
        }

        long fifthCandidate = getSameDigits(num - 1, n.length());
        if (fifthCandidate != num && isPalindrome(fifthCandidate)) {
            if (Math.abs((num - 1) - fifthCandidate) < diff) {
                res = fifthCandidate;
                diff = Math.abs((num - 1) - fifthCandidate);
            } else if (Math.abs((num - 1) - fifthCandidate) == diff) {
                res = Math.min(res, fifthCandidate);
            }
        }

        return String.valueOf(res);
    }

    private boolean isPalindrome(long num) {
        long temp = num;
        long reverse = 0;

        while (temp > 0) {
            reverse = reverse * 10 + temp % 10;
            temp /= 10;
        }

        return num == reverse;
    }

    private long getSameDigits(long num, int length) {
        String strNum = String.valueOf(num);
        char firstDigit = strNum.charAt(0);

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < length; i++) {
            sb.append(firstDigit);
        }

        return Long.parseLong(sb.toString());
    }
}

