import java.util.Arrays;

public class Solution {
    public int findCircleNum(int[][] arr) {
        int n = arr.length;
        boolean[] visited = new boolean[n];

        int count = 0;
        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                dfs(arr, visited, i);
                count++;
            }
        }
        return count;
    }

    private void dfs(int[][] arr, boolean[] visited, int node) {
        visited[node] = true;

        for (int neighbor = 0; neighbor < arr.length; neighbor++) {
            if (arr[node][neighbor] == 1 && !visited[neighbor]) {
                dfs(arr, visited, neighbor);
            }
        }
    }
}

