        if (num <= 0) return false;

        int sum = 1; // since 1 is a divisor of every number

        for (int i = 2; i * i <= num; i++) {
            if (num % i == 0) {
                sum += i;
                if (i != num / i) { // to avoid adding the square root twice
                    sum += num / i;
                }
            }
        }

        return sum == num;
    }
}

