import java.util.Arrays;
public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int findPaths(int m, int n, int maxMove, int startRow, int startColumn) {
        Integer[][][] memo = new Integer[m][n][maxMove + 1];

        return dfs(m, n, maxMove, startRow, startColumn, memo);
    }

    private int dfs(int m, int n, int maxMove, int row, int col, Integer[][][] memo) {
        if (row < 0 || row >= m || col < 0 || col >= n) return 1;

        if (maxMove == 0) return 0;

        if (memo[row][col][maxMove] != null) return memo[row][col][maxMove];

        int count = 0;

        count += dfs(m, n, maxMove - 1, row + 1, col, memo);
        count += dfs(m, n, maxMove - 1, row - 1, col, memo);
        count += dfs(m, n, maxMove - 1, row, col + 1, memo);
        count += dfs(m, n, maxMove - 1, row, col - 1, memo);

        return memo[row][col][maxMove] = (count % MOD);
    }
}

