import java.util.Arrays;

public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int checkRecord(int n) {
        long[][][] dp = new long[n + 1][2][3];

        // Initialize the base case
        dp[0][0][0] = 1;

        for (int i = 1; i <= n; i++) {
            // If the student was present on the previous day
            dp[i][0][0] = (dp[i - 1][0][0] + dp[i - 1][0][1] + dp[i - 1][0][2]) % MOD;

            // If the student was late on the previous day and has not been absent before
            dp[i][0][1] = dp[i - 1][0][0];

            // If the student was late on the previous two days and has not been absent before
            dp[i][0][2] = dp[i - 1][0][1];

            // If the student was present on the previous day and has been absent once before
            dp[i][1][0] = (dp[i - 1][1][0] + dp[i - 1][1][1] + dp[i - 1][1][2]) % MOD;

            // If the student was late on the previous day and has been absent once before
            dp[i][1][1] = dp[i - 1][1][0];

            // If the student was late on the previous two days and has been absent once before
            dp[i][1][2] = dp[i - 1][1][1];
        }

        long result = (dp[n][0][0] + dp[n][0][1] + dp[n][0][2] + dp[n][1][0] + dp[n][1][1] + dp[n][1][2]) % MOD;

        return (int) result;
    }
}

