public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int numOfWays(int[] nums) {
        return dfs(nums);
    }

    private int dfs(int[] nums) {
        if (nums.length <= 2) {
            return 1;
        }

        int root = nums[0];
        int leftSize = 0, rightSize = 0;
        for (int num : nums) {
            if (num < root) {
                leftSize++;
            } else if (num > root) {
                rightSize++;
            }
        }

        int[] left = new int[leftSize], right = new int[rightSize];
        int li = 0, ri = 0;
        for (int i = 1; i < nums.length; i++) {
            if (nums[i] < root) {
                left[li++] = nums[i];
            } else if (nums[i] > root) {
                right[ri++] = nums[i];
            }
        }

        long res = dfs(left) * (long) dfs(right);
        res %= MOD;

        // calculate the number of ways to arrange left and right subtrees
        res *= comb(leftSize + rightSize, leftSize);
        res %= MOD;

        return (int) res;
    }

    private long comb(int n, int k) {
        long res = 1;
        for (int i = 1; i <= k; i++) {
            res = res * (n - i + 1) / i;
        }
        return res;
    }
}

