// #Hard #String #Sorting #Greedy #2022_04_11_Time_20_ms_(97.22%)_Space_54.4_MB_(72.22%)
public class Solution {
    public boolean isTransformable(String s, String t) {
        if (s.length() != t.length()) return false;

        Map<Character, Deque<Integer>> indexMap = new HashMap<>();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            indexMap.computeIfAbsent(c, k -> new ArrayDeque<>()).addLast(i);
        }

        int[] indices = new int[s.length()];
        Arrays.fill(indices, -1);

        for (int i = 0; i < t.length(); i++) {
            char c = t.charAt(i);
            if (!indexMap.containsKey(c) || indexMap.get(c).isEmpty()) return false;

            int index = indexMap.get(c).removeFirst();
            indices[i] = index;

            for (char key : indexMap.keySet()) {
                while (!indexMap.get(key).isEmpty() && indices[indexMap.get(key).peekFirst()] != -1) {
                    indexMap.get(key).removeFirst();
                }
            }
        }

        int[] sortedIndices = Arrays.copyOf(indices, indices.length);
        Arrays.sort(sortedIndices);

        for (int i = 0; i < sortedIndices.length; i++) {
            if (sortedIndices[i] != i) return false;
        }

        return true;
    }
}

