import java.util.Arrays;
public class Solution {
    public int[][] outerTrees(int[][] trees) {
        Arrays.sort(trees, (a, b) -> a[0] == b[0] ? a[1] - b[1] : a[0] - b[0]);

        int n = trees.length;
        int[] hull = new int[n * 2];
        int p = 0;

        for (int i = 0; i < n; i++) {
            while (p >= 2 && cross(hull[p - 2], hull[p - 1], trees[i]) > 0) p--;
            hull[p++] = i;
        }

        for (int i = n - 2, t = p + 1; i >= 0; i--) {
            while (p >= t && cross(hull[p - 2], hull[p - 1], trees[i]) > 0) p--;
            hull[p++] = i;
        }

        int[][] res = new int[p - 1][2];
        for (int i = 0; i < p - 1; i++) {
            res[i] = trees[hull[i]];
        }

        return res;
    }

    private int cross(int a, int b, int c) {
        int[] A = {trees[a][0], trees[a][1]};
        int[] B = {trees[b][0], trees[b][1]};
        int[] C = {trees[c][0], trees[c][1]};

        return (B[0] - A[0]) * (C[1] - A[1]) - (B[1] - A[1]) * (C[0] - A[0]);
    }

    private int[][] trees;
}

