public class Solution {
    public int unhappyFriends(int n, int[][] preferences, int[][] pairs) {
        Map<Integer, Integer> pairMap = new HashMap<>();

        // Create a map to store the pairing of each friend
        for (int[] pair : pairs) {
            pairMap.put(pair[0], pair[1]);
            pairMap.put(pair[1], pair[0]);
        }

        int unhappyCount = 0;

        // Iterate over each friend's preferences
        for (int i = 0; i < n; i++) {
            boolean isUnhappy = false;

            // Check if the current friend is unhappy
            for (int preference : preferences[i]) {
                // If the preferred friend prefers the current friend more than their own pair
                if (pairMap.containsKey(preference) && 
                    getPreferenceIndex(preferences[preference], i) < getPreferenceIndex(preferences[preference], pairMap.get(preference)))) {
                    isUnhappy = true;
                    break;
                }
            }

            // If the current friend is unhappy, increment the count
            if (isUnhappy) {
                unhappyCount++;
            }
        }

        return unhappyCount;
    }

    private int getPreferenceIndex(int[] preferences, int target) {
        for (int i = 0; i < preferences.length; i++) {
            if (preferences[i] == target) {
                return i;
            }
        }
        return -1; // Not found
    }
}

