import java.util.HashMap;

public class Solution {
    public int minSubarray(int[] nums, int p) {
        int sum = 0;
        for (int num : nums) {
            sum += num;
        }

        if (sum % p == 0) return 0;

        int target = sum % p;
        HashMap<Integer, Integer> prefixSumMap = new HashMap<>();
        prefixSumMap.put(0, -1);
        int currentSum = 0;
        int minLen = nums.length + 1;

        for (int i = 0; i < nums.length; i++) {
            currentSum += nums[i];
            if (prefixSumMap.containsKey((currentSum - target + p) % p)) {
                minLen = Math.min(minLen, i - prefixSumMap.get((currentSum - target + p) % p));
            }
            prefixSumMap.put(currentSum % p, i);
        }

        return minLen <= nums.length ? minLen : -1;
    }
}

