// #Hard #Array #Dynamic_Programming #Matrix #Bit_Manipulation #Bitmask
// #2022_04_07_Time_74_ms_(64.83%)_Space_41.4_MB_(96.55%)
import java.util.Arrays;
import java.util.List;

public class Solution {
    public int connectTwoGroups(List<List<Integer>> cost) {
        int m = cost.size();
        int n = cost.get(0).size();
        int[] record = new int[1 << n];
        Arrays.fill(record, Integer.MAX_VALUE);
        record[0] = 0;

        for (int i = 0; i < m; i++) {
            int[] tmpRecord = new int[record.length];
            Arrays.fill(tmpRecord, Integer.MAX_VALUE);

            for (int mask = 0; mask < (1 << n); mask++) {
                if (record[mask] == Integer.MAX_VALUE) continue;
                for (int j = 0; j < n; j++) {
                    tmpRecord[mask | (1 << j)] = Math.min(tmpRecord[mask | (1 << j)], record[mask] + cost.get(i).get(j));
                }
            }

            int[] newRecord = new int[record.length];
            Arrays.fill(newRecord, Integer.MAX_VALUE);
            for (int mask = 0; mask < (1 << n); mask++) {
                if ((mask & -mask) == mask) {
                    newRecord[mask] = tmpRecord[mask];
                } else {
                    for (int subMask = mask; subMask > 0; subMask = (subMask - 1) & mask) {
                        if ((subMask & -subMask) == subMask && tmpRecord[subMask] != Integer.MAX_VALUE) {
                            newRecord[mask] = Math.min(newRecord[mask], tmpRecord[subMask]);
                        }
                    }
                }
            }

            record = newRecord;
        }

        return record[(1 << n) - 1];
    }
}

