public class Solution {
    public int minSwaps(int[][] grid) {
        int n = grid.length;
        int[] zeros = new int[n];

        // Count the number of trailing zeros in each row
        for (int i = 0; i < n; i++) {
            int count = 0;
            for (int j = n - 1; j >= 0; j--) {
                if (grid[i][j] == 0) {
                    count++;
                } else {
                    break;
                }
            }
            zeros[i] = count;
        }

        int swaps = 0;

        // Try to find a row with enough trailing zeros for each column
        for (int i = 0; i < n; i++) {
            boolean found = false;
            for (int j = i; j < n; j++) {
                if (zeros[j] >= n - i - 1) {
                    // Swap rows to move the row with enough trailing zeros up
                    for (int k = j; k > i; k--) {
                        int temp = zeros[k];
                        zeros[k] = zeros[k - 1];
                        zeros[k - 1] = temp;
                    }
                    swaps += j - i;
                    found = true;
                    break;
                }
            }
            if (!found) {
                return -1; // or throw an exception, depending on the requirements
            }
        }

        return swaps;
    }
}

