// #Medium #Depth_First_Search #Tree #Binary_Tree
// #2022_04_09_Time_3_ms_(94.18%)_Space_52.2_MB_(60.26%)
import com_github_leetcode.TreeNode;

public class Solution {
    public int countPairs(TreeNode root, int distance) {
        int[] res = new int[1];
        dfs(root, distance, res);
        return res[0];
    }

    private void dfs(TreeNode node, int distance, int[] res) {
        if (node == null) return;

        if (node.left == null && node.right == null) {
            // leaf node
            dfsLeaf(node, distance, res);
            return;
        }

        dfs(node.left, distance, res);
        dfs(node.right, distance, res);
    }

    private void dfsLeaf(TreeNode node, int distance, int[] res) {
        if (node == null) return;

        if (node.left == null && node.right == null) {
            // leaf node
            dfsHelper(node, 0, distance, res);
            return;
        }

        dfsLeaf(node.left, distance, res);
        dfsLeaf(node.right, distance, res);
    }

    private void dfsHelper(TreeNode node, int depth, int distance, int[] res) {
        if (node == null || depth > distance) return;

        if (depth > 0 && node.left == null && node.right == null) {
            // leaf node
            res[0]++;
            return;
        }

        dfsHelper(node.left, depth + 1, distance, res);
        dfsHelper(node.right, depth + 1, distance, res);
    }
}

