    public String modifyString(String s) {
        char[] chars = s.toCharArray();
        for (int i = 0; i < chars.length; i++) {
            if (chars[i] == '?') {
                if (i > 0 && chars[i - 1] != 'a' && (i == chars.length - 1 || chars[i + 1] != 'a')) {
                    chars[i] = 'a';
                } else if (i > 0 && chars[i - 1] != 'b' && (i == chars.length - 1 || chars[i + 1] != 'b')) {
                    chars[i] = 'b';
                } else {
                    chars[i] = 'c';
                }
            }
        }
        return new String(chars);
    }
}

