import java.util.Arrays;

public class Solution {
    public String minInteger(String num, int k) {
        char[] chars = num.toCharArray();
        for (int i = 0; i < chars.length; i++) {
            if (k == 0) break;
            int j = i + 1;
            while (j < chars.length && k > 0) {
                if (chars[j] < chars[i]) {
                    char temp = chars[i];
                    for (int l = i; l < j; l++) {
                        chars[l] = chars[l + 1];
                    }
                    chars[j] = temp;
                    k--;
                    break;
                } else {
                    j++;
                }
            }
        }
        return new String(chars);
    }
}

