// #Hard #Array #Depth_First_Search #Breadth_First_Search #Matrix #Strongly_Connected_Component
// #2022_04_11_Time_1_ms_(100.00%)_Space_41.8_MB_(91.49%)
import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int minDays(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        boolean[][] visited = new boolean[m][n];

        // Function to check if the grid is connected
        boolean isConnected(boolean[][] grid) {
            int count = 0;
            for (int i = 0; i < m; i++) {
                for (int j = 0; j < n; j++) {
                    if (grid[i][j] == 1 && !visited[i][j]) {
                        dfs(grid, visited, i, j);
                        count++;
                    }
                }
            }
            return count <= 1;
        }

        // Function to perform DFS
        void dfs(boolean[][] grid, boolean[][] visited, int x, int y) {
            if (x < 0 || x >= m || y < 0 || y >= n || grid[x][y] == 0 || visited[x][y]) return;
            visited[x][y] = true;
            dfs(grid, visited, x - 1, y);
            dfs(grid, visited, x + 1, y);
            dfs(grid, visited, x, y - 1);
            dfs(grid, visited, x, y + 1);
        }

        // Check if the grid is already disconnected
        int islandCount = 0;
        boolean[][] tempVisited = new boolean[m][n];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1 && !tempVisited[i][j]) {
                    dfs(grid, tempVisited, i, j);
                    islandCount++;
                }
            }
        }

        // If the grid is already disconnected, return 0
        if (islandCount > 1) return 0;

        // Try to disconnect the grid by removing each land cell
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    boolean[][] newGrid = new boolean[m][n];
                    for (int k = 0; k < m; k++) {
                        System.arraycopy(grid[k], 0, newGrid[k], 0, n);
                    }
                    newGrid[i][j] = false;
                    if (!isConnected(newGrid)) return 1;
                }
            }
        }

        // If we cannot disconnect the grid by removing one land cell, return 2
        return 2;
    }
}

