// #Medium #Array #Hash_Table #Greedy #Prefix_Sum
// #2022_04_11_Time_56_ms_(71.58%)_Space_89_MB_(38.59%)
import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int maxNonOverlapping(int[] nums, int target) {
        Map<Integer, Integer> prefixSum = new HashMap<>();
        prefixSum.put(0, -1);
        int sum = 0;
        int count = 0;
        boolean[] seen = new boolean[nums.length];

        for (int i = 0; i < nums.length; i++) {
            sum += nums[i];
            if (prefixSum.containsKey(sum - target) && !seen[prefixSum.get(sum - target) + 1]) {
                count++;
                for (int j = prefixSum.get(sum - target) + 1; j <= i; j++) {
                    seen[j] = true;
                }
            }
            prefixSum.putIfAbsent(sum, i);
        }

        return count;
    }
}

