import java.util.*;

public class Solution {
    public double maxProbability(int n, int[][] edges, double[] succProb, int start, int end) {
        List<List<int[]>> graph = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }

        for (int i = 0; i < edges.length; i++) {
            int u = edges[i][0];
            int v = edges[i][1];
            double p = succProb[i];

            graph.get(u).add(new int[] {v, (int) (p * 100000)});
            graph.get(v).add(new int[] {u, (int) (p * 100000)});
        }

        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> b[1] - a[1]);
        boolean[] visited = new boolean[n];

        pq.offer(new int[] {start, 100000});

        while (!pq.isEmpty()) {
            int[] curr = pq.poll();
            int node = curr[0];
            int prob = curr[1];

            if (node == end) {
                return prob / 100000.0;
            }

            visited[node] = true;

            for (int[] neighbor : graph.get(node)) {
                if (!visited[neighbor[0]]) {
                    pq.offer(new int[] {neighbor[0], Math.min(prob, neighbor[1])});
                }
            }
        }

        return 0.0;
    }
}

