// #Hard #Dynamic_Programming #Memoization #2022_04_11_Time_5_ms_(91.90%)_Space_43.5_MB_(31.90%)
import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int minDays(int n) {
        Map<Integer, Integer> memo = new HashMap<>();
        return dfs(n, memo);
    }

    private int dfs(int n, Map<Integer, Integer> memo) {
        if (n == 0) return 0;
        if (memo.containsKey(n)) return memo.get(n);

        int res = dfs(n - 1, memo) + 1;

        if (n % 2 == 0) {
            res = Math.min(res, dfs(n / 2, memo) + 1);
        }

        if (n % 3 == 0) {
            res = Math.min(res, dfs(n - 2 * (n / 3), memo) + 1);
        }

        memo.put(n, res);
        return res;
    }
}

