public class Solution {
    public int minOperations(int[] nums) {
        int operations = 0;
        boolean hasNonZero = true;

        while (hasNonZero) {
            hasNonZero = false;

            for (int i = 0; i < nums.length; i++) {
                if (nums[i] % 2 == 1) {
                    nums[i]--;
                    operations++;
                }
            }

            boolean allZero = true;
            for (int num : nums) {
                if (num != 0) {
                    hasNonZero = true;
                    allZero = false;
                    break;
                }
            }

            if (!allZero) {
                operations += 1;
                for (int i = 0; i < nums.length; i++) {
                    nums[i] /= 2;
                }
            }
        }

        return operations;
    }
}

