public class Solution {
    public int minCost(String s, int[] cost) {
        int totalCost = 0;
        int i = 0;

        while (i < s.length()) {
            int j = i + 1;

            // Find consecutive balloons with the same color
            while (j < s.length() && s.charAt(j) == s.charAt(i)) {
                j++;
            }

            // If there are no consecutive balloons with the same color, move to the next balloon
            if (j - i == 1) {
                i = j;
                continue;
            }

            // Calculate the total cost of removing all but one balloon in the group
            int groupCost = 0;
            for (int k = i; k < j; k++) {
                groupCost += cost[k];
            }

            // Remove the balloons with the lowest costs to minimize the total cost
            int maxCostInGroup = Integer.MIN_VALUE;
            for (int k = i; k < j; k++) {
                if (cost[k] > maxCostInGroup) {
                    maxCostInGroup = cost[k];
                }
            }

            // Subtract the maximum cost in the group from the total cost of the group
            totalCost += groupCost - maxCostInGroup;

            i = j;
        }

        return totalCost;
    }
}

