public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int numOfSubarrays(int[] arr) {
        int countOdd = 0, countEven = 0;
        int sum = 0;
        int result = 0;

        for (int num : arr) {
            sum += num;

            if (sum % 2 == 1) {
                result = (result + countEven + 1) % MOD;
                countOdd++;
            } else {
                result = (result + countOdd) % MOD;
                countEven++;
            }
        }

        return result;
    }
}

