public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int rangeSum(int[] nums, int n, int left, int right) {
        int len = n * (n + 1) / 2;
        int[] sums = new int[len];
        int idx = 0;

        for (int i = 0; i < n; i++) {
            int sum = 0;
            for (int j = i; j < n; j++) {
                sum += nums[j];
                sums[idx++] = sum;
            }
        }

        Arrays.sort(sums);
        long res = 0;

        for (int i = left - 1; i <= right - 1; i++) {
            res = (res + sums[i]) % MOD;
        }

        return (int) res;
    }
}

