        int maxLen = 0;
        int positiveCount = 0;
        int negativeCount = 0;

        for (int num : nums) {
            if (num == 0) {
                positiveCount = 0;
                negativeCount = 0;
            } else if (num > 0) {
                positiveCount++;
                if (negativeCount != 0) {
                    negativeCount++;
                }
            } else {
                int temp = positiveCount;
                positiveCount = negativeCount == 0 ? 0 : negativeCount + 1;
                negativeCount = temp + 1;
            }

            maxLen = Math.max(maxLen, positiveCount);
        }

        return maxLen;
