// #Medium #Hash_Table #Depth_First_Search #Breadth_First_Search #Tree #Counting
// #2022_04_09_Time_60_ms_(98.13%)_Space_107.7_MB_(97.66%)
public class Solution {
    public int[] countSubTrees(int n, int[][] edges, String labelsString) {
        // Create adjacency list for the tree
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }

        // Populate adjacency list
        for (int[] edge : edges) {
            adj.get(edge[0]).add(edge[1]);
            adj.get(edge[1]).add(edge[0]);
        }

        char[] labels = labelsString.toCharArray();
        int[] result = new int[n];

        // Perform DFS to count subtrees with the same label
        dfs(0, -1, adj, labels, result);

        return result;
    }

    private Map<Character, Integer> dfs(int node, int parent, List<List<Integer>> adj, char[] labels, int[] result) {
        Map<Character, Integer> count = new HashMap<>();
        count.put(labels[node], 1);

        for (int child : adj.get(node)) {
            if (child != parent) {
                Map<Character, Integer> childCount = dfs(child, node, adj, labels, result);
                for (char key : childCount.keySet()) {
                    count.put(key, count.getOrDefault(key, 0) + childCount.get(key));
                }
            }
        }

        result[node] = count.get(labels[node]);
        return count;
    }
}

