// #Hard #Array #Matrix #Graph #Topological_Sort
// #2022_04_11_Time_12_ms_(90.00%)_Space_53.9_MB_(71.25%)
import java.util.HashSet;
import java.util.Set;

public class Solution {
    public boolean isPrintable(int[][] targetGrid) {
        int m = targetGrid.length, n = targetGrid[0].length;
        int[] colorBound = new int[61];
        for (int i = 0; i < 61; i++) {
            colorBound[i] = -1;
        }

        // find the color range for each color
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                int color = targetGrid[i][j];
                if (colorBound[color] == -1) {
                    colorBound[color] = i;
                }
                colorBound[color + 30] = Math.max(colorBound[color + 30], i);
                colorBound[color * 2] = Math.min(colorBound[color * 2] == -1 ? Integer.MAX_VALUE : colorBound[color * 2], j);
                colorBound[color * 2 + 1] = Math.max(colorBound[color * 2 + 1] == -1 ? Integer.MIN_VALUE : colorBound[color * 2 + 1], j);
            }
        }

        // DFS all the colors, skip the color already be printed
        for (int i = 1; i <= 60; i++) {
            if (colorBound[i] != -1) {
                boolean[][] visited = new boolean[m][n];
                if (!dfs(targetGrid, colorBound, visited, i)) return false;
            }
        }

        // if all color has been printed, then return true
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (targetGrid[i][j] != 0) return false;
            }
        }

        return true;
    }

    private boolean dfs(int[][] targetGrid, int[] colorBound, boolean[][] visited, int color) {
        int m = targetGrid.length, n = targetGrid[0].length;
        for (int i = colorBound[color]; i <= colorBound[color + 30]; i++) {
            for (int j = colorBound[color * 2]; j <= colorBound[color * 2 + 1]; j++) {
                if (i < 0 || i >= m || j < 0 || j >= n) continue;
                if (visited[i][j]) continue;

                visited[i][j] = true;
                // if we find a different color, then check if the color is already printed, if so,
                // return false
                if (targetGrid[i][j] != 0 && targetGrid[i][j] != color) {
                    int newColor = targetGrid[i][j];
                    if (colorBound[newColor + 30] == -1 || colorBound[newColor * 2] == -1) continue;
                    if (!dfs(targetGrid, colorBound, visited, newColor)) return false;
                }
            }
        }

        // mark the color as printed
        for (int i = colorBound[color]; i <= colorBound[color + 30]; i++) {
            for (int j = colorBound[color * 2]; j <= colorBound[color * 2 + 1]; j++) {
                if (i < 0 || i >= m || j < 0 || j >= n) continue;
                targetGrid[i][j] = 0;
            }
        }

        // reset the color bound
        colorBound[color] = -1;
        colorBound[color + 30] = -1;
        colorBound[color * 2] = -1;
        colorBound[color * 2 + 1] = -1;

        return true;
    }
}

