            for (int end = start; end < n; end++) {
                charToLastIndex.put(s.charAt(end), lastOccurrence.get(s.charAt(end)));

                int maxEnd = Collections.max(charToLastIndex.values());

                if (end == maxEnd) {
                    result.add(s.substring(start, end + 1));
                    start = end + 1;
                    break;
                }
            }
        }

        return result;
    }
}

