public class Solution {
    public int minOperations(int n) {
        // Calculate the target value which is the average of all elements in the array
        int target = (n - 1) / 2;

        // Initialize the count of operations
        int operations = 0;

        // Iterate over the first half of the array
        for (int i = 0; i <= target; i++) {
            // Calculate the difference between the current element and the target value
            int diff = (2 * i) + 1 - target;

            // Add the difference to the count of operations
            operations += diff;
        }

        return operations;
