public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int maxProductPath(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        long[][] maxDp = new long[m][n];
        long[][] minDp = new long[m][n];

        maxDp[0][0] = grid[0][0];
        minDp[0][0] = grid[0][0];

        for (int i = 1; i < m; i++) {
            maxDp[i][0] = maxDp[i - 1][0] * grid[i][0];
            minDp[i][0] = minDp[i - 1][0] * grid[i][0];
        }

        for (int j = 1; j < n; j++) {
            maxDp[0][j] = maxDp[0][j - 1] * grid[0][j];
            minDp[0][j] = minDp[0][j - 1] * grid[0][j];
        }

        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                long upMax = maxDp[i - 1][j];
                long upMin = minDp[i - 1][j];
                long leftMax = maxDp[i][j - 1];
                long leftMin = minDp[i][j - 1];

                if (grid[i][j] < 0) {
                    maxDp[i][j] = Math.max(upMin, leftMin) * grid[i][j];
                    minDp[i][j] = Math.min(upMax, leftMax) * grid[i][j];
                } else {
                    maxDp[i][j] = Math.max(upMax, leftMax) * grid[i][j];
                    minDp[i][j] = Math.min(upMin, leftMin) * grid[i][j];
                }
            }
        }

        if (maxDp[m - 1][n - 1] < 0) {
            return -1;
        } else {
            return (int) (maxDp[m - 1][n - 1] % MOD);
        }
    }

    public static class Tuple {
        long a;
        long b;

        public Tuple(long a, long b) {
            this.a = a;
            this.b = b;
        }
    }
}

