public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int numWays(String s) {
        int countOnes = 0;
        for (char c : s.toCharArray()) {
            if (c == '1') {
                countOnes++;
            }
        }

        if (countOnes % 3 != 0) {
            return 0;
        }

        if (countOnes == 0) {
            long totalWays = (long) (s.length() - 1) * (s.length() - 2) / 2;
            return (int) (totalWays % MOD);
        }

        int onesPerPart = countOnes / 3;
        int firstCut = 0, secondCut = 0;
        int onesCounted = 0;

        for (char c : s.toCharArray()) {
            if (c == '1') {
                onesCounted++;
            }

            if (onesCounted == onesPerPart) {
                firstCut++;
            } else if (onesCounted == 2 * onesPerPart) {
                secondCut++;
            }
        }

        return (int) ((long) firstCut * secondCut % MOD);
    }
}

