public class Solution {
    public int getLengthOfOptimalCompression(String s, int k) {
        int n = s.length();
        int[][] dp = new int[n + 1][k + 1];

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= k; j++) {
                dp[i][j] = n;
            }
        }

        dp[0][0] = 0;

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= Math.min(i, k); j++) {
                if (j > 0) {
                    dp[i][j] = dp[i - 1][j - 1];
                }

                int count[ ] = new int[26];
                int del = 0;

                for (int l = i; l >= 1; l--) {
                    if (s.charAt(l - 1) != s.charAt(i - 1)) {
                        del++;
                    }

                    count[s.charAt(l - 1) - 'a']++;

                    if (del <= j) {
                        int len = dp[l - 1][j - del] + 1;

                        if (count[s.charAt(i - 1) - 'a'] > 1) {
                            len += String.valueOf(count[s.charAt(i - 1) - 'a']).length() - 1;
                        }

                        dp[i][j] = Math.min(dp[i][j], len);
                    }
                }
            }
        }

        return dp[n][k];
    }
}

