public class Solution {
    public boolean containsCycle(char[][] grid) {
        int m = grid.length;
        int n = grid[0].length;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (dfs(grid, i, j, -1, -1, 0)) {
                    return true;
                }
            }
        }

        return false;
    }

    private boolean dfs(char[][] grid, int x, int y, int px, int py, int step) {
        if (step >= 4 && x == px && y == py) {
            return true;
        }

        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (int[] direction : directions) {
            int nx = x + direction[0];
            int ny = y + direction[1];

            if (nx >= 0 && nx < grid.length && ny >= 0 && ny < grid[0].length
                    && grid[nx][ny] == grid[x][y]
                    && !(nx == px && ny == py)) {
                if (dfs(grid, nx, ny, x, y, step + 1)) {
                    return true;
                }
            }
        }

        return false;
    }
}

