public class Solution {
    public int findLengthOfShortestSubarray(int[] arr) {
        int n = arr.length;

        // Handle edge cases
        if (n == 0 || n == 1) return 0;

        // Find the first decreasing element from the left
        int left = 0;
        while (left < n - 1 && arr[left] <= arr[left + 1]) {
            left++;
        }

        // If no decreasing element is found, array is already non-decreasing
        if (left == n - 1) return 0;

        // Find the first increasing element from the right
        int right = n - 1;
        while (right > 0 && arr[right] >= arr[right - 1]) {
            right--;
        }

        // Initialize minimum length of subarray to remove
        int minLen = Math.min(n - left - 1, right);

        // Try to find a longer non-decreasing subarray by moving the pointers
        int i = 0;
        int j = right;
        while (i <= left && j < n) {
            if (arr[i] <= arr[j]) {
                minLen = Math.min(minLen, j - i - 1);
                i++;
            } else {
                j++;
            }
        }

        return minLen;
    }
}

