    public int longestAwesome(String s) {
        int n = s.length();
        int res = 0;
        Map<Integer, Integer> map = new HashMap<>();
        map.put(0, -1);
        int mask = 0;

        for (int i = 0; i < n; i++) {
            mask ^= 1 << (s.charAt(i) - '0');
            res = Math.max(res, i + 1);

            if (map.containsKey(mask)) {
