            for (int j = 0; j < 10; j++) {
                int newMask = mask ^ (1 << j);
                if (map.containsKey(newMask)) {
                    res = Math.max(res, i - map.get(newMask));
                }
            }

            if (!map.containsKey(mask)) {
                map.put(mask, i);
            }
        }

