import java.util.Arrays;

public class Solution {
    public int minCost(int n, int[] cuts) {
        int len = cuts.length;
        Arrays.sort(cuts);

        // Add the start and end points of the stick to the array
        int[] newCuts = new int[len + 2];
        newCuts[0] = 0;
        System.arraycopy(cuts, 0, newCuts, 1, len);
        newCuts[len + 1] = n;

        // Initialize a 2D array to store the minimum cost for each subproblem
        int[][] dp = new int[len + 2][len + 2];

        // Fill up the dp table in a bottom-up manner
        for (int i = len; i >= 0; i--) {
            for (int j = i + 1; j <= len + 1; j++) {
                if (j - i == 1) {
                    // Base case: no cuts needed
                    dp[i][j] = 0;
                } else {
                    int minCost = Integer.MAX_VALUE;
                    for (int k = i + 1; k < j; k++) {
                        // Calculate the cost of cutting at position k
                        int cost = newCuts[j] - newCuts[i] + dp[i][k] + dp[k][j];
                        minCost = Math.min(minCost, cost);
                    }
                    dp[i][j] = minCost;
                }
            }
        }

        // The minimum total cost is stored in dp[0][len + 1]
        return dp[0][len + 1];
    }
}

