public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int countRoutes(int[] locations, int start, int finish, int fuel) {
        Map<String, Integer> memo = new HashMap<>();
        return dfs(locations, start, finish, fuel, memo);
    }

    private int dfs(int[] locations, int currentCity, int finish, int remainingFuel, Map<String, Integer> memo) {
        if (remainingFuel < 0) {
            return 0;
        }

        String key = currentCity + "," + remainingFuel;
        if (memo.containsKey(key)) {
            return memo.get(key);
        }

        int count = currentCity == finish ? 1 : 0;

        for (int nextCity = 0; nextCity < locations.length; nextCity++) {
            if (nextCity != currentCity) {
                int fuelConsumed = Math.abs(locations[currentCity] - locations[nextCity]);
                count = (count + dfs(locations, nextCity, finish, remainingFuel - fuelConsumed, memo)) % MOD;
            }
        }

        memo.put(key, count);
        return count;
    }
}

