public class Solution {
    public int findLatestStep(int[] arr, int m) {
        int n = arr.length;
        int[] lengths = new int[n + 2];
        int latestStep = -1;

        for (int i = 1; i <= n; i++) {
            int index = arr[i - 1];
            int leftLength = lengths[index - 1];
            int rightLength = lengths[index + 1];

            if (leftLength == m || rightLength == m) {
                latestStep = i - 1;
            }

            lengths[index - leftLength] = lengths[index + rightLength] = leftLength + rightLength + 1;

            if (leftLength + rightLength + 1 == m) {
                latestStep = i;
            }
        }

        return latestStep;
    }
}

