public class Solution {
    public int findKthPositive(int[] arr, int k) {
        int left = 0;
        int right = arr.length - 1;

        while (left <= right) {
            int mid = left + (right - left) / 2;

            // Calculate the number of missing integers up to arr[mid]
            int missingCount = arr[mid] - mid - 1;

            if (missingCount < k) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }

        // If we exit the loop, it means that the kth missing integer is not in the array
        // So, we calculate it as arr[left] - (left + 1) + k
        return left + k;
    }
}

