public class Solution {
    public List<Integer> mostVisited(int n, int[] rounds) {
        int m = rounds.length;
        int[] count = new int[n];

        for (int i = 0; i < m - 1; i++) {
            if (rounds[i] <= rounds[i + 1]) {
                for (int j = rounds[i]; j <= rounds[i + 1]; j++) {
                    count[j - 1]++;
                }
            } else {
                for (int j = rounds[i]; j <= n; j++) {
                    count[j - 1]++;
                }
                for (int j = 1; j <= rounds[i + 1]; j++) {
                    count[j - 1]++;
                }
            }
        }

        // Count the last round
        if (rounds[m - 2] <= rounds[m - 1]) {
            for (int j = rounds[m - 2]; j <= rounds[m - 1]; j++) {
                count[j - 1]++;
            }
        } else {
