            for (int j = 1; j <= rounds[m - 1]; j++) {
                count[j - 1]++;
            }
        }

        int maxCount = Arrays.stream(count).max().getAsInt();

        List<Integer> result = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (count[i] == maxCount) {
                result.add(i + 1);
