public class Solution {
    public int maxSumRangeQuery(int[] nums, int[][] requests) {
        final int MOD = (int) 1e9 + 7;
        int n = nums.length;
        int[] count = new int[n];

        for (int[] request : requests) {
            int start = request[0];
            int end = request[1];
            count[start]++;
            if (end + 1 < n) {
                count[end + 1]--;
            }
        }

        for (int i = 1; i < n; i++) {
            count[i] += count[i - 1];
        }

        Arrays.sort(count);
        Arrays.sort(nums);

        long res = 0;
        for (int i = 0; i < n; i++) {
            res = (res + (long) nums[i] * count[n - i - 1]) % MOD;
        }

        return (int) res;
    }
