// #2022_04_11_Time_36_ms_(95.56%)_Space_54.3_MB_(17.78%)
public class Solution {
    public int stoneGameV(int[] stoneValue) {
        int n = stoneValue.length;
        int[][] dp = new int[n][n];
        int[] prefixSum = new int[n + 1];

        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] + stoneValue[i];
        }

        for (int length = 2; length <= n; length++) {
            for (int left = 0; left <= n - length; left++) {
                int right = left + length - 1;
                dp[left][right] = Integer.MIN_VALUE;

                for (int k = left; k < right; k++) {
                    int leftSum = prefixSum[k + 1] - prefixSum[left];
                    int rightSum = prefixSum[right + 1] - prefixSum[k + 1];

                    if (leftSum < rightSum) {
                        dp[left][right] = Math.max(dp[left][right], leftSum + dp[left][k]);
                    } else if (leftSum > rightSum) {
                        dp[left][right] = Math.max(dp[left][right], rightSum + dp[k + 1][right]);
                    } else {
                        dp[left][right] = Math.max(dp[left][right], Math.max(leftSum + dp[left][k], rightSum + dp[k + 1][right]));
                    }
                }
            }
        }

        return dp[0][n - 1];
    }
}

