import java.util.Arrays;

public class Solution {
    public int maxNumEdgesToRemove(int n, int[][] edges) {
        UnionFind alice = new UnionFind(n);
        UnionFind bob = new UnionFind(n);

        int count = 0;
        // First add type 3 edges
        for (int[] edge : edges) {
            if (edge[0] == 3 && !alice.union(edge[1], edge[2])) {
                bob.union(edge[1], edge[2]);
                count++;
            }
        }

        // Then add type 1 and type 2 edges
        for (int[] edge : edges) {
            if (edge[0] == 1 && !alice.union(edge[1], edge[2])) {
                count++;
            } else if (edge[0] == 2 && !bob.union(edge[1], edge[2])) {
                count++;
            }
        }

        // Check if the graph is fully traversed by both Alice and Bob
        if (alice.count != 1 || bob.count != 1) {
            return -1;
        }

        return edges.length - count;
    }

    class UnionFind {
        int[] parent;
        int[] rank;
        int count;

        public UnionFind(int n) {
            parent = new int[n + 1];
            rank = new int[n + 1];
            for (int i = 1; i <= n; i++) {
                parent[i] = i;
            }
            count = n;
        }

        public int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        public boolean union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);

            if (rootX == rootY) {
                return false;
            }

            if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }

            count--;
            return true;
        }
    }
}

