public class Solution {
    public boolean hasTrailingZeros(int[] nums) {
        for (int i = 0; i < nums.length; i++) {
            for (int j = i + 1; j < nums.length; j++) {
                if ((nums[i] | nums[j]) % 2 == 0) {
                    return true;
                }
            }
        }

        // Check all possible combinations of three or more elements
        for (int mask = 3; mask < (1 << nums.length); mask++) {
            int orResult = 0;
            for (int i = 0; i < nums.length; i++) {
                if ((mask & (1 << i)) != 0) {
                    orResult |= nums[i];
                }
            }
            if (orResult % 2 == 0) {
                return true;
            }
        }

        return false;
    }
}

