import java.util.*;

public class Solution {
    public int minCost(String source, String target, char[] original, char[] changed, int[] cost) {
        if (source.length() != target.length()) return -1;

        Map<Character, List<int[]>> graph = new HashMap<>();
        for (int i = 0; i < original.length; i++) {
            graph.computeIfAbsent(original[i], k -> new ArrayList<>()).add(new int[]{changed[i], cost[i]});
        }

        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[1] - b[1]);
        Map<String, Integer> visited = new HashMap<>();
        pq.offer(new int[]{0, 0});
        visited.put(source, 0);

        while (!pq.isEmpty()) {
            int[] current = pq.poll();
            String str = source;
            for (int i = 0; i < current[0]; i++) {
                str = str.substring(0, i) + target.charAt(i) + str.substring(i + 1);
            }

            if (str.equals(target)) return current[1];

            for (int i = current[0]; i < source.length(); i++) {
                if (source.charAt(i) != target.charAt(i)) {
                    List<int[]> neighbors = graph.getOrDefault(source.charAt(i), new ArrayList<>());
                    for (int[] neighbor : neighbors) {
                        String nextStr = str.substring(0, i) + neighbor[0] + str.substring(i + 1);
                        int nextCost = current[1] + neighbor[1];
                        if (!visited.containsKey(nextStr) || visited.get(nextStr) > nextCost) {
                            pq.offer(new int[]{i + 1, nextCost});
                            visited.put(nextStr, nextCost);
                        }
                    }
                }
            }
        }

        return -1;
    }
}

