import java.util.*;

public class Solution {
    public List<String> getWordsInLongestSubsequence(int n, String[] words, int[] groups) {
        // Create a graph where each node is an index in the words array
        Map<Integer, List<Integer>> graph = new HashMap<>();
        for (int i = 0; i < n; i++) {
            graph.put(i, new ArrayList<>());
        }

        // Add edges to the graph if two nodes have different groups and their corresponding words are equal in length with a hamming distance of 1
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i != j && groups[i] != groups[j] && words[i].length() == words[j].length()) {
                    int hammingDistance = 0;
                    for (int k = 0; k < words[i].length(); k++) {
                        if (words[i].charAt(k) != words[j].charAt(k)) {
                            hammingDistance++;
                        }
                    }
                    if (hammingDistance == 1) {
                        graph.get(i).add(j);
                    }
                }
            }
        }

        // Perform DFS to find the longest subsequence
        int[] dp = new int[n];
        Arrays.fill(dp, 1);
        for (int i = 0; i < n; i++) {
            dfs(graph, words, groups, i, dp);
        }

        // Find the index with the maximum length in the dp array
        int maxLengthIndex = -1;
        int maxLength = 0;
        for (int i = 0; i < n; i++) {
            if (dp[i] > maxLength) {
                maxLength = dp[i];
                maxLengthIndex = i;
            }
        }

        // Reconstruct the longest subsequence
        List<String> result = new ArrayList<>();
        reconstruct(graph, words, groups, maxLengthIndex, result);

        return result;
    }

    private void dfs(Map<Integer, List<Integer>> graph, String[] words, int[] groups, int index, int[] dp) {
        for (int neighbor : graph.get(index)) {
            if (dp[neighbor] < dp[index] + 1) {
                dp[neighbor] = dp[index] + 1;
                dfs(graph, words, groups, neighbor, dp);
            }
        }
    }

    private void reconstruct(Map<Integer, List<Integer>> graph, String[] words, int[] groups, int index, List<String> result) {
        if (index == -1) return;

        // Add the word at the current index to the result
        result.add(0, words[index]);

        // Find a neighbor with a length one less than the current node and recursively reconstruct the subsequence
        for (int neighbor : graph.get(index)) {
            if (getLength(graph, words, groups, neighbor) == getLength(graph, words, groups, index) - 1) {
                reconstruct(graph, words, groups, neighbor, result);
                break;
            }
        }
    }

    private int getLength(Map<Integer, List<Integer>> graph, String[] words, int[] groups, int index) {
        int length = 0;
        while (index != -1) {
            length++;
            boolean found = false;
            for (int neighbor : graph.get(index)) {
                if (getLength(graph, words, groups, neighbor) == length - 1) {
                    index = neighbor;
                    found = true;
                    break;
                }
            }
            if (!found) {
                index = -1;
            }
        }
        return length;
    }
}

