public class Solution {
    public int minimumAddedCoins(int[] coins, int target) {
        Arrays.sort(coins);
        long sum = 0;
        int count = 0;

        for (int coin : coins) {
            if (sum < coin - 1) {
                count += (coin - 1 - sum);
                sum = coin + sum;
            } else {
                sum += coin;
            }
        }

        if (sum < target) {
