import java.util.HashMap;
import java.util.Map;

public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int numberOfGoodPartitions(int[] nums) {
        Map<Integer, Integer> countMap = new HashMap<>();
        for (int num : nums) {
            countMap.put(num, countMap.getOrDefault(num, 0) + 1);
        }

        int n = nums.length;
        long[][] dp = new long[n + 1][countMap.size() + 1];
        dp[0][0] = 1;

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= countMap.size(); j++) {
                if (j > 0) {
                    dp[i][j] += dp[i - 1][j - 1];
                    dp[i][j] %= MOD;
                }
                int k = 1;
                while (i + k - 1 < n && nums[i + k - 1] == nums[i - 1]) {
                    k++;
                }
                if (i + k <= n) {
                    dp[i + k][j] += dp[i - 1][j];
                    dp[i + k][j] %= MOD;
                }
            }
        }

        long result = 0;
        for (int j = 1; j <= countMap.size(); j++) {
            result += dp[n][j];
            result %= MOD;
        }
        return (int) result;
    }
}

