public class Solution {
    public int findMaximumLength(int[] nums) {
        int n = nums.length;
        int[][] dp = new int[n][n];

        for (int i = 0; i < n; i++) {
            dp[i][i] = 1;
        }

        for (int length = 2; length <= n; length++) {
            for (int left = 0; left <= n - length; left++) {
                int right = left + length - 1;

                if (isNonDecreasing(nums, dp, left, right)) {
                    dp[left][right] = right - left + 1;
                } else {
                    for (int k = left; k < right; k++) {
                        if (dp[left][k] > 0 && dp[k + 1][right] > 0) {
                            int sumLeft = getSum(nums, left, k);
                            int sumRight = getSum(nums, k + 1, right);

                            if (sumLeft <= sumRight) {
                                dp[left][right] = Math.max(dp[left][right], dp[k + 1][right]);
                            }
                        }
                    }
                }
            }
        }

        return dp[0][n - 1];
    }

    private boolean isNonDecreasing(int[] nums, int[][] dp, int left, int right) {
        for (int i = left; i < right; i++) {
            if (nums[i] > nums[i + 1]) {
                return false;
            }
        }

        return true;
    }

    private int getSum(int[] nums, int left, int right) {
        int sum = 0;

        for (int i = left; i <= right; i++) {
            sum += nums[i];
        }

        return sum;
    }
}

