import java.util.*;

public class Solution {
    public int countClosedBranches(int n, int maxDistance, int[][] roads) {
        List<int[]>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }

        for (int[] road : roads) {
            graph[road[0]].add(new int[]{road[1], road[2]});
            graph[road[1]].add(new int[]{road[0], road[2]});
        }

        long result = 0;
        for (int mask = 0; mask < (1 << n); mask++) {
            boolean isValid = true;
            int[] distances = new int[n];
            Arrays.fill(distances, Integer.MAX_VALUE);

            for (int i = 0; i < n; i++) {
                if (((mask >> i) & 1) == 1) {
                    distances[i] = 0;
                }
            }

            Queue<Integer> queue = new LinkedList<>();
            for (int i = 0; i < n; i++) {
                if (distances[i] != Integer.MAX_VALUE) {
                    queue.offer(i);
                }
            }

            while (!queue.isEmpty()) {
                int current = queue.poll();
                for (int[] neighbor : graph[current]) {
                    if (((mask >> neighbor[0]) & 1) == 1 && distances[current] + neighbor[1] < distances[neighbor[0]]) {
                        distances[neighbor[0]] = distances[current] + neighbor[1];
                        queue.offer(neighbor[0]);
                    }
                }
            }

            for (int i = 0; i < n; i++) {
                if (((mask >> i) & 1) == 1 && distances[i] > maxDistance) {
                    isValid = false;
                    break;
                }
            }

            if (isValid) {
                result++;
            }
        }

        return (int) result;
    }
}

