public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int countSubMultisets(List<Integer> nums, int l, int r) {
        int n = nums.size();
        int[] dp = new int[r + 1];
        dp[0] = 1;

        for (int num : nums) {
            int[] nextDp = new int[r + 1];
            System.arraycopy(dp, 0, nextDp, 0, r + 1);

            for (int i = num; i <= r; i++) {
                nextDp[i] = (nextDp[i] + dp[i - num]) % MOD;
            }

            dp = nextDp;
        }

        int count = 0;
        for (int i = l; i <= r; i++) {
            count = (count + dp[i]) % MOD;
        }

        return count;
    }
}

