public class Solution {
    public long minIncrementOperations(int[] nums, int k) {
        long operations = 0;
        for (int i = 0; i < nums.length - 2; i++) {
            int max = Math.max(Math.max(nums[i], nums[i + 1]), nums[i + 2]);
            if (max < k) {
                operations += k - max;
                nums[i] += k - max;
                nums[i + 1] += k - max;
                nums[i + 2] += k - max;
            }
        }

        // Check for subarrays of size 3 at the end
        if (nums.length >= 3) {
            int lastThreeMax = Math.max(Math.max(nums[nums.length - 3], nums[nums.length - 2]), nums[nums.length - 1]);
            if (lastThreeMax < k) {
                operations += k - lastThreeMax;
            }
        } else if (nums.length == 2) {
            int lastTwoMax = Math.max(nums[0], nums[1]);
            if (lastTwoMax < k) {
                operations += k - lastTwoMax;
            }
        } else if (nums.length == 1 && nums[0] < k) {
            operations += k - nums[0];
        }

        return operations;
    }
