            this.val = val;
            this.row = row;
            this.col = col;
        }

        @Override
        public int compareTo(Node other) {
            return Integer.compare(other.val, this.val);
        }
    }

    public long maxSpending(int[][] values) {
        PriorityQueue<Node> pq = new PriorityQueue<>();
        for (int i = 0; i < values.length; i++) {
            if (values[i].length > 0) {
                pq.offer(new Node(values[i][0], i, 0));
            }
        }

        long res = 0;
        int day = 1;

        while (!pq.isEmpty()) {
            Node node = pq.poll();
            res += (long) node.val * day;

            if (node.col + 1 < values[node.row].length) {
                pq.offer(new Node(values[node.row][node.col + 1], node.row, node.col + 1));
            }

            day++;
        }

        return res;
    }
}

