    public long maximumScoreAfterOperations(int[][] edges, int[] values) {
        this.values = values;
        graph = new ArrayList<>();
        for (int i = 0; i < values.length; i++) {
            graph.add(new ArrayList<>());
        }

        // Build the tree
        for (int[] edge : edges) {
