            // Leaf node
            maxScore = Math.max(maxScore, values[node]);
            return values[node];
        }

        long sum = 0;
        for (int child : graph.get(node)) {
            if (child != parent) {
                sum += dfs(child, node);
            }
        }

        maxScore = Math.max(maxScore, sum + values[node]);
        return sum + values[node];
    }
}

