public class Solution {
    public int minimumChanges(String s, int k) {
        int n = s.length();
        int[][] dp = new int[n + 1][k + 1];

        // Initialize the base case where we have no substrings (i.e., k = 0)
        for (int i = 0; i <= n; i++) {
            dp[i][0] = Integer.MAX_VALUE;
        }

        // Base case: one substring
        dp[n][1] = getChanges(s, 0, n - 1);

        // Fill up the dp table in a bottom-up manner
        for (int i = n - 1; i >= 0; i--) {
            for (int j = 2; j <= k; j++) {
                int min = Integer.MAX_VALUE;
                for (int m = i + 1; m < n; m++) {
                    // Calculate the minimum changes by considering all possible splits
                    min = Math.min(min, dp[m][j - 1] + getChanges(s, i, m - 1));
                }
                dp[i][j] = min;
            }
        }

        return dp[0][k];
    }

    // Helper function to calculate the minimum changes required for a substring
    private int getChanges(String s, int left, int right) {
        if (left == right) {
            return 0; // Single character is always a palindrome
        }

        int n = right - left + 1;
        int min = Integer.MAX_VALUE;

        // Check for all possible divisors of the substring length
        for (int d = 1; d < n && d <= n / 2; d++) {
            if (n % d == 0) {
                int changes = getChangesForDivisor(s, left, right, d);
                min = Math.min(min, changes);
            }
        }

        return min;
    }

    // Helper function to calculate the minimum changes required for a substring with a given divisor
    private int getChangesForDivisor(String s, int left, int right, int d) {
        int n = right - left + 1;
        int[] count = new int[26];

        // Count the frequency of each character in the substring
        for (int i = left; i <= right; i++) {
            count[s.charAt(i) - 'a']++;
        }

        int changes = 0;
        // Calculate the minimum changes required to make the substring a semi-palindrome
        for (int i = 0; i < d; i++) {
            int[] groupCount = new int[26];
            for (int j = i; j < n; j += d) {
                groupCount[s.charAt(left + j) - 'a']++;
            }

            // Calculate the minimum changes required to make the current group a palindrome
            for (int c = 0; c < 26; c++) {
                if ((groupCount[c] & 1) == 1) {
                    changes++;
                }
            }
        }

        return changes / 2;
    }
}

