public class Solution {
    public boolean areSimilar(int[][] mat, int k) {
        int m = mat.length;
        int n = mat[0].length;

        // Perform cyclic shifts on the matrix
        for (int i = 0; i < m; i++) {
            if (i % 2 == 0) { // Even indexed rows: left shift
                k = k % n; // Handle cases where k > n
                int[] temp = new int[n];
                System.arraycopy(mat[i], k, temp, 0, n - k);
                System.arraycopy(mat[i], 0, temp, n - k, k);
                System.arraycopy(temp, 0, mat[i], 0, n);
            } else { // Odd indexed rows: right shift
                k = k % n; // Handle cases where k > n
                int[] temp = new int[n];
                System.arraycopy(mat[i], n - k, temp, 0, k);
                System.arraycopy(mat[i], 0, temp, k, n - k);
                System.arraycopy(temp, 0, mat[i], 0, n);
            }
        }

        // Compare the initial and final matrices
        int[][] originalMat = new int[m][n];
        for (int i = 0; i < m; i++) {
            if (i % 2 == 0) { // Even indexed rows: left shift back to original position
                k = k % n;
                int[] temp = new int[n];
                System.arraycopy(mat[i], n - k, temp, 0, k);
                System.arraycopy(mat[i], 0, temp, k, n - k);
                System.arraycopy(temp, 0, originalMat[i], 0, n);
            } else { // Odd indexed rows: right shift back to original position
                k = k % n;
                int[] temp = new int[n];
                System.arraycopy(mat[i], k, temp, 0, n - k);
                System.arraycopy(mat[i], 0, temp, n - k, k);
                System.arraycopy(temp, 0, originalMat[i], 0, n);
            }
        }

        // Compare the initial and final matrices
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (mat[i][j] != originalMat[i][j]) {
                    return false;
                }
            }
        }

        return true;
    }
}

