public class Solution {
    public int minOperations(int[] nums, int k) {
        int xor = 0;
        for (int num : nums) {
            xor ^= num;
        }

        int target = k ^ xor;
        if (target == 0) return 0;

        int operations = Integer.MAX_VALUE;
        for (int num : nums) {
            String binaryNum = Integer.toBinaryString(num);
            String binaryTarget = Integer.toBinaryString(target);

            while (binaryNum.length() < binaryTarget.length()) {
                binaryNum = "0" + binaryNum;
            }

            int count = 0;
            for (int i = 0; i < binaryTarget.length(); i++) {
                if (binaryNum.charAt(i) != binaryTarget.charAt(i)) {
                    count++;
                }
            }

            operations = Math.min(operations, count);
        }

        return operations;
    }
