import java.util.*;

public class Solution {
    private List<Integer>[] graph;
    private int[] cost;

    public long[] placedCoins(int[][] edges, int[] cost) {
        this.cost = cost;
        int n = cost.length;
        graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] edge : edges) {
            graph[edge[0]].add(edge[1]);
            graph[edge[1]].add(edge[0]);
        }

        long[] coins = new long[n];
        dfs(0, -1, coins);
        return coins;
    }

    private Result dfs(int node, int parent, long[] coins) {
        List<Integer> costs = new ArrayList<>();
        for (int child : graph[node]) {
            if (child != parent) {
                Result result = dfs(child, node, coins);
                costs.addAll(result.costs);
            }
        }
        costs.add(cost[node]);

        if (costs.size() < 3) {
            coins[node] = 1;
        } else {
            PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Comparator.reverseOrder());
            for (int c : costs) {
                maxHeap.offer(c);
            }

            long product = (long) maxHeap.poll() * maxHeap.poll() * maxHeap.poll();
            if (product < 0) {
                coins[node] = 0;
            } else {
                coins[node] = product;
            }
        }

        Result result = new Result(coins[node], costs);
        return result;
    }

    private static class Result {
        long coins;
        List<Integer> costs;

        public Result(long coins, List<Integer> costs) {
            this.coins = coins;
            this.costs = costs;
        }
