public class Solution {
    public int minCost(String source, String target, String[] original, String[] changed, int[] cost) {
        int n = source.length();
        int[][] dp = new int[n + 1][n + 1];
        for (int i = 0; i <= n; i++) {
            Arrays.fill(dp[i], Integer.MAX_VALUE);
        }
        dp[0][0] = 0;

        for (int len = 1; len <= n; len++) {
            for (int start = 0; start + len - 1 < n; start++) {
                int end = start + len - 1;
                String substr = source.substring(start, end + 1);
                for (int i = 0; i < original.length; i++) {
                    if (substr.equals(original[i])) {
                        String newSubstr = changed[i];
                        dp[start][end] = Math.min(dp[start][end], cost[i]);
                        int idx = target.indexOf(newSubstr, start);
                        while (idx != -1 && idx <= end) {
                            dp[idx + newSubstr.length()][end] = Math.min(dp[idx + newSubstr.length()][end], dp[start][start + len - 1] + cost[i]);
                            idx = target.indexOf(newSubstr, idx + 1);
                        }
                    }
                }
            }
        }

        int minCost = Integer.MAX_VALUE;
        for (int i = n; i <= n; i++) {
            if (target.substring(0, n).equals(source.substring(0, n))) {
                minCost = Math.min(minCost, dp[i][i]);
            } else {
                minCost = Math.min(minCost, dp[n][n]);
            }
        }

        return minCost == Integer.MAX_VALUE ? -1 : minCost;
    }
}

