import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

public class Solution {
    public boolean[] makePalindrome(String s, int[][] queries) {
        boolean[] answer = new boolean[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int a = queries[i][0], b = queries[i][1], c = queries[i][2], d = queries[i][3];
            Map<Character, Integer> leftCount = countChars(s, a, b);
            Map<Character, Integer> rightCount = countChars(s, c, d);

            boolean possible = true;
            for (char ch : leftCount.keySet()) {
                if (!rightCount.containsKey(ch) || leftCount.get(ch) != rightCount.get(ch)) {
                    possible = false;
                    break;
                }
            }

            if (possible) {
                answer[i] = true;
                continue;
            }

            int n = s.length();
            Map<Character, Integer> firstHalfCount = countChars(s, 0, n / 2 - 1);
            Map<Character, Integer> secondHalfCount = countChars(s, n / 2, n - 1);

            boolean isPalindrome = true;
            for (char ch : firstHalfCount.keySet()) {
                if (!secondHalfCount.containsKey(ch) || firstHalfCount.get(ch) != secondHalfCount.get(ch)) {
                    isPalindrome = false;
                    break;
                }
            }

            if (isPalindrome) {
                answer[i] = true;
                continue;
            }

            int mismatchIndex1 = -1, mismatchIndex2 = -1;
            for (int j = 0; j < n / 2; j++) {
                char ch1 = s.charAt(j);
                char ch2 = s.charAt(n - 1 - j);
                if (ch1 != ch2) {
                    mismatchIndex1 = j;
                    mismatchIndex2 = n - 1 - j;
                    break;
                }
            }

            if ((a <= mismatchIndex1 && b >= mismatchIndex1) || (c <= mismatchIndex2 && d >= mismatchIndex2)) {
                answer[i] = true;
            } else if ((a <= mismatchIndex1 && c <= mismatchIndex2) || (b >= mismatchIndex1 && d >= mismatchIndex2)) {
                Map<Character, Integer> leftRemainCount = countChars(s, a, b);
                Map<Character, Integer> rightRemainCount = countChars(s, c, d);

                boolean possibleLeft = true;
                for (char ch : leftRemainCount.keySet()) {
                    if (!rightRemainCount.containsKey(ch) || leftRemainCount.get(ch) != rightRemainCount.get(ch)) {
                        possibleLeft = false;
                        break;
                    }
                }

                answer[i] = possibleLeft;
            } else {
                answer[i] = false;
            }
        }
        return answer;
    }

    private Map<Character, Integer> countChars(String s, int start, int end) {
        Map<Character, Integer> charCount = new HashMap<>();
        for (int i = start; i <= end; i++) {
            char ch = s.charAt(i);
            charCount.put(ch, charCount.getOrDefault(ch, 0) + 1);
        }
        return charCount;
    }
}

