public class Solution {
    public long minimumSteps(String s) {
        int n = s.length();
        int blackBalls = 0;
        for (char c : s.toCharArray()) {
            if (c == '1') {
                blackBalls++;
            }
        }

        int whiteBalls = n - blackBalls;

        int steps = 0;
        int blackCount = 0;
        for (int i = 0; i < whiteBalls; i++) {
            if (s.charAt(i) == '1') {
                blackCount++;
            }
        }

        steps = blackCount;

        for (int i = whiteBalls; i < n; i++) {
            if (s.charAt(i - whiteBalls) == '1') {
                blackCount--;
            }
            if (s.charAt(i) == '1') {
                blackCount++;
            }
            steps = Math.min(steps, blackCount);
        }

        return steps;
    }
}

