import java.util.Arrays;

public class Solution {
    public long maxBalancedSubsequenceSum(int[] nums) {
        int n = nums.length;
        long[] dp = new long[n];

        // Initialize the maximum sum for each subsequence of length 1
        for (int i = 0; i < n; i++) {
            dp[i] = nums[i];
        }

        // Compute the maximum sum for each subsequence of length >= 2
        for (int j = 1; j < n; j++) {
            for (int i = 0; i < j; i++) {
                if (nums[j] - nums[i] >= j - i) {
                    dp[j] = Math.max(dp[j], dp[i] + nums[j]);
                }
            }
        }

        // Return the maximum sum of all subsequences
        return Arrays.stream(dp).max().getAsLong();
    }
}

