        }
        for (int i = 0; i < nums.length; i++) {
            if (i >= start && i < end) {
                continue;
            }
            if (i > 0 && i - 1 >= start && i - 1 < end) {
                continue;
            }
            if (i > 0 && nums[i] <= nums[i - 1]) {
                return false;
            }
        }
        return true;
    }
}

