import java.util.List;

public class Solution {
    public int lengthOfLIS(List<Integer> nums, int target) {
        return helper(nums, 0, target);
    }

    private int helper(List<Integer> nums, int index, int target) {
        if (target == 0) {
            return 0;
        }
        if (index >= nums.size() || target < 0) {
            return -1;
        }

        int include = helper(nums, index + 1, target - nums.get(index));
        if (include != -1) {
            include += 1;
        }

        int exclude = helper(nums, index + 1, target);

        if (include == -1 && exclude == -1) {
            return -1;
        } else if (include == -1) {
            return exclude;
        } else if (exclude == -1) {
            return include;
        }

        return Math.max(include, exclude);
    }
}

