            if (nums2[i] > maxNums2) {
                maxNums2 = nums2[i];
                maxIndexNums2 = i;
            }
        }

        int operations = 0;

        // Check if it's possible to satisfy both conditions
        if ((maxIndexNums1 != n - 1 && maxIndexNums2 != n - 1) || (maxIndexNums1 == n - 1 && maxIndexNums2 == n - 1)) {
            if (maxIndexNums1 != n - 1) {
                operations++;
                int temp = nums1[maxIndexNums1];
                nums1[maxIndexNums1] = nums2[maxIndexNums1];
                nums2[maxIndexNums1] = temp;
