            if (maxIndexNums2 != n - 1) {
                operations++;
                int temp = nums2[maxIndexNums2];
                nums2[maxIndexNums2] = nums1[maxIndexNums2];
                nums1[maxIndexNums2] = temp;
            }

            // Check if the conditions are satisfied after swapping
            if (nums1[n - 1] == maxNums1 && nums2[n - 1] == maxNums2) {
                return operations;
            } else {
                return -1;
            }
        } else if (maxIndexNums1 == n - 1 || maxIndexNums2 == n - 1) {
            // If one of the arrays already has its maximum at the end
            if (maxIndexNums1 == n - 1 && maxIndexNums2 != n - 1) {
                operations++;
                int temp = nums2[maxIndexNums2];
                nums2[maxIndexNums2] = nums1[maxIndexNums2];
                nums1[maxIndexNums2] = temp;
