public class Solution {
    public int[][] constructProductMatrix(int[][] grid) {
        int n = grid.length;
        int m = grid[0].length;

        long totalProduct = 1;
        int zeroCount = 0;

        // Calculate the total product of all elements in the grid
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 0) {
                    zeroCount++;
                } else {
                    totalProduct *= grid[i][j];
                    totalProduct %= 1000000007;
                }
            }
        }

        int[][] result = new int[n][m];

        // Calculate the product of all elements except for each element
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (zeroCount > 1) {
                    result[i][j] = 0;
                } else if (zeroCount == 1) {
                    result[i][j] = grid[i][j] == 0 ? (int)(totalProduct % 1000000007) : 0;
                } else {
                    result[i][j] = (int)((totalProduct * powMod(grid[i][j], -1, 1000000007)) % 1000000007);
                }
            }
        }

        return result;
    }

    private long powMod(long base, int exponent, int mod) {
        if (exponent == 0) {
            return 1;
        } else if (exponent < 0) {
            return powMod(pow(base, -exponent, mod), mod - 2, mod);
        }

        long result = 1;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = (result * base) % mod;
            }
            exponent >>= 1;
            base = (base * base) % mod;
        }
        return result;
    }

    private long pow(long base, int exponent, int mod) {
        if (exponent == 0) {
            return 1;
        } else if (exponent < 0) {
            return powMod(pow(base, -exponent, mod), mod - 2, mod);
        }

        long result = 1;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result *= base;
            }
            exponent >>= 1;
            base *= base;
        }
        return result % mod;
    }
}

