public class Solution {
    public int findChampion(int n, int[][] edges) {
        // Create an adjacency list to represent the graph
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }

        // Initialize the in-degree array
        int[] inDegree = new int[n];

        // Populate the adjacency list and update the in-degree array
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            graph.get(u).add(v);
            inDegree[v]++;
        }

        // Find all nodes with an in-degree of 0, which are potential champions
        List<Integer> champions = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (inDegree[i] == 0) {
                champions.add(i);
            }
        }

        // If there is a unique champion, return it; otherwise, return -1
        if (champions.size() == 1) {
            return champions.get(0);
        } else {
            return -1;
        }
    }
}

