import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int maxArea(int m, int n, int[] hFences, int[] vFences) {
        Arrays.sort(hFences);
        Arrays.sort(vFences);

        Set<Integer> horizontalSet = new HashSet<>();
        for (int fence : hFences) {
            horizontalSet.add(fence);
        }

        Set<Integer> verticalSet = new HashSet<>();
        for (int fence : vFences) {
            verticalSet.add(fence);
        }

        int maxArea = -1;
        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                if (!horizontalSet.contains(i) && !verticalSet.contains(j)) {
                    continue;
                }
                int sideLength = Math.min(getHorizontalDistance(m, horizontalSet, i), getVerticalDistance(n, verticalSet, j));
                maxArea = Math.max(maxArea, (int) ((long) sideLength * sideLength % MOD));
            }
        }

        return maxArea;
    }

    private int getHorizontalDistance(int m, Set<Integer> horizontalSet, int current) {
        int left = 0, right = m - 1;

        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (!horizontalSet.contains(mid)) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }

        return Math.min(current, m - current);
    }

    private int getVerticalDistance(int n, Set<Integer> verticalSet, int current) {
        int left = 0, right = n - 1;

        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (!verticalSet.contains(mid)) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }

        return Math.min(current, n - current);
    }
}

