public class Solution {
    public int minimumOperationsToMakeEqual(int x, int y) {
        Queue<int[]> queue = new LinkedList<>();
        Set<String> visited = new HashSet<>();

        queue.offer(new int[] {x, 0});
        visited.add(String.valueOf(x));

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int currentValue = current[0];
            int steps = current[1];

            if (currentValue == y) {
                return steps;
            }

            if (currentValue % 11 == 0 && !visited.contains(String.valueOf(currentValue / 11))) {
                queue.offer(new int[] {currentValue / 11, steps + 1});
                visited.add(String.valueOf(currentValue / 11));
            }

            if (currentValue % 5 == 0 && !visited.contains(String.valueOf(currentValue / 5))) {
                queue.offer(new int[] {currentValue / 5, steps + 1});
                visited.add(String.valueOf(currentValue / 5));
            }

            if (!visited.contains(String.valueOf(currentValue - 1))) {
                queue.offer(new int[] {currentValue - 1, steps + 1});
                visited.add(String.valueOf(currentValue - 1));
            }

            if (!visited.contains(String.valueOf(currentValue + 1))) {
                queue.offer(new int[] {currentValue + 1, steps + 1});
                visited.add(String.valueOf(currentValue + 1));
            }
        }

        return -1;
    }
