            for (int j = i + 1; j <= n; j++) {
                if (isIncreasing(nums, i, j)) {
                    count++;
                }
            }
        }

        return count;
    }

    private boolean isIncreasing(int[] nums, int start, int end) {
        if (start == end) {
            return true;
        }

        for (int i = 0; i < start - 1; i++) {
            if (nums[i] >= nums[i + 1]) {
                return false;
            }
        }

        for (int i = end; i < nums.length - 1; i++) {
            if (nums[i] >= nums[i + 1]) {
                return false;
            }
        }

        if (start > 0 && end < nums.length) {
            if (nums[start - 1] >= nums[end]) {
                return false;
            }
        }

        return true;
    }
}

