import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int collectCoins(int[][] edges, int[] coins, int k) {
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < coins.length; i++) {
            graph.add(new ArrayList<>());
        }

        for (int[] edge : edges) {
            graph.get(edge[0]).add(edge[1]);
            graph.get(edge[1]).add(edge[0]);
        }

        return dfs(graph, coins, k, 0, -1);
    }

    private int dfs(List<List<Integer>> graph, int[] coins, int k, int node, int parent) {
        int maxPoints = 0;

        for (int child : graph.get(node)) {
            if (child != parent) {
                maxPoints += dfs(graph, coins, k, child, node);
            }
        }

        // Collect all the coins
        int collectAll = coins[node] - k;
        if (collectAll < 0) {
            collectAll = -collectAll;
        } else {
            collectAll = coins[node] - k;
        }

        // Collect half of the coins
        int collectHalf = coins[node] / 2;

        return Math.max(collectAll, collectHalf + maxPoints);
    }

    private void reduceCoins(int[] coins, List<List<Integer>> graph, int node) {
        coins[node] /= 2;

        for (int child : graph.get(node)) {
            reduceCoins(coins, graph, child);
        }
    }
}

