import java.util.PriorityQueue;

public class Solution {
    public int minOperations(int[] nums, int k) {
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        for (int num : nums) {
            pq.offer(num);
        }

        int operations = 0;
        while (!pq.isEmpty()) {
            if (pq.peek() >= k && pq.size() == 1) break;
            if (pq.size() < 2) return -1; // not possible to make all elements greater than or equal to k

            int x = pq.poll();
            int y = pq.poll();

            if (Math.min(x, y) * 2 + Math.max(x, y) >= k && pq.isEmpty()) break;

            pq.offer(Math.min(x, y) * 2 + Math.max(x, y));
            operations++;
        }

        return operations;
    }
}

