public class Solution {
    public int minimumLevels(int[] possible) {
        int n = possible.length;
        int alicePoints = 0, bobPoints = 0;

        for (int i = 0; i < n; i++) {
            if (possible[i] == 1) {
                alicePoints++;
            } else {
                break;
            }
        }

        for (int i = n - 1; i >= 0; i--) {
            if (possible[i] == 1) {
                bobPoints++;
            } else {
                break;
            }
        }

        int minLevels = 1;

        while (alicePoints <= bobPoints && minLevels < n) {
            minLevels++;

            if (minLevels < n && possible[minLevels - 1] == 1) {
                alicePoints++;
            }

            if (possible[n - minLevels] == 1) {
                bobPoints--;
            }
        }

        return alicePoints > bobPoints ? minLevels : -1;
    }
}

