public class Solution {
    public int minOrAfterOperations(int[] nums, int k) {
        int n = nums.length;
        int[][] dp = new int[n][n];

        // Initialize the diagonal of the dp array with the original values in nums.
        for (int i = 0; i < n; i++) {
            dp[i][i] = nums[i];
        }

        // Fill up the rest of the dp array using dynamic programming.
        for (int length = 1; length <= n - 1; length++) {
            for (int left = 0; left + length < n; left++) {
                int right = left + length;
                dp[left][right] = nums[left] & nums[right];
                for (int mid = left; mid < right; mid++) {
                    dp[left][right] = Math.max(dp[left][right], dp[left][mid] | dp[mid + 1][right]);
                }
            }
        }

        // Initialize the minimum OR value with a large number.
        int minOr = Integer.MAX_VALUE;

        // Try all possible ways to divide nums into two parts and calculate their OR values.
        for (int i = 0; i < n - k; i++) {
            int leftOr = dp[0][i];
            int rightOr = dp[i + 1][n - 1];
            minOr = Math.min(minOr, leftOr | rightOr);
        }

        return minOr;
    }
}

