public class Solution {
    public int maximumLength(int[] nums) {
        Map<Integer, Integer> map = new HashMap<>();
        int maxLen = 0;

        for (int num : nums) {
            if (!map.containsKey(num)) {
                map.put(num, 1);
            } else {
                map.put(num, map.get(num) + 1);
            }
        }

        for (Map.Entry<Integer, Integer> entry : map.entrySet()) {
            int base = entry.getKey();
            int count = entry.getValue();

            if (count < 2) continue;

            int len = 0;
            long val = base;
            while (val <= Integer.MAX_VALUE && count > 0) {
                if (map.containsKey((int) val)) {
                    len++;
                    count--;
                }
                val *= base;
            }

            if (len == 1) continue;

            maxLen = Math.max(maxLen, len * 2 - 1);
        }

        for (Map.Entry<Integer, Integer> entry : map.entrySet()) {
            int base = entry.getKey();
            int count = entry.getValue();

            if (count < 2) continue;

            int len = 0;
            long val = base;
            while (val <= Integer.MAX_VALUE && count > 0) {
                if (map.containsKey((int) val)) {
                    len++;
                    count--;
                }
                val *= base;
            }

            maxLen = Math.max(maxLen, len * 2);
        }

