// #2024_03_04_Time_5_ms_(92.03%)_Space_44.5_MB_(91.30%)
import java.util.HashSet;
import java.util.PriorityQueue;
import java.util.Queue;
import java.util.Set;

public class Solution {
    public int earliestSecondToMarkIndices(int[] nums, int[] changeIndices) {
        int n = nums.length;
        int m = changeIndices.length;

        for (int i = 0; i < m; i++) {
            if (nums[changeIndices[i] - 1] == 0) {
                return i + 1;
            }
        }

        PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> nums[b - 1] - nums[a - 1]);

        for (int i = 1; i <= n; i++) {
            if (nums[i - 1] > 0) {
                pq.offer(i);
            }
        }

        Set<Integer> marked = new HashSet<>();

        int second = 1;

        while (!pq.isEmpty() && second <= m) {
            if (marked.contains(changeIndices[second - 1])) {
                second++;
                continue;
            }

            nums[changeIndices[second - 1] - 1]--;

            if (nums[changeIndices[second - 1] - 1] == 0) {
                marked.add(changeIndices[second - 1]);
            } else {
                pq.offer(changeIndices[second - 1]);
            }

            second++;
        }

        while (!pq.isEmpty()) {
            int index = pq.poll();
            if (nums[index - 1] > 0) {
                return -1;
            } else {
                marked.add(index);
            }
        }

        if (marked.size() == n) {
            return Math.min(second, m + 1);
        } else {
            return -1;
        }
    }
}

