import java.util.Arrays;

public class Solution {
    public int[] distributeArray(int[] nums) {
        int n = nums.length;
        int[] arr1 = new int[n];
        int[] arr2 = new int[n];
        int size1 = 0, size2 = 0;

        // append the first element to arr1
        arr1[size1++] = nums[0];

        for (int i = 1; i < n; i++) {
            int greaterCount1 = getGreaterCount(arr1, size1, nums[i]);
            int greaterCount2 = getGreaterCount(arr2, size2, nums[i]);

            if (greaterCount1 > greaterCount2) {
                arr2[size2++] = nums[i];
            } else if (greaterCount1 < greaterCount2) {
                arr1[size1++] = nums[i];
            } else {
                // If there is still a tie, append nums[i] to the array with a lesser number of elements
                if (size1 <= size2) {
                    arr1[size1++] = nums[i];
                } else {
                    arr2[size2++] = nums[i];
                }
            }
        }

        int[] result = new int[n];
        System.arraycopy(arr1, 0, result, 0, size1);
        System.arraycopy(arr2, 0, result, size1, size2);

        return result;
    }

    private int getGreaterCount(int[] arr, int size, int val) {
        int count = 0;
        for (int i = 0; i < size; i++) {
            if (arr[i] > val) {
                count++;
            }
        }
        return count;
    }
}

