public class Solution {
    public int countSubmatrices(int[][] grid, int k) {
        int rows = grid.length;
        int cols = grid[0].length;
        int count = 0;

        for (int rowStart = 0; rowStart < rows; rowStart++) {
            int[] prefixSumRow = new int[cols];
            for (int rowEnd = rowStart; rowEnd < rows; rowEnd++) {
                // Calculate the prefix sum of each column
                for (int col = 0; col < cols; col++) {
                    prefixSumRow[col] += grid[rowEnd][col];
                }

                int[] prefixSumCol = new int[cols + 1];
                for (int colStart = 0; colStart < cols; colStart++) {
                    // Calculate the prefix sum of each column
                    for (int colEnd = colStart; colEnd < cols; colEnd++) {
                        prefixSumCol[colEnd + 1] = prefixSumCol[colEnd] + prefixSumRow[colEnd];
                    }

                    // Check if the submatrix has a sum less than or equal to k
                    for (int colEnd = colStart; colEnd < cols; colEnd++) {
                        int sum = prefixSumCol[colEnd + 1] - prefixSumCol[colStart];
                        if (sum <= k) {
                            count++;
                        }
                    }

                    // Reset the prefix sum of each column
                    prefixSumCol = new int[cols + 1];
                }
            }
        }

        return count;
    }
}

