public class Solution {
    public int[][] resultGrid(int[][] image, int threshold) {
        int m = image.length;
        int n = image[0].length;
        int[][] result = new int[m][n];

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                double sum = 0;
                int count = 0;

                // Check all possible 3x3 regions that include the current pixel
                for (int x = Math.max(0, i - 1); x <= Math.min(m - 3 + 1, i + 1); x++) {
                    for (int y = Math.max(0, j - 1); y <= Math.min(n - 3 + 1, j + 1); y++) {
                        boolean isValidRegion = true;

                        // Check if the current region is valid
                        for (int a = x; a < x + 3; a++) {
                            for (int b = y; b < y + 3; b++) {
                                for (int c = a - 1; c <= a + 1; c++) {
                                    for (int d = b - 1; d <= b + 1; d++) {
                                        if (c >= x && c < x + 3 && d >= y && d < y + 3) {
                                            continue;
                                        }
                                        if (c >= 0 && c < m && d >= 0 && d < n && Math.abs(a - c) + Math.abs(b - d) == 1
                                                && Math.abs(image[a][b] - image[c][d]) > threshold) {
                                            isValidRegion = false;
                                        }
                                    }
                                }
                            }
                        }

                        // If the region is valid, calculate its average intensity
                        if (isValidRegion) {
                            for (int a = x; a < x + 3; a++) {
                                for (int b = y; b < y + 3; b++) {
                                    sum += image[a][b];
                                    count++;
                                }
                            }
                        }
                    }
                }

                // If the pixel belongs to at least one region, calculate its average intensity
                if (count > 0) {
                    result[i][j] = (int) Math.floor(sum / count);
                } else {
                    result[i][j] = image[i][j];
                }
            }
        }

        return result;
    }
}

