public class Solution {
    public int minimumOperationsToWriteY(int[][] grid) {
        int n = grid.length;
        int center = n / 2;

        // Calculate the number of operations for each possible value (0 and 1)
        int opsForZero = calculateOps(grid, 0);
        int opsForOne = calculateOps(grid, 1);

        return Math.min(opsForZero, opsForOne);
    }

    private int calculateOps(int[][] grid, int target) {
        int n = grid.length;
        int center = n / 2;
        int ops = 0;

        // Check the diagonals and vertical line
        for (int i = 0; i <= center; i++) {
            if (grid[i][i] != target) {
                ops++;
            }
            if (grid[i][n - i - 1] != target) {
                ops++;
            }
        }

        // Check the rest of the vertical line
        for (int i = center + 1; i < n; i++) {
            if (grid[i][center] != target) {
                ops++;
            }
        }

        // Check the rest of the grid
        int otherValue = (target == 0) ? 1 : 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (!isOnY(i, j, center)) {
                    if (grid[i][j] != otherValue) {
                        ops++;
                    }
                }
            }
        }

        return ops;
    }

    private boolean isOnY(int i, int j, int center) {
        return (i == j && i <= center) || 
               (i + j == grid.length - 1 && i <= center) || 
               (j == center && i > center);
    }
}

