// #Medium #Array #Depth_First_Search #Tree #2024_03_31_Time_69_ms_(99.83%)_Space_45.5_MB_(81.49%)
public class Solution {
    public int[] countPairsOfConnectableServers(int[][] edges, int signalSpeed) {
        int n = 0;
        for (int[] edge : edges) {
            n = Math.max(n, Math.max(edge[0], edge[1]));
        }
        n++;

        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }

        for (int[] edge : edges) {
            int a = edge[0], b = edge[1], weight = edge[2];
            graph[a].add(b);
            graph[b].add(a);
        }

        int[] count = new int[n];

        for (int i = 0; i < n; i++) {
            boolean[][] visited = new boolean[n][n];
            Map<Integer, Integer> distanceMap1 = new HashMap<>();
            dfs(graph, i, -1, 0, signalSpeed, distanceMap1, visited);

            int pairs = 0;
            for (int j = 0; j < n; j++) {
                if (j == i) continue;

                boolean[][] visited2 = new boolean[n][n];
                Map<Integer, Integer> distanceMap2 = new HashMap<>();
                dfs(graph, i, -1, 0, signalSpeed, distanceMap2, visited2);

                for (int k = j + 1; k < n; k++) {
                    if (k == i) continue;

                    if (distanceMap1.containsKey(k) && distanceMap2.containsKey(j)
                            && distanceMap1.get(k) % signalSpeed == 0
                            && distanceMap2.get(j) % signalSpeed == 0
                            && !hasCommonEdge(graph, visited, visited2, k, j)) {
                        pairs++;
                    }
                }
            }

            count[i] = pairs;
        }

        return count;
    }

    private void dfs(List<Integer>[] graph, int node, int parent, int distance, int signalSpeed,
                     Map<Integer, Integer> distanceMap, boolean[][] visited) {
        if (visited[node][parent]) return;

        visited[node][parent] = true;
        distanceMap.put(node, distance);

        for (int neighbor : graph[node]) {
            if (neighbor != parent) {
                dfs(graph, neighbor, node, distance + 1, signalSpeed, distanceMap, visited);
            }
        }
    }

    private boolean hasCommonEdge(List<Integer>[] graph, boolean[][] visited1, boolean[][] visited2,
                                   int node1, int node2) {
        for (int i = 0; i < graph.length; i++) {
            if (visited1[node1][i] && visited2[node2][i]) return true;
        }
        return false;
    }
}

