public class Solution {
    public int minMovesToCaptureTheQueen(int a, int b, int c, int d, int e, int f) {
        // Check if the rook can capture the queen directly
        boolean rookCanCapture = (a == e || b == f);

        // Check if the bishop can capture the queen directly
        boolean bishopCanCapture = Math.abs(c - e) == Math.abs(d - f);

        // If either piece can capture the queen, return 1 move
        if (rookCanCapture || bishopCanCapture) {
            return 1;
        }

        // Check if the rook and bishop are on the same row or column as the queen
        boolean rookSameRowOrColumn = a == e || b == f;

        // If the rook is not on the same row or column, it needs to move to get there
        int rookMoves = rookSameRowOrColumn ? 0 : 1;

        // Check if the bishop and queen are on the same diagonal
        boolean bishopSameDiagonal = Math.abs(c - e) == Math.abs(d - f);

        // If the bishop is not on the same diagonal, it needs to move to get there
        int bishopMoves = bishopSameDiagonal ? 0 : 1;

        // The minimum number of moves is the minimum between the rook and bishop's moves plus one for capturing the queen
        return Math.min(rookMoves + 1, bishopMoves + 1);
    }
}

