// #Medium #String #Hash_Table #Sorting #Greedy #Counting
// #2024_04_17_Time_4_ms_(100.00%)_Space_45.1_MB_(94.33%)
public class Solution {
    public int minimumDeletions(String word, int k) {
        Map<Character, Integer> freqMap = new HashMap<>();

        // Count the frequency of each character in the string
        for (char c : word.toCharArray()) {
            freqMap.put(c, freqMap.getOrDefault(c, 0) + 1);
        }

        List<Integer> frequencies = new ArrayList<>(freqMap.values());
        Collections.sort(frequencies);

        int deletions = 0;
        int left = 0, right = frequencies.size() - 1;

        while (left < right && frequencies.get(right) - frequencies.get(left) > k) {
            // Try to reduce the frequency of the most frequent character
            if (frequencies.get(right) - frequencies.get(left) <= k + 1) {
                deletions += frequencies.get(right) - frequencies.get(left) - k;
                left++;
                right--;
            } else {
                // If we can't make it k-special by reducing one character, 
                // then delete the most frequent character
                deletions += frequencies.get(right);
                right--;
            }
        }

        return deletions;
    }
}

