        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < count; i++) {
            sb.append(digit);
        }
        return sb.toString();
    }

    private int countDigits(int num) {
        int count = 0;
        while (num > 0) {
            num /= 10;
            count++;
        }
        return count;
    }
