import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int maxPartitionsAfterOperations(String s, int k) {
        int n = s.length();
        int res = 0;

        // Function to calculate the number of partitions for a given string and k
        int calcPartition(String str, int k) {
            int count = 0;
            Map<Character, Integer> map = new HashMap<>();

            for (int i = 0; i < str.length(); ) {
                int j = i;
                while (j < str.length() && map.size() <= k) {
                    map.put(str.charAt(j), map.getOrDefault(str.charAt(j), 0) + 1);
                    if (map.size() > k) break;
                    j++;
                }

                // If we have more than k distinct characters, stop the current partition
                if (map.size() > k) j--;

                count++;
                i = j + 1;
                map.clear();
            }

            return count;
        }

        // Try changing each character to all possible lowercase English letters
        for (int i = 0; i < n; i++) {
            char[] arr = s.toCharArray();
            for (char c = 'a'; c <= 'z'; c++) {
                if (arr[i] == c) continue;
                arr[i] = c;
                res = Math.max(res, calcPartition(new String(arr), k));
            }
        }

        // Also try not changing any character
        res = Math.max(res, calcPartition(s, k));

        return res;
    }
}

