// #2024_04_17_Time_4_ms_(97.63%)_Space_61_MB_(7.12%)
public class Solution {
    public long minimumMoves(int[] nums, int k, int maxChanges) {
        int n = nums.length;
        long minMoves = Long.MAX_VALUE;

        for (int aliceIndex = 0; aliceIndex < n; aliceIndex++) {
            if (nums[aliceIndex] == 1) {
                int onesPicked = 1;
                int changesMade = 0;
                int moves = 0;

                // Try to pick up the remaining k - 1 ones
                for (int i = aliceIndex + 1; i < n && onesPicked < k; i++) {
                    if (nums[i] == 1) {
                        // If we can reach this one without making any changes, do so
                        if (changesMade <= maxChanges) {
                            moves += i - aliceIndex;
                            aliceIndex = i;
                            onesPicked++;
                        } else {
                            break;
                        }
                    } else if (changesMade < maxChanges && onesPicked < k) {
                        // If we can make a change to get this one, do so
                        changesMade++;
                        moves += 1 + (i - aliceIndex);
                        aliceIndex = i;
                        onesPicked++;
                    }
                }

                for (int i = aliceIndex - 1; i >= 0 && onesPicked < k; i--) {
                    if (nums[i] == 1) {
                        // If we can reach this one without making any changes, do so
                        if (changesMade <= maxChanges) {
                            moves += aliceIndex - i;
                            aliceIndex = i;
                            onesPicked++;
                        } else {
                            break;
                        }
                    } else if (changesMade < maxChanges && onesPicked < k) {
                        // If we can make a change to get this one, do so
                        changesMade++;
                        moves += 1 + (aliceIndex - i);
                        aliceIndex = i;
                        onesPicked++;
                    }
                }

                if (onesPicked == k) {
                    minMoves = Math.min(minMoves, moves);
                }
            }
        }

        return minMoves == Long.MAX_VALUE ? -1 : minMoves;
    }
}

