public class Solution {
    public long[] countOfPairs(int n, int x, int y) {
        long[] result = new long[n];

        // Create an adjacency list to represent the graph
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            graph.add(new ArrayList<>());
        }

        // Add edges between consecutive houses
        for (int i = 1; i < n; i++) {
            graph.get(i).add(i + 1);
            graph.get(i + 1).add(i);
        }

        // Add an edge between x and y
        if (x != y) {
            graph.get(x).add(y);
            graph.get(y).add(x);
        }

        // Perform BFS for each house to find the minimum distance to all other houses
        for (int i = 1; i <= n; i++) {
            boolean[] visited = new boolean[n + 1];
            Queue<int[]> queue = new LinkedList<>();
            queue.offer(new int[] {i, 0});
            visited[i] = true;

            while (!queue.isEmpty()) {
                int[] current = queue.poll();
                int house = current[0];
                int distance = current[1];

                if (distance > 0) {
                    result[distance - 1]++;
                }

                for (int neighbor : graph.get(house)) {
                    if (!visited[neighbor]) {
                        visited[neighbor] = true;
                        queue.offer(new int[] {neighbor, distance + 1});
                    }
                }
            }
        }

        return result;
    }
}

