public class Solution {
    public int[] stringIndices(String[] wordsContainer, String[] wordsQuery) {
        int[] result = new int[wordsQuery.length];

        for (int i = 0; i < wordsQuery.length; i++) {
            int maxLength = -1;
            int minLength = Integer.MAX_VALUE;
            int minIndex = -1;

            for (int j = 0; j < wordsContainer.length; j++) {
                String queryWord = wordsQuery[i];
                String containerWord = wordsContainer[j];

                int commonSuffixLength = getCommonSuffixLength(queryWord, containerWord);

                if (commonSuffixLength > maxLength) {
                    maxLength = commonSuffixLength;
                    minLength = containerWord.length();
                    minIndex = j;
                } else if (commonSuffixLength == maxLength && containerWord.length() < minLength) {
                    minLength = containerWord.length();
                    minIndex = j;
                }
            }

            result[i] = minIndex;
        }

        return result;
    }

    private int getCommonSuffixLength(String word1, String word2) {
        int length1 = word1.length();
        int length2 = word2.length();
        int minLength = Math.min(length1, length2);

        for (int i = 0; i < minLength; i++) {
            if (word1.charAt(length1 - 1 - i) != word2.charAt(length2 - 1 - i)) {
                return i;
            }
        }

        return minLength;
    }
}

