public class Solution {
    public String[] shortestSubstrings(String[] arr) {
        int n = arr.length;
        String[] answer = new String[n];

        for (int i = 0; i < n; i++) {
            Set<String> substrings = new HashSet<>();
            List<String> uniqueSubstrings = new ArrayList<>();

            // Generate all possible substrings of the current string
            for (int j = 1; j <= arr[i].length(); j++) {
                for (int k = 0; k <= arr[i].length() - j; k++) {
                    String substring = arr[i].substring(k, k + j);
                    substrings.add(substring);

                    // Check if the substring is unique
                    boolean isUnique = true;
                    for (int l = 0; l < n; l++) {
                        if (l != i && arr[l].contains(substring)) {
                            isUnique = false;
                            break;
                        }
                    }

                    if (isUnique) {
                        uniqueSubstrings.add(substring);
                    }
                }
            }

            // If no unique substring exists, set the answer to an empty string
            if (uniqueSubstrings.isEmpty()) {
                answer[i] = "";
            } else {
                // Find the lexicographically smallest unique substring
                Collections.sort(uniqueSubstrings);
                int minLength = Integer.MAX_VALUE;
                String shortestSubstring = "";

                for (String substring : uniqueSubstrings) {
                    if (substring.length() < minLength) {
                        minLength = substring.length();
                        shortestSubstring = substring;
                    }
                }

                answer[i] = shortestSubstring;
            }
        }

        return answer;
    }
}

