public class Solution {
    public long maximumStrength(int[] nums, int k) {
        int n = nums.length;
        long[] prefixSum = new long[n + 1];

        // Calculate the prefix sum of the array
        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] + nums[i];
        }

        long maxStrength = Long.MIN_VALUE;

        // Iterate over all possible subarray lengths
        for (int x = 1; x <= n; x++) {
            long strength = 0;

            // Calculate the sum of each subarray and update the strength
            for (int i = 1; i <= x; i++) {
                int start = i - 1;
                int end = x - 1 + i;

                if (end > n) break;

                long sum = prefixSum[end] - prefixSum[start];
                strength += ((i % 2 == 1) ? 1 : -1) * sum * (x - i + 1);
            }

            // Update the maximum strength
            maxStrength = Math.max(maxStrength, strength);
        }

        return maxStrength;
    }
}

