import java.util.Arrays;
public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int sumOfPowers(int[] nums, int k) {
        Arrays.sort(nums);
        long res = 0;
        for (int i = 0; i <= nums.length - k; i++) {
            int minDiff = Integer.MAX_VALUE;
            for (int j = i + 1; j < i + k; j++) {
                minDiff = Math.min(minDiff, nums[j] - nums[j - 1]);
            }
            res += minDiff;
        }
        return (int) (res % MOD);
    }

    public int sumOfPowersOptimized(int[] nums, int k) {
        Arrays.sort(nums);
        long res = 0;
        for (int mask = 0; mask < (1 << nums.length); mask++) {
            if (Integer.bitCount(mask) == k) {
                int minDiff = Integer.MAX_VALUE;
                int prev = -1;
                for (int i = 0; i < nums.length; i++) {
                    if ((mask & (1 << i)) != 0) {
                        if (prev != -1) {
                            minDiff = Math.min(minDiff, nums[i] - prev);
                        }
                        prev = nums[i];
                    }
                }
                res += minDiff;
            }
        }
        return (int) (res % MOD);
    }

    public int sumOfPowersOptimizedFurther(int[] nums, int k) {
        Arrays.sort(nums);
        long[][] dp = new long[nums.length + 1][k + 1];
        for (int i = 0; i <= nums.length; i++) {
            dp[i][0] = 0;
        }
        for (int i = 1; i <= nums.length; i++) {
            for (int j = 1; j <= Math.min(i, k); j++) {
                long minDiff = Long.MAX_VALUE;
                for (int l = i - 1; l >= i - j; l--) {
                    minDiff = Math.min(minDiff, nums[i - 1] - nums[l]);
                }
                dp[i][j] = (dp[i - 1][j] + minDiff) % MOD;
            }
        }
        return (int) dp[nums.length][k];
    }

}

