                left++;
            }

            maxLength = Math.max(maxLength, right - left + 1);
        }

        return maxLength;
    }

    private boolean hasMoreThanTwoOccurrences(Map<Character, Integer> charCountMap) {
        for (int count : charCountMap.values()) {
            if (count > 2) {
                return true;
            }
        }
        return false;
    }
}

