        // Check if the sides can form a triangle
        if (a + b <= c || a + c <= b || b + c <= a) {
            return "none";
        }

        // Check for equilateral triangle
        if (a == b && b == c) {
            return "equilateral";
        }

        // Check for isosceles triangle
        if (a == b || a == c || b == c) {
            return "isosceles";
        }

        // If none of the above conditions are met, it's a scalene triangle
        return "scalene";
    }
}

