public class Solution {
    public long largestSquareArea(int[][] bottomLeft, int[][] topRight) {
        long maxArea = 0;

        for (int i = 0; i < bottomLeft.length; i++) {
            for (int j = i + 1; j < bottomLeft.length; j++) {
                // Calculate the intersection of two rectangles
                int x1 = Math.max(bottomLeft[i][0], bottomLeft[j][0]);
                int y1 = Math.min(topRight[i][1], topRight[j][1]);
                int x2 = Math.min(topRight[i][0], topRight[j][0]);
                int y2 = Math.max(bottomLeft[i][1], bottomLeft[j][1]);

                // Check if the rectangles intersect
                if (x1 < x2 && y1 > y2) {
                    // Calculate the side length of the largest square that can fit in the intersection
                    long sideLength = Math.min(x2 - x1, y1 - y2);

                    // Update the maximum area
                    maxArea = Math.max(maxArea, sideLength * sideLength);
                }
            }
        }

        return maxArea;
    }
}

