// #Medium #Array #Depth_First_Search #Tree #Binary_Tree
// #2022_05_26_Time_40_ms_(93.75%)_Space_92.9_MB_(71.71%)
public class Solution {
    public int countHighestScoreNodes(int[] parents) {
        int n = parents.length;
        List<List<Integer>> children = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            children.add(new ArrayList<>());
        }

        for (int i = 1; i < n; i++) {
            children.get(parents[i]).add(i);
        }

        long[] scores = new long[n];
        int maxScoreCount = 0;
        long maxScore = Long.MIN_VALUE;

        dfs(children, scores, 0);

        for (long score : scores) {
            if (score > maxScore) {
                maxScore = score;
                maxScoreCount = 1;
            } else if (score == maxScore) {
                maxScoreCount++;
            }
        }

        return maxScoreCount;
    }

    private long dfs(List<List<Integer>> children, long[] scores, int node) {
        long size = 1;

        for (int child : children.get(node)) {
            size += dfs(children, scores, child);
        }

        if (node == 0) {
            scores[node] = 1;
        } else {
            long score = 1;
            for (int child : children.get(node)) {
                score *= dfsSize(child, children);
            }
            score *= Math.max(1, children.size() - size);
            scores[node] = score;
        }

        return size;
    }

    private long dfsSize(int node, List<List<Integer>> children) {
        if (children.get(node).isEmpty()) {
            return 1;
        } else {
            long size = 1;
            for (int child : children.get(node)) {
                size += dfsSize(child, children);
            }
            return size;
        }
    }
}

