// #2022_06_21_Time_14_ms_(53.97%)_Space_126.8_MB_(25.40%)
public class Solution {
    public boolean stoneGameIX(int[] stones) {
        int count0 = 0, count1 = 0, count2 = 0;
        for (int x : stones) {
            int remainder = x % 3;
            if (remainder == 0) {
                count0++;
            } else if (remainder == 1) {
                count1++;
            } else {
                count2++;
            }
        }

        boolean aliceWins = false;

        // If there are no stones with a value divisible by 3, Alice wins if and only if the number of stones with remainder 1 is not equal to the number of stones with remainder 2.
        if (count0 == 0) {
            aliceWins = count1 != count2;
        } else {
            // If there are stones with a value divisible by 3, Alice wins if and only if she can make the sum of the values of all removed stones not divisible by 3 after her turn.
            // This happens when the number of stones with remainder 1 is equal to the number of stones with remainder 2 plus or minus one (depending on whether a stone with value divisible by 3 was removed).
            aliceWins = count0 % 2 == 1 && ((count1 - count2) * (count1 - count2 + 1) > 0 || (count2 - count1) * (count2 - count1 + 1) > 0);
        }

        return aliceWins;
    }
}

