// #Hard #Graph #Union_Find #2022_05_29_Time_102_ms_(55.25%)_Space_54.4_MB_(55.25%)
public class Solution {
    public boolean[] friendRequests(int n, int[][] restrictions, int[][] requests) {
        UnionFind uf = new UnionFind(n);
        boolean[] result = new boolean[requests.length];

        for (int i = 0; i < requests.length; i++) {
            int u = requests[i][0];
            int v = requests[i][1];

            // Check whether the current request will violate any restriction or not
            boolean isValidRequest = true;
            for (int[] restriction : restrictions) {
                int x = restriction[0];
                int y = restriction[1];

                if ((uf.find(u) == uf.find(x) && uf.find(v) == uf.find(y)) || 
                    (uf.find(u) == uf.find(y) && uf.find(v) == uf.find(x))) {
                    isValidRequest = false;
                    break;
                }
            }

            result[i] = isValidRequest;

            if (isValidRequest) {
                // Union
                uf.union(u, v);
            }
        }

        return result;
    }

    private static class UnionFind {
        int[] parent;

        public UnionFind(int n) {
            parent = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        public int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        public void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);

            if (rootX != rootY) {
                parent[rootX] = rootY;
            }
        }
    }
}

