public class Solution {
    public boolean placeWordInCrossword(char[][] board, String word) {
        int m = board.length;
        int n = board[0].length;

        // Check horizontal placement from left to right
        for (int i = 0; i < m; i++) {
            for (int j = 0; j <= n - word.length(); j++) {
                if (canPlaceHorizontally(board, word, i, j)) {
                    return true;
                }
            }
        }

        // Check horizontal placement from right to left
        String reversedWord = new StringBuilder(word).reverse().toString();
        for (int i = 0; i < m; i++) {
            for (int j = 0; j <= n - word.length(); j++) {
                if (canPlaceHorizontally(board, reversedWord, i, j)) {
                    return true;
                }
            }
        }

        // Check vertical placement from top to bottom
        for (int i = 0; i <= m - word.length(); i++) {
            for (int j = 0; j < n; j++) {
                if (canPlaceVertically(board, word, i, j)) {
                    return true;
                }
            }
        }

        // Check vertical placement from bottom to top
        char[] arr = word.toCharArray();
        String reversedWord2 = new StringBuilder(word).reverse().toString();
        for (int i = 0; i <= m - word.length(); i++) {
            for (int j = 0; j < n; j++) {
                if (canPlaceVertically(board, reversedWord2, i, j)) {
                    return true;
                }
            }
        }

        return false;
    }

    private boolean canPlaceHorizontally(char[][] board, String word, int row, int col) {
        // Check if the cell before and after the word is not empty or blocked
        if (col > 0 && board[row][col - 1] != '#') {
            return false;
        }
        if (col + word.length() < board[0].length && board[row][col + word.length()] != '#' && board[row][col + word.length()] != ' ') {
            return false;
        }

        // Check each character of the word
        for (int i = 0; i < word.length(); i++) {
            if (board[row][col + i] == '#') {
                return false;
            }
            if (board[row][col + i] != ' ' && board[row][col + i] != word.charAt(i)) {
                return false;
            }
        }

        return true;
    }

    private boolean canPlaceVertically(char[][] board, String word, int row, int col) {
        // Check if the cell before and after the word is not empty or blocked
        if (row > 0 && board[row - 1][col] != '#') {
            return false;
        }
        if (row + word.length() < board.length && board[row + word.length()][col] != '#' && board[row + word.length()][col] != ' ') {
            return false;
        }

        // Check each character of the word
        for (int i = 0; i < word.length(); i++) {
            if (board[row + i][col] == '#') {
                return false;
            }
            if (board[row + i][col] != ' ' && board[row + i][col] != word.charAt(i)) {
                return false;
            }
        }

        return true;
    }
}

