// #Hard #Array #String #Simulation #Backtracking
// #2024_05_13_Time_195_ms_(41.18%)_Space_44.8_MB_(47.06%)
import java.util.*;

public class Solution {
    // 0: rook, queen, bishop
    public int countCombinations(String[] pieces, int[][] positions) {
        Set<String> visited = new HashSet<>();
        return backtrack(pieces, positions, visited);
    }

    private int backtrack(String[] pieces, int[][] positions, Set<String> visited) {
        if (isInvalidPosition(positions)) {
            return 0;
        }

        String currentPosition = getPositionString(positions);
        if (visited.contains(currentPosition)) {
            return 0;
        }
        visited.add(currentPosition);

        if (allPiecesAtDestination(pieces, positions)) {
            return 1;
        }

        int count = 0;
        for (int i = 0; i < pieces.length; i++) {
            String pieceType = pieces[i];
            int[] position = positions[i];

            List<int[]> possibleMoves = getPossibleMoves(pieceType, position);
            for (int[] move : possibleMoves) {
                positions[i] = move;
                count += backtrack(pieces, positions, visited);
                positions[i] = position; // backtrack
            }
        }

        visited.remove(currentPosition);
        return count;
    }

    private boolean isInvalidPosition(int[][] positions) {
        Set<String> set = new HashSet<>();
        for (int[] position : positions) {
            String posString = position[0] + "," + position[1];
            if (!set.add(posString)) {
                return true; // duplicate position
            }
        }
        return false;
    }

    private boolean allPiecesAtDestination(String[] pieces, int[][] positions) {
        for (int i = 0; i < pieces.length; i++) {
            String pieceType = pieces[i];
            int[] position = positions[i];

            List<int[]> possibleMoves = getPossibleMoves(pieceType, position);
            if (!possibleMoves.isEmpty()) {
                return false;
            }
        }
        return true;
    }

    private String getPositionString(int[][] positions) {
        StringBuilder sb = new StringBuilder();
        for (int[] position : positions) {
            sb.append(position[0]).append(",").append(position[1]).append(";");
        }
        return sb.toString();
    }

    private List<int[]> getPossibleMoves(String pieceType, int[] position) {
        List<int[]> possibleMoves = new ArrayList<>();

        if (pieceType.equals("rook")) {
            // up
            if (position[0] > 1) {
                possibleMoves.add(new int[]{position[0] - 1, position[1]});
            }
            // down
            if (position[0] < 8) {
                possibleMoves.add(new int[]{position[0] + 1, position[1]});
            }
            // left
            if (position[1] > 1) {
                possibleMoves.add(new int[]{position[0], position[1] - 1});
            }
            // right
            if (position[1] < 8) {
                possibleMoves.add(new int[]{position[0], position[1] + 1});
            }
        } else if (pieceType.equals("queen")) {
            // up
            if (position[0] > 1) {
                possibleMoves.add(new int[]{position[0] - 1, position[1]});
            }
            // down
            if (position[0] < 8) {
                possibleMoves.add(new int[]{position[0] + 1, position[1]});
            }
            // left
            if (position[1] > 1) {
                possibleMoves.add(new int[]{position[0], position[1] - 1});
            }
            // right
            if (position[1] < 8) {
                possibleMoves.add(new int[]{position[0], position[1] + 1});
            }
            // up-left
            if (position[0] > 1 && position[1] > 1) {
                possibleMoves.add(new int[]{position[0] - 1, position[1] - 1});
            }
            // up-right
            if (position[0] > 1 && position[1] < 8) {
                possibleMoves.add(new int[]{position[0] - 1, position[1] + 1});
            }
            // down-left
            if (position[0] < 8 && position[1] > 1) {
                possibleMoves.add(new int[]{position[0] + 1, position[1] - 1});
            }
            // down-right
            if (position[0] < 8 && position[1] < 8) {
                possibleMoves.add(new int[]{position[0] + 1, position[1] + 1});
            }
        } else if (pieceType.equals("bishop")) {
            // up-left
            if (position[0] > 1 && position[1] > 1) {
                possibleMoves.add(new int[]{position[0] - 1, position[1] - 1});
            }
            // up-right
            if (position[0] > 1 && position[1] < 8) {
                possibleMoves.add(new int[]{position[0] - 1, position[1] + 1});
            }
            // down-left
            if (position[0] < 8 && position[1] > 1) {
                possibleMoves.add(new int[]{position[0] + 1, position[1] - 1});
            }
            // down-right
            if (position[0] < 8 && position[1] < 8) {
                possibleMoves.add(new int[]{position[0] + 1, position[1] + 1});
            }
        }

        return possibleMoves;
    }
}

