public class Solution {
    public int minimizedMaximum(int n, int[] q) {
        int left = 1;
        int right = Integer.MIN_VALUE;

        for (int quantity : q) {
            right = Math.max(right, quantity);
        }

        while (left < right) {
            int mid = left + (right - left) / 2;
            if (canDistribute(q, n, mid)) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }

        return left;
    }

    private boolean canDistribute(int[] q, int n, int maxQuantity) {
        int storesNeeded = 0;
        for (int quantity : q) {
            storesNeeded += (quantity - 1) / maxQuantity + 1;
        }
        return storesNeeded <= n;
    }
}

