public class Solution {
    public int sumOfBeauties(int[] nums) {
        int beautySum = 0;

        for (int i = 1; i < nums.length - 1; i++) {
            boolean isMaxMin = true;
            boolean isLocalMax = false;

            // Check if nums[i] is greater than all previous elements and smaller than all next elements
            for (int j = 0; j < i; j++) {
                if (nums[j] >= nums[i]) {
                    isMaxMin = false;
                    break;
                }
            }

            if (!isMaxMin) {
                // Check if nums[i] is a local maximum
                if (nums[i - 1] < nums[i] && nums[i] > nums[i + 1]) {
                    isLocalMax = true;
                }
            } else {
                for (int k = i + 1; k < nums.length; k++) {
                    if (nums[k] <= nums[i]) {
                        isMaxMin = false;
                        break;
                    }
                }
            }

            // Calculate the beauty of nums[i]
            int beauty = 0;
            if (isMaxMin) {
                beauty = 2;
            } else if (isLocalMax) {
                beauty = 1;
            }

            beautySum += beauty;
        }

        return beautySum;
    }
}

