public class Solution {
    public int minimumDeletions(int[] nums) {
        int minIndex = 0, maxIndex = 0;
        for (int i = 1; i < nums.length; i++) {
            if (nums[i] < nums[minIndex]) {
                minIndex = i;
            }
            if (nums[i] > nums[maxIndex]) {
                maxIndex = i;
            }
        }

        int minDeletionsFromFront = Math.min(minIndex, maxIndex) + 1;
        int minDeletionsFromBack = nums.length - Math.max(minIndex, maxIndex);

        return Math.min(Math.min(minDeletionsFromFront + minDeletionsFromBack, 
                Math.min(minIndex + 1 + nums.length - maxIndex, maxIndex + 1 + nums.length - minIndex)), 
                Math.min(nums.length - minIndex, nums.length - maxIndex) + 1);
    }
}

