// #2022_05_26_Time_6_ms_(85.46%)_Space_42.3_MB_(94.75%)
import java.util.*;

public class Solution {
    public int[] maxSubsequence(int[] nums, int k) {
        // Create priority queue with min priority queue so that min element will be removed first,
        // with index
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);

        // Add those unique index in a set
        for (int i = 0; i < nums.length; i++) {
            pq.offer(new int[] {nums[i], i});
            if (pq.size() > k) {
                pq.poll();
            }
        }

        Set<Integer> set = new HashSet<>();
        while (!pq.isEmpty()) {
            set.add(pq.poll()[1]);
        }

        // Loop from 0 to n-1 and add element in result if set contains those index
        int[] result = new int[k];
        int j = 0;
        for (int i = 0; i < nums.length; i++) {
            if (set.contains(i)) {
                result[j++] = nums[i];
            }
        }

        return result;
    }
}

