public class Solution {
    public int maximalPathQuality(int[] values, int[][] edges, int maxTime) {
        int n = values.length;
        List<int[]>[] graph = new ArrayList[n];

        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }

        for (int[] edge : edges) {
            int u = edge[0], v = edge[1], time = edge[2];
            graph[u].add(new int[]{v, time});
            graph[v].add(new int[]{u, time});
        }

        boolean[] visited = new boolean[n];
        int maxQuality = 0;

        dfs(0, values[0], maxTime, graph, visited, values, maxQuality);

        return maxQuality;
    }

    private void dfs(int node, int currentSum, int remainingTime, List<int[]>[] graph, boolean[] visited, int[] values, int maxQuality) {
        if (node == 0) {
            maxQuality = Math.max(maxQuality, currentSum);
        }

        for (int[] neighbor : graph[node]) {
            int nextNode = neighbor[0], time = neighbor[1];

            if (remainingTime - time >= 0) {
                boolean wasVisited = visited[nextNode];

                if (!wasVisited) {
                    visited[nextNode] = true;
                    dfs(nextNode, currentSum + values[nextNode], remainingTime - time, graph, visited, values, maxQuality);
                    visited[nextNode] = false;
                } else {
                    dfs(nextNode, currentSum, remainingTime - time, graph, visited, values, maxQuality);
                }
            }
        }
    }

    public Node(int i, int time) {
        // This class is not used in the solution
    }

    public static void main(String[] args) {
        Solution solution = new Solution();
        int[] values = {5, 10, 15, 20};
        int[][] edges = {{0, 1, 10}, {1, 2, 10}, {0, 3, 10}};
        int maxTime = 30;

        System.out.println(solution.maximalPathQuality(values, edges, maxTime));
    }
}

