// #Hard #Array #Hash_Table #Prefix_Sum #Counting #Enumeration
// #2022_05_25_Time_172_ms_(100.00%)_Space_75.5_MB_(65.10%)
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Solution {
    public int waysToPartition(int[] nums, int k) {
        int n = nums.length;
        int maxWays = 0;

        // Calculate prefix sum
        long[] prefixSum = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] + nums[i];
        }

        // Check if we can get a valid partition without changing any element
        int waysWithoutChange = 0;
        for (int pivot = 1; pivot < n; pivot++) {
            long leftSum = prefixSum[pivot];
            long rightSum = prefixSum[n] - prefixSum[pivot];
            if (leftSum == rightSum) {
                waysWithoutChange++;
            }
        }

        // Try changing each element to k and check the number of valid partitions
        for (int i = 0; i < n; i++) {
            int temp = nums[i];
            nums[i] = k;

            // Calculate prefix sum after changing the current element
            long[] newPrefixSum = new long[n + 1];
            for (int j = 0; j < n; j++) {
                if (j == 0) {
                    newPrefixSum[j + 1] = nums[j];
                } else {
                    newPrefixSum[j + 1] = newPrefixSum[j] + nums[j];
                }
            }

            // Check the number of valid partitions after changing the current element
            int waysWithChange = 0;
            for (int pivot = 1; pivot < n; pivot++) {
                long leftSum = newPrefixSum[pivot];
                long rightSum = newPrefixSum[n] - newPrefixSum[pivot];
                if (leftSum == rightSum) {
                    waysWithChange++;
                }
            }

            // Update the maximum number of valid partitions
            maxWays = Math.max(maxWays, waysWithChange);

            // Revert the change
            nums[i] = temp;
        }

        return Math.max(maxWays, waysWithoutChange);
    }
}

