// #Medium #Array #Breadth_First_Search #2022_05_28_Time_97_ms_(64.14%)_Space_116.9_MB_(51.03%)
import java.util.*;

public class Solution {
    public int minimumOperations(int[] nums, int start, int goal) {
        Queue<int[]> queue = new LinkedList<>();
        Set<Integer> visited = new HashSet<>();

        queue.offer(new int[]{start, 0});
        visited.add(start);

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int x = current[0];
            int step = current[1];

            if (x == goal) return step;

            for (int num : nums) {
                int nextXPlus = x + num;
                int nextXMinus = x - num;
                int nextXXor = x ^ num;

                if (!visited.contains(nextXPlus) && 0 <= nextXPlus && nextXPlus <= 1000) {
                    queue.offer(new int[]{nextXPlus, step + 1});
                    visited.add(nextXPlus);
                }

                if (!visited.contains(nextXMinus) && 0 <= nextXMinus && nextXMinus <= 1000) {
                    queue.offer(new int[]{nextXMinus, step + 1});
                    visited.add(nextXMinus);
                }

                if (!visited.contains(nextXXor) && 0 <= nextXXor && nextXXor <= 1000) {
                    queue.offer(new int[]{nextXXor, step + 1});
                    visited.add(nextXXor);
                }
            }
        }

        return -1;
    }
}

