import java.util.*;

public class Solution {
    public String longestSubsequenceRepeatedK(String s, int k) {
        int n = s.length();
        String res = "";

        for (int len = 1; len <= n / k; len++) {
            for (int i = 0; i <= n - len; i++) {
                String sub = s.substring(i, i + len);

                if (isRepeatedKTimes(s, sub, k) && (sub.length() > res.length() || 
                    (sub.length() == res.length() && sub.compareTo(res) > 0))) {
                    res = sub;
                }
            }
        }

        return res;
    }

    private boolean isRepeatedKTimes(String s, String sub, int k) {
        StringBuilder target = new StringBuilder();
        for (int i = 0; i < k; i++) {
            target.append(sub);
        }

        int j = 0;
        for (char c : s.toCharArray()) {
            if (j < target.length() && c == target.charAt(j)) {
                j++;
            }
        }

        return j == target.length();
    }
}

