// #Hard #String #Dynamic_Programming #2022_05_29_Time_354_ms_(69.39%)_Space_209.4_MB_(51.21%)
import java.util.ArrayList;
import java.util.List;

public class Solution {
    public boolean possiblyEquals(String s1, String s2) {
        int m = s1.length(), n = s2.length();
        return dfs(s1, 0, s2, 0, 0);
    }

    private boolean dfs(String s1, int i, String s2, int j, int diff) {
        if (i == s1.length() && j == s2.length()) return diff == 0;
        if (diff < 0) return false;

        for (int k = 1; k <= (s1.length() - i); k++) {
            String subStr = s1.substring(i, i + k);
            boolean isDigit = false;
            int num = 0;
            for (char c : subStr.toCharArray()) {
                if (Character.isDigit(c)) {
                    isDigit = true;
                    num = num * 10 + (c - '0');
                }
            }

            if (!isDigit) {
                boolean res = dfs(s1, i + k, s2, j, diff);
                if (res) return true;
            } else {
                boolean res = dfs(s1, i + k, s2, j, diff - num);
                if (res) return true;
            }
        }

        for (int k = 1; k <= (s2.length() - j); k++) {
            String subStr = s2.substring(j, j + k);
            boolean isDigit = false;
            int num = 0;
            for (char c : subStr.toCharArray()) {
                if (Character.isDigit(c)) {
                    isDigit = true;
                    num = num * 10 + (c - '0');
                }
            }

            if (!isDigit) {
                boolean res = dfs(s1, i, s2, j + k, diff);
                if (res) return true;
            } else {
                boolean res = dfs(s1, i, s2, j + k, diff + num);
                if (res) return true;
            }
        }

        return false;
    }
}

