import java.util.*;

public class Solution {
    public int scoreOfStudents(String s, int[] answers) {
        Set<Integer> set = new HashSet<>();
        dfs(s, 0, 0, set);

        int correctAnswer = calculateCorrectAnswer(s);
        int sum = 0;

        for (int answer : answers) {
            if (answer == correctAnswer) {
                sum += 5;
            } else if (set.contains(answer)) {
                sum += 2;
            }
        }

        return sum;
    }

    private void dfs(String s, int index, int value, Set<Integer> set) {
        if (index >= s.length()) {
            set.add(value);
            return;
        }

        char c = s.charAt(index);
        if (Character.isDigit(c)) {
            dfs(s, index + 1, value * 10 + (c - '0'), set);
        } else if (c == '+') {
            dfs(s, index + 1, value, set);
        } else if (c == '*') {
            int num = 0;
            for (int i = index + 1; i < s.length(); i++) {
                char d = s.charAt(i);
                if (!Character.isDigit(d)) break;
                num = num * 10 + (d - '0');
            }
            dfs(s, index + String.valueOf(num).length() + 1, value * num, set);
        }
    }

    private int calculateCorrectAnswer(String s) {
        int result = 0;
        boolean hasMultiply = false;

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isDigit(c)) {
                int num = 0;
                while (i < s.length() && Character.isDigit(s.charAt(i))) {
                    num = num * 10 + (s.charAt(i) - '0');
                    i++;
                }
                i--;

                if (hasMultiply) {
                    result += num;
                } else {
                    result *= num;
                    hasMultiply = true;
                }
            } else if (c == '+') {
                hasMultiply = false;
            }
        }

        return result;
    }
}

