public class Solution {
    public int[] missingRolls(int[] rolls, int mean, int n) {
        int m = rolls.length;
        long totalSum = (long)mean * (m + n);

        // Calculate the sum of the given observations
        long givenSum = 0;
        for (int roll : rolls) {
            givenSum += roll;
        }

        // Calculate the sum of the missing observations
        long missingSum = totalSum - givenSum;

        if (missingSum < n || missingSum > 6 * n) {
            return new int[0];
        }

        int[] result = new int[n];
        int quotient = (int)(missingSum / n);
        int remainder = (int)(missingSum % n);

        for (int i = 0; i < n; i++) {
            if (i < remainder) {
                result[i] = quotient + 1;
            } else {
                result[i] = quotient;
            }
        }

        return result;
    }
}

