                if (uniqueVowels == 5) count++;
            }
        }
        return count;
    }

    private boolean isVowel(char c) {
        return "aeiou".indexOf(c) != -1;
    }

    private int getVowelIndex(char c) {
        switch (c) {
            case 'a':
                return 0;
            case 'e':
                return 1;
            case 'i':
                return 2;
            case 'o':
                return 3;
            default:
                return 4;
        }
    }
}

