// #Hard #Math #Enumeration #2022_05_29_Time_759_ms_(81.69%)_Space_116.6_MB_(61.97%)
import java.util.ArrayList;
import java.util.List;

public class Solution {
    public long kMirror(int k, int n) {
        List<Long> list = new ArrayList<>();
        for (long num = 1; ; num++) {
            String base10Str = Long.toString(num);
            if (isPalindrome(base10Str)) {
                String baseKStr = convertBase(num, k);
                if (!baseKStr.startsWith("0") && isPalindrome(baseKStr)) {
                    list.add(num);
                }
            }
            if (list.size() == n) break;
        }

        long sum = 0;
        for (long num : list) {
            sum += num;
        }
        return sum;
    }

    private boolean isPalindrome(String str) {
        int left = 0, right = str.length() - 1;
        while (left < right) {
            if (str.charAt(left++) != str.charAt(right--)) {
                return false;
            }
        }
        return true;
    }

    private String convertBase(long num, int base) {
        StringBuilder sb = new StringBuilder();
        while (num > 0) {
            long remainder = num % base;
            sb.insert(0, remainder);
            num /= base;
        }
        return sb.toString();
    }
}

