// #Medium #String #Dynamic_Programming #Bit_Manipulation #Backtracking #Bitmask
// #2022_05_22_Time_69_ms_(89.94%)_Space_53.8_MB_(41.42%)
import java.util.*;

public class Solution {
    public int maxProduct(String s) {
        int n = s.length();
        int[][] dp = new int[n][n];

        for (int i = 0; i < n; i++) {
            dp[i][i] = 1;
        }

        for (int length = 2; length <= n; length++) {
            for (int start = 0; start <= n - length; start++) {
                int end = start + length - 1;

                if (s.charAt(start) == s.charAt(end)) {
                    dp[start][end] = (length > 2 ? dp[start + 1][end - 1] : 0) + 2;
                } else {
                    dp[start][end] = Math.max(dp[start + 1][end], dp[start][end - 1]);
                }
            }
        }

        int maxProduct = 0;

        for (int mask = 1; mask < (1 << n); mask++) {
            List<Integer> indices = new ArrayList<>();

            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    indices.add(i);
                }
            }

            boolean isPalindrome = true;

            for (int i = 0, j = indices.size() - 1; i < j; i++, j--) {
                if (s.charAt(indices.get(i)) != s.charAt(indices.get(j))) {
                    isPalindrome = false;
                    break;
                }
            }

            if (!isPalindrome) {
                continue;
            }

            int length1 = indices.size();

            for (int otherMask = 1; otherMask < (1 << n); otherMask++) {
                if ((mask & otherMask) != 0) {
                    continue;
                }

                List<Integer> otherIndices = new ArrayList<>();

                for (int i = 0; i < n; i++) {
                    if ((otherMask & (1 << i)) != 0) {
                        otherIndices.add(i);
                    }
                }

                boolean isOtherPalindrome = true;

                for (int i = 0, j = otherIndices.size() - 1; i < j; i++, j--) {
                    if (s.charAt(otherIndices.get(i)) != s.charAt(otherIndices.get(j))) {
                        isOtherPalindrome = false;
                        break;
                    }
                }

                if (!isOtherPalindrome) {
                    continue;
                }

                int length2 = otherIndices.size();

                maxProduct = Math.max(maxProduct, length1 * length2);
            }
        }

        return maxProduct;
    }
}

