import java.util.*;

public class Solution {
    public int[] smallestMissingValueSubtree(int[] parents, int[] nums) {
        int n = parents.length;
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }

        for (int i = 1; i < n; i++) {
            graph.get(parents[i]).add(i);
        }

        int[] ans = new int[n];
        boolean[] seen = new boolean[100001];

        dfs(0, graph, nums, ans, seen);

        return ans;
    }

    private void dfs(int node, List<List<Integer>> graph, int[] nums, int[] ans, boolean[] seen) {
        if (nums[node] <= 100000) {
            seen[nums[node]] = true;
        }

        for (int child : graph.get(node)) {
            dfs(child, graph, nums, ans, seen);
        }

        int smallestMissingValue = findSmallestMissing(seen);
        ans[node] = smallestMissingValue;

        if (nums[node] <= 100000) {
            seen[nums[node]] = false;
        }
    }

    private int findSmallestMissing(boolean[] seen) {
        for (int i = 1; i < seen.length; i++) {
            if (!seen[i]) {
                return i;
            }
        }

        return seen.length;
    }
}

