// #Medium #Linked_List #2022_05_29_Time_9_ms_(62.36%)_Space_270.4_MB_(37.64%)
import com_github_leetcode.ListNode;

public class Solution {
    public ListNode reverseEvenLengthGroups(ListNode head) {
        if (head == null || head.next == null) return head;

        int groupSize = 1;
        ListNode dummy = new ListNode(0);
        dummy.next = head;
        ListNode prevTail = dummy;

        while (prevTail.next != null) {
            int count = 0;
            ListNode curr = prevTail.next;

            // Count the number of nodes in the current group
            ListNode temp = curr;
            while (temp != null && count < groupSize) {
                temp = temp.next;
                count++;
            }

            if (count % 2 == 0) {
                // Reverse the nodes in the current group
                ListNode prev = null;
                ListNode next = null;
                for (int i = 0; i < count; i++) {
                    next = curr.next;
                    curr.next = prev;
                    prev = curr;
                    curr = next;
                }

                // Update the links between groups
                prevTail.next = prev;
                temp = prevTail.next;
                while (temp.next != null) {
                    temp = temp.next;
                }
                temp.next = curr;
            } else {
                // Move to the next group without reversing
                for (int i = 0; i < count; i++) {
                    prevTail = prevTail.next;
                }
            }

            groupSize++;
        }

        return dummy.next;
    }
}

