public class Solution {
    public int countValidWords(String sentence) {
        String[] words = sentence.split(" ");
        int validCount = 0;

        for (String word : words) {
            if (!word.isEmpty()) {
                boolean isValid = true;

                // Check if the word contains any digits
                if (word.matches(".*\\d.*")) {
                    isValid = false;
                }

                // Check if the word has more than one hyphen or punctuation mark
                int hyphenCount = countChar(word, '-');
                int punctuationCount = countChar(word, '!') + countChar(word, '.') + countChar(word, ',');
                if (hyphenCount > 1 || punctuationCount > 1) {
                    isValid = false;
                }

                // Check if the word has a hyphen that is not surrounded by lowercase characters
                for (int i = 0; i < word.length(); i++) {
                    char c = word.charAt(i);
                    if (c == '-') {
                        if (i == 0 || i == word.length() - 1) {
                            isValid = false;
                            break;
                        }
                        if (!Character.isLowerCase(word.charAt(i - 1)) || !Character.isLowerCase(word.charAt(i + 1))) {
                            isValid = false;
                            break;
                        }
                    }
                }

                // Check if the word has a punctuation mark that is not at the end
                for (int i = 0; i < word.length() - 1; i++) {
                    char c = word.charAt(i);
                    if (c == '!' || c == '.' || c == ',') {
                        isValid = false;
                        break;
                    }
                }

                // Check if the word contains any characters other than lowercase letters, hyphens, and punctuation marks
                for (char c : word.toCharArray()) {
                    if (!Character.isLowerCase(c) && c != '-' && c != '!' && c != '.' && c != ',') {
                        isValid = false;
                        break;
                    }
                }

                // If the word is valid, increment the count
                if (isValid) {
                    validCount++;
                }
            }
        }

        return validCount;
    }

    private int countChar(String str, char c) {
        int count = 0;
        for (char ch : str.toCharArray()) {
            if (ch == c) {
                count++;
            }
        }
        return count;
    }
}

