public class Solution {
    public int[][] validArrangement(int[][] pairs) {
        Map<Integer, List<int[]>> graph = new HashMap<>();
        for (int[] pair : pairs) {
            graph.computeIfAbsent(pair[0], k -> new LinkedList<>()).add(new int[]{pair[1]});
        }

        Queue<int[]> queue = new LinkedList<>();
        queue.offer(pairs[0]);

        List<int[]> result = new ArrayList<>();

        while (!queue.isEmpty()) {
            int[] currentPair = queue.poll();
            if (graph.containsKey(currentPair[1]) && !graph.get(currentPair[1]).isEmpty()) {
                queue.offer(new int[]{currentPair[0], graph.get(currentPair[1]).remove(0)[0]});
            } else {
                result.add(0, currentPair);
            }
        }

        return result.toArray(new int[result.size()][2]);
