public class Solution {
    public int[] nodesBetweenCriticalPoints(ListNode head) {
        ListNode dummy = new ListNode(0);
        dummy.next = head;
        ListNode prev = dummy, curr = head;

        int index = 1;
        int[] criticalPoints = new int[10000];
        int count = 0;

        while (curr != null && curr.next != null) {
            if ((prev.val < curr.val && curr.val > curr.next.val) || 
                (prev.val > curr.val && curr.val < curr.next.val)) {
                criticalPoints[count++] = index;
            }
            prev = curr;
            curr = curr.next;
            index++;
        }

        if (count < 2) return new int[] {-1, -1};

        int minDistance = Integer.MAX_VALUE;
        for (int i = 0; i < count - 1; i++) {
            minDistance = Math.min(minDistance, criticalPoints[i + 1] - criticalPoints[i]);
        }

        int maxDistance = criticalPoints[count - 1] - criticalPoints[0];

        return new int[] {minDistance, maxDistance};
    }
}

