public class Solution {
    public int countPyramids(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int[][] dp1 = new int[m][n];
        int[][] dp2 = new int[m][n];

        // Calculate the number of pyramidal plots
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    dp1[i][j] = Math.min(Math.min(i, j), Math.min(m - i - 1, n - j - 1)) + 1;
                }
            }
        }

        // Calculate the number of inverse pyramidal plots
        for (int i = m - 1; i >= 0; i--) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    dp2[i][j] = Math.min(Math.min(m - i - 1, j), Math.min(i, n - j - 1)) + 1;
                }
            }
        }

        // Calculate the total number of pyramidal and inverse pyramidal plots
        int count = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (dp1[i][j] > 1) {
                    count += dp1[i][j];
                }
                if (dp2[i][j] > 1) {
                    count += dp2[i][j];
                }
            }
        }

        return count;
    }
}

