// #2022_05_25_Time_30_ms_(76.29%)_Space_109.4_MB_(43.13%)
import com_github_leetcode.TreeNode;
import java.util.*;

public class Solution {
    public String getDirections(TreeNode root, int startValue, int destValue) {
        Map<Integer, List<int[]>> graph = new HashMap<>();
        buildGraph(root, null, graph);

        Queue<int[]> queue = new LinkedList<>();
        Set<Integer> visited = new HashSet<>();
        queue.offer(new int[]{startValue, ""});
        visited.add(startValue);

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            if (current[0] == destValue) {
                return current[1];
            }

            for (int[] neighbor : graph.get(current[0])) {
                if (!visited.contains(neighbor[0])) {
                    visited.add(neighbor[0]);
                    String direction = current[1] + getDirection(neighbor[1]);
                    queue.offer(new int[]{neighbor[0], direction});
                }
            }
        }

        return "";
    }

    private void buildGraph(TreeNode node, TreeNode parent, Map<Integer, List<int[]>> graph) {
        if (node == null) {
            return;
        }

        if (!graph.containsKey(node.val)) {
            graph.put(node.val, new ArrayList<>());
        }

        if (parent != null) {
            graph.get(parent.val).add(new int[]{node.val, 0});
            graph.get(node.val).add(new int[]{parent.val, 1});
        }

        buildGraph(node.left, node, graph);
        buildGraph(node.right, node, graph);
    }

    private String getDirection(int direction) {
        if (direction == 0) {
            return "L";
        } else if (direction == 1) {
            return "R";
        } else {
            return "U";
        }
    }
}

