// #Hard #String #Greedy #Stack #Monotonic_Stack
// #2022_05_25_Time_131_ms_(64.46%)_Space_72.3_MB_(46.99%)
public class Solution {
    public String smallestSubsequence(String s, int k, char letter, int repetition) {
        int n = s.length();
        int[] count = new int[26];
        for (char c : s.toCharArray()) {
            count[c - 'a']++;
        }

        StringBuilder sb = new StringBuilder();
        Stack<Character> stack = new Stack<>();
        int remaining = k;
        int letterCount = 0;

        for (int i = 0; i < n; i++) {
            while (!stack.isEmpty() && 
                   stack.peek() > s.charAt(i) && 
                   remaining > 0 && 
                   count[stack.peek() - 'a'] >= 1 && 
                   letterCount - (stack.peek() == letter ? 1 : 0) >= repetition) {
                char c = stack.pop();
                remaining++;
                letterCount -= c == letter ? 1 : 0;
            }

            if (remaining > 0) {
                if (s.charAt(i) == letter) {
                    letterCount++;
                }

                if (stack.isEmpty() || s.charAt(i) <= stack.peek()) {
                    stack.push(s.charAt(i));
                    remaining--;
                } else if (count[s.charAt(i) - 'a'] >= 1 && 
                           letterCount >= repetition) {
                    // do nothing
                }
            }

            count[s.charAt(i) - 'a']--;
        }

        while (!stack.isEmpty()) {
            sb.append(stack.pop());
        }

        return sb.reverse().toString();
    }
}

