public class Solution {
    public int secondMinimum(int n, int[][] edges, int time, int change) {
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            graph.add(new ArrayList<>());
        }

        for (int[] edge : edges) {
            graph.get(edge[0]).add(edge[1]);
            graph.get(edge[1]).add(edge[0]);
        }

        int[][] dist = new int[n + 1][2];
        for (int i = 0; i <= n; i++) {
            Arrays.fill(dist[i], Integer.MAX_VALUE);
        }

        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        dist[1][0] = 0;
        pq.offer(new int[] {0, 1});

        while (!pq.isEmpty()) {
            int[] curr = pq.poll();
            int d = curr[0];
            int node = curr[1];

            for (int neighbor : graph.get(node)) {
                int newD = d + time;
                if (newD % (2 * change) >= change) {
                    newD += 2 * change - (newD % (2 * change));
                }

                if (dist[neighbor][0] == Integer.MAX_VALUE) {
                    dist[neighbor][0] = newD;
                    pq.offer(new int[] {newD, neighbor});
                } else if (dist[neighbor][1] == Integer.MAX_VALUE && newD > dist[neighbor][0]) {
                    dist[neighbor][1] = newD;
                    pq.offer(new int[] {newD, neighbor});
                }
            }
        }

        return dist[n][1];
    }
}

