public class Solution {
    public boolean areNumbersAscending(String s) {
        String[] tokens = s.split(" ");
        int prevNumber = -1;

        for (String token : tokens) {
            if (token.matches("\\d+")) {
                int currentNumber = Integer.parseInt(token);
                if (currentNumber <= prevNumber) {
                    return false;
                }
                prevNumber = currentNumber;
            }
        }

        return true;
    }
}

