import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;

public class Solution {
    public int maxTaskAssign(int[] tasks, int[] workers, int pills, int strength) {
        Arrays.sort(tasks);
        Arrays.sort(workers);

        int low = 0;
        int high = Math.min(tasks.length, workers.length);

        while (low < high) {
            int mid = (low + high + 1) / 2;

            if (canAssign(mid, tasks, workers, pills, strength)) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }

        return low;
    }

    private boolean canAssign(int k, int[] tasks, int[] workers, int pills, int strength) {
        Deque<Integer> deque = new ArrayDeque<>();

        for (int i = k - 1; i >= 0; i--) {
            while (!deque.isEmpty() && workers[deque.peekLast()] + strength < tasks[i]) {
                deque.pollLast();
                pills--;
            }

            if (pills < 0) return false;

            if (workers[k - 1 - i] >= tasks[i]) continue;
            if (pills > 0) {
                pills--;
                continue;
            }
            if (!deque.isEmpty() && workers[deque.peekLast()] >= tasks[i]) {
                deque.pollLast();
                continue;
            }

            return false;
        }

        return true;
    }
}
